// ---- atlas-demos1.js ----
// ===== デモ（1）基本原則・イージング・スプリング・タイミング =====

// ---------- 共通ビュー：イージング（グラフ＋動く四角＋スペーシング表）----------
function easeView(g, t, fn, o = {}) {
  const gx = 22, gy = 30, gw = 124, gh = 128, Y = v => gy + gh - 22 - v * (gh - 44), X = x => gx + x * gw;
  rr(g, gx, gy, gw, gh, 6, null, K.grid, 1);
  ln(g, gx, Y(0), gx + gw, Y(0), K.grid, 1, [3, 3]); ln(g, gx, Y(1), gx + gw, Y(1), K.grid, 1, [3, 3]);
  g.beginPath(); for (let i = 0; i <= 80; i++) { const x = i / 80; g.lineTo(X(x), Y(fn(x))); } g.strokeStyle = K.blue; g.lineWidth = 2; g.stroke();
  const p = clamp((t - .3) / (o.d || 1.2)), v = fn(p);
  ln(g, X(p), gy + 4, X(p), gy + gh - 4, K.mute, 1, [2, 3]); circ(g, X(p), Y(v), 4.5, K.red);
  const a = 178, b = 292, ty = 74; ln(g, a, ty + 18, b, ty + 18, K.grid, 1);
  rr(g, lerp(a, b, v) - 12, ty - 12, 24, 24, 5, K.red);
  for (let i = 0; i <= 12; i++) { const x = lerp(a, b, fn(i / 12)); ln(g, x, 124, x, i % 6 ? 134 : 140, K.ink, 1.2); }
  tx(g, 'スペーシング（12コマ）', (a + b) / 2, 152, { size: 9, w: 500, c: K.mute });
  if (o.lab) label(g, o.lab);
}
// ---------- 共通ビュー：スプリング（時間グラフ＋四角）----------
function springView(g, t, k, c, m, o = {}) {
  const gx = 22, gy = 30, gw = 124, gh = 128, T = 1.6, Y = v => gy + gh - 22 - v * (gh - 50), X = s => gx + s / T * gw;
  rr(g, gx, gy, gw, gh, 6, null, K.grid, 1); ln(g, gx, Y(1), gx + gw, Y(1), K.grid, 1, [3, 3]); ln(g, gx, Y(0), gx + gw, Y(0), K.grid, 1, [3, 3]);
  g.beginPath(); for (let i = 0; i <= 90; i++) { const s = i / 90 * T; g.lineTo(X(s), Y(spring(s, k, c, m))); } g.strokeStyle = K.blue; g.lineWidth = 2; g.stroke();
  const s = clamp(t - .3, 0, T), v = spring(s, k, c, m); circ(g, X(s), Y(v), 4.5, K.red);
  const a = 178, b = 280, ty = 74; ln(g, b, ty - 20, b, ty + 20, K.grid, 1, [3, 3]);
  rr(g, lerp(a, b, v) - 12, ty - 12, 24, 24, 5, K.red);
  const st = springStats(k, c, m);
  tx(g, `${L('オーバーシュート')} ${st.over.toFixed(1)}%`, 236, 128, { size: 10, w: 500, f: 'm', c: K.ink });
  tx(g, `${L('収束')} ${Math.round(st.settle * 1000)}ms`, 236, 146, { size: 10, w: 500, f: 'm', c: K.mute });
  if (o.lab) label(g, o.lab);
}

