D({ id: 't-stagger-random', c: 'timing', ja: 'ステッガー：ランダム', en: 'Stagger: Random', dur: 2.8, d: 'ばらばらに出る。きらめき・テクスチャ的な出現に（シードを固定して毎回同じに）。', v: ['from: "random"', 'シード固定'], s: ['gsap', 'lottie'], kw: ['stagger', 'random'], f(g, t) { staggerGrid(g, t, (i, j) => hash(i * 9 + j * 31) * .6, 'from: random'); } });
D({ id: 't-stagger-grid', c: 'timing', ja: 'ステッガー：グリッド斜め', en: 'Stagger: Grid Diagonal', dur: 2.8, d: 'グリッドの角から対角線に波が走る。grid と from を組み合わせる。', v: ['grid: [4, 8]', 'from: [0, 0]'], s: ['gsap', 'student'], kw: ['stagger', 'grid'], f(g, t) { staggerGrid(g, t, (i, j) => (i + j) * .05, 'grid diagonal'); } });
D({ id: 't-twos', c: 'timing', ja: '1 コマ打ち・2 コマ打ち・3 コマ打ち', en: 'On Ones / Twos / Threes', dur: 2,
  d: '24fps で同じ絵を 2 コマ（12 枚/秒）や 3 コマ保つと手描きの味が出る。滑らかさより「描いた感」。', v: ['ones 24fps', 'twos 12fps', 'threes 8fps'], s: ['charlie', 'animate', 'hanif', 'cab'], kw: ['twos', 'ones'],
  f(g, t) { [[1, 50, '1s'], [2, 100, '2s'], [3, 150, '3s']].forEach(([n, y, s]) => { const q = Math.floor(t * 24 / n) * n / 24, x = 40 + ping(q, 2) * 230; circ(g, x, y, 12, n === 1 ? K.ink : K.red); tx(g, s, 14, y, { a: 'left', size: 10, f: 'm', w: 500, c: K.mute }); }); } });
D({ id: 't-snaphold', c: 'timing', ja: 'パッと出て、止めて見せる', en: 'Snap, then Hold', dur: 2.4,
  d: '変化そのものは 1〜2 コマで素早く、落ち着く部分だけイージング。押した・置いた感触が強くなる。', v: ['ポップ 0.04〜0.08s', 'その後ホールド'], s: ['hanif'], kw: ['snap', 'hold'],
  f(g, t) { for (let i = 0; i < 4; i++) { const t0 = .3 + i * .45, k = t < t0 ? 0 : t < t0 + .06 ? 1.25 : lerp(1.25, 1, E.outCubic(clamp((t - t0 - .06) / .2))); xf(g, 55 + i * 70, 100, k, k, 0, () => star(g, 0, 0, 22, 9, 5, i % 2 ? K.ink : K.red)); } } });
D({ id: 't-hitstop', c: 'timing', ja: 'ヒットストップ', en: 'Hit-stop', dur: 2.4,
  d: '当たった瞬間に時間を数コマ止める（ゲームの手応え）。画面の白フラッシュ・揺れ・パーティクルと 1 コマで重ねる。', v: ['停止 3〜6 フレーム', 'フラッシュ上限 0.6'], s: ['hanif'], kw: ['hit-stop', 'impact'],
  f(g, t) { const hit = 1.0, stop = .12, tt = t < hit ? t : t < hit + stop ? hit : t - stop, x = lerp(30, 250, clamp(tt / 1)), back = tt > hit ? (tt - hit) * 140 : 0;
    rr(g, 250, 60, 40, 80, 6, K.ink); circ(g, Math.min(x, 234) - back, 100, 16, K.red);
    if (t > hit && t < hit + stop) { alpha(g, .55, () => rr(g, 0, 0, W, H, 0, K.paper)); for (let i = 0; i < 8; i++) { const a = i / 8 * TAU; ln(g, 240 + Math.cos(a) * 20, 100 + Math.sin(a) * 20, 240 + Math.cos(a) * 40, 100 + Math.sin(a) * 40, K.red, 3); } } } });
D({ id: 't-beat', c: 'timing', ja: '拍のグリッド（120BPM）', en: 'Beat Grid', dur: 2,
  d: '120BPM なら 1 拍 0.5 秒＝30fps で 15 フレーム。変化は拍に、大きな出来事は小節の頭（ダウンビート）に置く。', v: ['frames/beat = 60/BPM × fps', '120BPM@30fps = 15f'], s: ['klik', 'iart', 'reel', 'kimeur', 'movez'], kw: ['beat', 'bpm'],
  f(g, t) { const beat = t * 2, b = Math.floor(beat), ph = fract(beat), down = b % 4 === 0;
    for (let i = 0; i < 4; i++) { const on = i === b % 4, k = on ? Math.exp(-ph * 6) : 0; circ(g, 70 + i * 60, 90, 18 + k * 12, on ? (i === 0 ? K.red : K.ink) : K.grid); }
    for (let i = 0; i < 16; i++) ln(g, 40 + i * 15, 150, 40 + i * 15, i % 4 ? 158 : 166, i === Math.floor(fract(t / 2) * 16) ? K.red : K.mute, 1.5); if (down) alpha(g, Math.exp(-ph * 8) * .25, () => rr(g, 0, 0, W, H, 0, K.red)); } });
D({ id: 't-ramp', c: 'timing', ja: 'スピードランプ', en: 'Speed Ramp into a Hit', dur: 2.6,
  d: '当たる直前に 25% まで減速して溜め、ダウンビートで衝撃、その後また加速。映像の緩急づけの定番。', v: ['100% → 25% → 衝撃 → 100%'], s: ['iart', 'hf'], kw: ['speed ramp'],
  f(g, t) { const rate = u => u < .8 ? 1 : u < 1.3 ? lerp(1, .25, (u - .8) / .5) : u < 1.35 ? .25 : 1.3; let x = 0; for (let u = 0; u < t; u += .01) x += rate(u) * .01 * 130; x = 30 + x % 280;
    for (let i = 0; i < 6; i++) alpha(g, .15 * (6 - i) / 6, () => circ(g, x - i * 6 * rate(t), 100, 12, K.red)); circ(g, x, 100, 12, K.red); tx(g, Math.round(rate(t) * 100) + '%', 160, 160, { size: 12, f: 'm' }); } });
D({ id: 't-overlap', c: 'timing', ja: '重なり（オーバーラップ）の量', en: 'Overlap Levels', dur: 2.8,
  d: '続けて動く要素の重なり具合で印象が変わる。0% は几帳面、25% はきびきび（標準）、50% は流れるよう。', v: ['0% / 25% / 50%'], s: ['lottie'], kw: ['overlap'],
  f(g, t) { [[0, 50], [.25, 100], [.5, 150]].forEach(([o, y]) => { const d = .35; for (let i = 0; i < 4; i++) { const st = .3 + i * d * (1 - o), p = seg(t, st, st + d, E.outCubic) * (1 - seg(t, 2.4, 2.7)); xf(g, 60 + i * 56, y, p, p, 0, () => rr(g, -16, -14, 32, 28, 5, K.red)); } tx(g, Math.round(o * 100) + '%', 300, y, { a: 'right', size: 10, f: 'm', w: 500, c: K.mute }); }); } });
D({ id: 't-read', c: 'timing', ja: '読める時間を確保する', en: 'Reading Hold', dur: 4,
  d: '文字は最低でも max(0.7 秒, 0.25 秒 + 文字数 ÷ 17) は静止させる。短いフレーズでも 1 秒以上。', v: ['MIN = max(0.70s, 0.25s + chars/17)', '1 語あたり +0.25s'], s: ['klik', 'whaley'], kw: ['hold', 'legib'],
  f(g, t) { const words = ['動きは', '読める', '速さで'], i = Math.floor(t / 1.33) % 3, k = fract(t / 1.33); alpha(g, seg(k, 0, .1) * (1 - seg(k, .9, 1)), () => tx(g, words[i], 160, 92, { size: 34, f: 'd', w: 400 })); rr(g, 60, 150, 200, 6, 3, K.grid); rr(g, 60, 150, 200 * k, 6, 3, k > .75 ? K.red : K.blue); } });
D({ id: 't-energy', c: 'timing', ja: 'エネルギーの弧', en: 'Energy Arc', dur: 4,
  d: '作品全体に一つの盛り上がりの形を設計する：静かに始め、積み上げ、山場、落ち着いた解決。', v: ['establish → build → climax → resolve'], s: ['klik', 'iart', 'animate'], kw: ['energy', 'pacing'],
  f(g, t) { const e = u => .15 + .8 * Math.max(0, Math.sin(Math.PI * Math.min(1, u / .75))) * (u < .75 ? u / .75 : 1) - (u > .75 ? (u - .75) * 2 : 0); g.beginPath(); for (let i = 0; i <= 100; i++) { const u = i / 100; g.lineTo(30 + u * 260, 170 - e(u) * 120); } g.strokeStyle = K.blue; g.lineWidth = 2; g.stroke();
    const u = fract(t / 4), v = Math.max(.05, e(u)); circ(g, 30 + u * 260, 170 - v * 120, 5, K.red); const sh = v > .8 ? (hash(Math.floor(t * 24)) - .5) * 4 : 0; xf(g, 160 + sh, 40, .6 + v * .5, .6 + v * .5, 0, () => star(g, 0, 0, 14, 6, 5, K.red)); } });

// ---- atlas-demos2.js ----
// オフスクリーンに描いてから合成する（文字マスクなど）
const _oc = document.createElement('canvas'); _oc.width = W * 2; _oc.height = H * 2;
function offscreen(fn) { const c = _oc.getContext('2d'); c.setTransform(2, 0, 0, 2, 0, 0); c.globalCompositeOperation = 'source-over'; c.globalAlpha = 1; c.clearRect(0, 0, W, H); fn(c); c.globalCompositeOperation = 'source-over'; return _oc; }
// ===== デモ（2）トランジション・カメラ・タイポグラフィ =====
// ---------- 2 つのシーン ----------
function sceneA(g) { rr(g, 0, 0, W, H, 0, K.card); circ(g, 110, 100, 46, K.ink); tx(g, 'A', 230, 100, { size: 64, f: 'd', w: 400, c: K.ink }); }
function sceneB(g) { rr(g, 0, 0, W, H, 0, K.red); rr(g, 170, 54, 92, 92, 10, K.paper); tx(g, 'B', 90, 100, { size: 64, f: 'd', w: 400, c: K.paper }); }
// A→B（前半）と B→A（後半）を同じトランジションで見せる
function transView(g, t, fn, dur = 3) { const h = dur / 2, first = t < h, p = first ? seg(t, h * .35, h * .85, E.linear) : seg(t, h + h * .35, h + h * .85, E.linear); fn(g, p, first ? sceneA : sceneB, first ? sceneB : sceneA); }
const T = (id, ja, en, d, v, s, fn, extra = {}) => D({ id: 'tr-' + id, c: 'transitions', ja, en, d, v, s, dur: 3, kw: [en.split(' ')[0].toLowerCase(), 'transition'], src: `function f(g, t) { transView(g, t, ${fn.toString()}); }`, f(g, t) { transView(g, t, fn); }, ...extra });
T('cut', 'ハードカット（拍で切る）', 'Hard Cut', '9 割のつなぎはこれで十分。切った次のコマで新しい内容が完成しているように。拍に合わせる。', ['全体の約 90%', '新シーンは 1 コマ目で完成'], ['iart', 'animate', 'launch'], (g, p, a, b) => (p < .5 ? a : b)(g));
T('dissolve', 'クロスフェード（ディゾルブ）', 'Crossfade / Dissolve', '「続いている」「時間が流れた」を表す。多用すると安っぽい。12 フレーム前後。', ['12 フレーム前後', 'モーフ > カット > フェード'], ['iart', 'student', 'klik', 'remotion'], (g, p, a, b) => { a(g); alpha(g, E.inOut(p), () => b(g)); });
T('blur', 'ブラー・クロスフェード', 'Blur Crossfade', 'ぼかしながら入れ替える。フォーカスが移る印象。夢・回想に。', ['blur 0 → 14px → 0'], ['student', 'hf'], (g, p, a, b) => { const bl = Math.sin(p * Math.PI) * 10; g.filter = `blur(${bl}px)`; a(g); alpha(g, E.inOut(p), () => b(g)); g.filter = 'none'; });
T('push', 'プッシュ（押し出し）', 'Push / Slide', '新しい場面が古い場面を押し出す。前へ進む・次へ、の意味。', ['300〜500ms ease-in-out', 'direction: from-right'], ['remotion', 'student', 'iart'], (g, p, a, b) => { const q = E.inOut(p); xf(g, -q * W, 0, 1, 1, 0, () => a(g)); xf(g, (1 - q) * W, 0, 1, 1, 0, () => b(g)); });
T('whip', 'ウィップパン', 'Whip Pan', '6〜10 フレームで一気に振り、モーションブラーでカットを隠す。勢い・場面転換。', ['8〜14 フレーム', '1500px を 6 フレーム＋8px ブラー'], ['haidr', 'iart', 'student', 'klik'], (g, p, a, b) => { const q = E.whip(p); for (let i = 4; i >= 0; i--) alpha(g, i ? .18 : 1, () => { const o = (q - i * .04 * Math.sin(p * Math.PI)) * W; xf(g, -o, 0, 1, 1, 0, () => a(g)); xf(g, W - o, 0, 1, 1, 0, () => b(g)); }); });
T('wipe', 'ワイプ', 'Linear Wipe', '境界線が横切って入れ替える。境界にブランド色の帯を走らせることも。', ['wipe()', 'クリップの矩形を動かす'], ['remotion', 'haidr'], (g, p, a, b) => { a(g); const x = E.inOut(p) * W; clip(g, 0, 0, x, H, () => b(g)); ln(g, x, 0, x, H, K.yel, 4); });
T('inset', 'インセット・クリップ', 'Inset (clip-path)', 'clip-path inset() で中央から開く。去る側と入る側で逆向きにする。', ['clip-path: inset()'], ['klik', 'hf'], (g, p, a, b) => { a(g); const q = E.outExpo(p), w = W * q, h2 = H * q; clip(g, (W - w) / 2, (H - h2) / 2, w, h2, () => b(g)); });
T('clock', 'クロックワイプ', 'Clock Wipe', '時計の針のように回って切りかわる。時間経過・カウントダウン。', ['clockWipe()'], ['remotion', 'student'], (g, p, a, b) => { a(g); g.save(); g.beginPath(); g.moveTo(W / 2, H / 2); g.arc(W / 2, H / 2, 260, -Math.PI / 2, -Math.PI / 2 + TAU * E.inOut(p)); g.closePath(); g.clip(); b(g); g.restore(); });
T('iris', 'アイリス（丸く開く）', 'Iris', '円が広がって次の場面へ。半径は画面の最も遠い角まで（hypot）。2〜4 フレームの早いアイリスも。', ['radius → hypot(W, H)'], ['animate', 'pdoom', 'cab', 'student'], (g, p, a, b) => { a(g); g.save(); g.beginPath(); g.arc(W / 2, H / 2, Math.hypot(W, H) / 2 * E.inOut(p), 0, TAU); g.clip(); b(g); g.restore(); });
T('shapeiris', '形のアイリス（ハート・鍵穴）', 'Shaped Iris', '円以外の形でくり抜く。ハート・口・鍵穴など意味のある形で。', ['irisShape(pts)'], ['pdoom'], (g, p, a, b) => { a(g); const s = E.inCubic(p) * 7; g.save(); poly(g, shapePts('heart', W / 2, H / 2 + 6, 26 * s, 80)); g.clip(); b(g); g.restore(); });
T('flood', 'カラーフラッド', 'Colour Flood', '一色が点から広がって画面を覆い、引くと次の場面。半径は最も遠い角を必ず越える。', ['r = hypot(最遠の角)'], ['howseen', 'student'], (g, p, a, b) => { (p < .5 ? a : b)(g); const r = p < .5 ? E.inCubic(p * 2) : 1 - E.outCubic((p - .5) * 2); circ(g, 40, 160, r * Math.hypot(W, H), K.yel); });
T('zoomthrough', 'ズームスルー', 'Scale-through / Zoom Through', '前の場面が 1.3 倍に拡大しながら消え、次の場面が 0.8 から 1 へ。奥へ進む感覚。', ['out: scale 1.3 + fade', 'in: 0.8 → 1'], ['haidr', 'student'], (g, p, a, b) => { const q = E.inOut(p); xf(g, W / 2, H / 2, .8 + .2 * q, .8 + .2 * q, 0, () => xf(g, -W / 2, -H / 2, 1, 1, 0, () => b(g))); alpha(g, 1 - q, () => xf(g, W / 2, H / 2, 1 + .3 * q, 1 + .3 * q, 0, () => xf(g, -W / 2, -H / 2, 1, 1, 0, () => a(g)))); });
T('blinds', 'スラット（ブラインド）', 'Slats / Blinds', '細い板が左から順に引かれて現れる。上品な画像の出し方。', ['7 枚', 'ステッガー'], ['charlie', 'student'], (g, p, a, b) => { a(g); const n = 7; for (let i = 0; i < n; i++) { const k = E.inOut(clamp(p * 1.6 - i * .09)); clip(g, i * W / n, 0, W / n * k, H, () => b(g)); } });
T('blocks', 'ブロックで覆う', 'Staggered Blocks', 'タイルが時間差で画面を覆い、外れると次の場面。テンポのいい切りかえ。', ['css-cover', '時間差のタイル'], ['student'], (g, p, a, b) => { (p < .5 ? a : b)(g); const n = 8, m = 5; for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) { const d = (i + j) * .04, k = p < .5 ? E.outCubic(clamp(p * 2 * 1.6 - d)) : 1 - E.inCubic(clamp((p - .5) * 2 * 1.6 - d)); xf(g, i * 40 + 20, j * 40 + 20, k, k, 0, () => rr(g, -20.5, -20.5, 41, 41, 0, K.yel)); } });
T('pixel', 'ピクセルディゾルブ', 'Pixel Dissolve', '小さなマス単位でランダムに入れ替わる。デジタル・レトロな切りかえ。', ['マスごとにしきい値'], ['howseen', 'student'], (g, p, a, b) => { a(g); const s = 16; for (let x = 0; x < W; x += s) for (let y = 0; y < H; y += s) if (hash(x * 3.1 + y * 7.7) < p) clip(g, x, y, s, s, () => b(g)); });
T('morph', 'シェイプモーフで橋渡し', 'Shape-morph Bridge', 'フェードの代わりに、前の場面の形が次の場面の形へ変わって橋渡しする。モーフ > カット > フェード。', ['同じ点数にそろえて補間', 'morph > cut > crossfade'], ['klik', 'animate', 'reel'], (g, p, a, b) => { const q = E.inOut(p); (q < .5 ? a : b)(g); alpha(g, Math.sin(q * Math.PI), () => rr(g, 0, 0, W, H, 0, K.blue)); const A = shapePts('circle', 110, 100, 46), B = shapePts('square', 216, 100, 46); poly(g, lerpPts(a === sceneA ? A : B, a === sceneA ? B : A, q), K.paper); });
T('shared', '共有要素（FLIP）', 'Shared Element / FLIP', '一覧の小さなカードが、そのまま広がって次の画面になる。layoutId・View Transitions。', ['layoutId', 'FLIP', '400ms ease-in-out'], ['motion', 'mdev', 'iart'], (g, p, a, b) => { const k = a === sceneA ? E.inOut(p) : 1 - E.inOut(p); sceneA(g); const x = lerp(222, 0, k), y = lerp(64, 0, k), w = lerp(64, W, k), h2 = lerp(64, H, k); g.save(); rr(g, x, y, w, h2, 12 * (1 - k)); g.clip(); xf(g, x, y, w / W, h2 / H, 0, () => sceneB(g)); g.restore(); });
T('match', 'マッチカット', 'Match Cut', '前後で形・位置・大きさ・動きの向きをそろえて切る。太陽 → コイン のように意味をつなぐ。', ['形と位置を一致させる'], ['iart', 'animate'], (g, p, a, b) => { if (p < .5) { rr(g, 0, 0, W, H, 0, K.blue); circ(g, 160, 100, 40, K.yel); } else { rr(g, 0, 0, W, H, 0, K.ink); circ(g, 160, 100, 40, K.yel); circ(g, 160, 100, 30, null, K.paper, 3); tx(g, '¥', 160, 101, { size: 34, f: 'd', w: 400, c: K.paper }); } });
T('glitch', 'グリッチ（RGB ずれ）', 'Glitch', '切りかえの数コマだけ、色ずれと横ずれのスライスを入れる。インダストリアル・デジタル。', ['RGB を 35% で重ねる', '数フレームだけ'], ['student', 'klik'], (g, p, a, b) => { const on = p > .3 && p < .7, sc = p < .5 ? a : b; sc(g); if (on) { for (let i = 0; i < 6; i++) { const y = hash(i + Math.floor(p * 40)) * H, h2 = 6 + hash(i * 3) * 18, dx = (hash(i * 7 + Math.floor(p * 40)) - .5) * 60; clip(g, 0, y, W, h2, () => xf(g, dx, 0, 1, 1, 0, () => (i % 2 ? a : b)(g))); } alpha(g, .35, () => { rr(g, 4, 0, W, H, 0, K.red); }); } });
T('leak', 'ライトリーク', 'Light Leak', '柔らかい光が流れて露出オーバーぎみに飛び、その間に切りかえる。カットの上に重ねるオーバーレイ。', ['lightLeak()', 'カットの上に重ねる'], ['remotion', 'student'], (g, p, a, b) => { (p < .5 ? a : b)(g); const x = lerp(-120, W + 120, E.inOut(p)), gr = g.createRadialGradient(x, 80, 10, x, 80, 200); gr.addColorStop(0, 'rgba(255,214,140,.95)'); gr.addColorStop(.5, 'rgba(255,140,80,.45)'); gr.addColorStop(1, 'rgba(255,140,80,0)'); alpha(g, Math.sin(p * Math.PI), () => { g.fillStyle = gr; g.fillRect(0, 0, W, H); }); });
T('flip', '3D フリップ', '3D Card Flip', 'カードを裏返すように切りかえる。横幅を cos で縮めて中央で入れ替える。', ['rotateY 0 → 180°', 'perspective'], ['remotion', 'student'], (g, p, a, b) => { rr(g, 0, 0, W, H, 0, K.paper); const q = E.inOut(p), s = Math.abs(Math.cos(q * Math.PI)); xf(g, W / 2, H / 2, s * .9, .9, 0, () => xf(g, -W / 2, -H / 2, 1, 1, 0, () => (q < .5 ? a : b)(g))); });
T('brush', 'ブラシワイプ', 'Brush Wipe', '太い筆跡が数本走って次の場面を塗り出す。手描き・水彩の作品の章替えに。', ['0.6 秒・5 ストローク', '少しずつ時間差'], ['pdoom', 'cab'], (g, p, a, b) => { a(g); g.save(); g.beginPath(); for (let i = 0; i < 5; i++) { const k = E.inOut(clamp(p * 1.5 - i * .1)), y = 10 + i * 40; g.moveTo(-20, y); g.lineTo(-20 + k * (W + 60), y - 6); g.lineTo(-20 + k * (W + 60), y + 46); g.lineTo(-20, y + 50); } g.clip(); b(g); g.restore(); });
T('letter', '文字の中を抜けて次へ', 'Mask Wipe through Letterforms', '次の場面が大きな文字の形の中に見え、そのまま文字に飛び込んで切りかわる。', ['in: "mask"', '文字をマスクに'], ['kimeur', 'student'], (g, p, a, b) => { a(g); const s = .6 + E.inCubic(p) * 22, oc = offscreen(c => { b(c); c.globalCompositeOperation = 'destination-in'; c.save(); c.translate(W / 2, H / 2); c.scale(s, s); c.font = `400 120px ${FONT.d}`; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillStyle = '#000'; c.fillText(a === sceneA ? 'B' : 'A', 0, 6); c.restore(); }); g.drawImage(oc, 0, 0, W, H); });
T('drop', 'グラビティドロップ', 'Gravity Drop', '前の場面が重力で傾きながら落ち、下から次の場面が現れる。', ['outgoing on top', '重力＋回転'], ['student'], (g, p, a, b) => { b(g); const q = E.inCubic(p); xf(g, W / 2, q * 260, 1, 1, q * .35, () => xf(g, -W / 2, 0, 1, 1, 0, () => a(g))); });
T('streak', 'ライトストリーク・ウィップ', 'Light-streak Whip', 'ぼけた光の帯が横切る瞬間に切る。0.3〜0.4 秒、power3.in。', ['0.3〜0.4s', 'power3.in'], ['student'], (g, p, a, b) => { (p < .5 ? a : b)(g); const x = lerp(-200, W + 200, E.inCubic(p)); for (let i = 0; i < 6; i++) alpha(g, .25, () => rr(g, x - 70 - i * 18, 0, 90 + i * 36, H, 0, K.paper)); });
D({ id: 'tr-jcut', c: 'transitions', ja: 'J カット／L カット', en: 'J-cut / L-cut', dur: 3, kw: ['j-cut', 'l-cut'],
  d: 'J カット：次の場面の音が 4〜12 フレーム先に聞こえ始める。L カット：前の場面の音が 12〜24 フレーム残る。映像と音をずらして自然につなぐ。', v: ['J: 音が先行 4〜12f', 'L: 音が残る 12〜24f'], s: ['iart'],
  f(g, t) { const ph = fract(t / 3) * 260 + 30; [['J', 40], ['L', 116]].forEach(([n, y]) => { tx(g, n, 16, y + 18, { size: 14, f: 'd', w: 400 }); rr(g, 30, y, 130, 16, 3, K.ink); rr(g, 160, y, 130, 16, 3, K.red); const cut = n === 'J' ? 130 : 190; rr(g, 30, y + 22, cut - 30, 14, 3, K.mute); rr(g, cut, y + 22, 290 - cut, 14, 3, K.blue); ln(g, 160, y - 4, 160, y + 40, K.yel, 2); }); ln(g, ph, 30, ph, 170, K.red, 1.5); } });

// =============== カメラ ===============
// 奥行きのある世界：遠景・中景・近景・主役。cam = {x, y, z（ズーム）, r（ロール）, d（ドリー：奥ほど動かない）}
function world(g, cam = {}) {
  const { x = 0, y = 0, z = 1, r = 0, dolly = 1, blurNear = 0, blurFar = 0, flat = false } = cam;
  const layer = (depth, fn, bl = 0) => { const k = flat ? 1 : depth, s = flat ? z : 1 + (z - 1) * k * dolly; g.save(); if (bl > .2) g.filter = `blur(${bl}px)`; g.translate(W / 2, H / 2); g.rotate(r); g.scale(s, s); g.translate(-W / 2 - x * k, -H / 2 - y * k); fn(); g.restore(); };
  rr(g, 0, 0, W, H, 0, K.paper);
  layer(.2, () => { for (let i = -3; i < 9; i++) poly(g, [[i * 70 - 20, 150], [i * 70 + 25, 70 + (i % 3) * 14], [i * 70 + 70, 150]], K.grid); }, blurFar);
  layer(.55, () => { for (let i = -3; i < 12; i++) rr(g, i * 46, 110 + (i % 2) * 8, 22, 60, 4, K.mute); });
  layer(1, () => { rr(g, -200, 168, 800, 40, 0, K.ink); circ(g, 160, 128, 26, K.red); rr(g, 148, 150, 24, 18, 4, K.red); }, 0);
  layer(1.6, () => { for (let i = -2; i < 8; i++) rr(g, i * 90 + 10, 150, 30, 70, 6, K.ink); }, blurNear);
}
const CAM = (id, ja, en, d, v, s, cam, dur = 3) => D({ id: 'cam-' + id, c: 'camera', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'camera'], src: `function f(g, t) { world(g, (${cam.toString()})(t)); }`, f(g, t) { world(g, cam(t)); } });
CAM('pushin', 'プッシュイン（ドリーイン）', 'Push In / Dolly In', '被写体に寄っていく。緊張・注目。scale 1.0 → 1.12 を 1.6 秒 ease-in-out。近景ほど大きくなる。', ['scale 1 → 1.12', '1600ms ease-in-out'], ['iart', 'launch', 'klik'], t => ({ z: 1 + .25 * seg(t, .3, 2.6) }));
CAM('pullout', 'プルアウト', 'Pull Out', '引いて全体を見せる。「世界はもっと広い」という意味づけに。', ['scale 1.3 → 1'], ['cab', 'hanif'], t => ({ z: 1.35 - .35 * seg(t, .3, 2.6) }));
CAM('truck', 'トラック（横移動）', 'Truck', 'カメラごと横に滑る。手前ほど速く、奥ほど遅く動く（視差）。最もよく使う移動。', ['x を動かす', '奥ほど遅い'], ['klik', 'launch'], t => ({ x: -60 + 120 * seg(t, .2, 2.8) }));
CAM('pan', 'パン（首振り）', 'Pan', 'カメラは動かず向きだけ変える。全部の層が同じ量だけ動く（視差が出ない）。トラックとの違いはここ。', ['rotateY ≤ 6°', '全層が同じ量'], ['klik', 'iart'], t => ({ x: -60 + 120 * seg(t, .2, 2.8), flat: true }));
CAM('pedestal', 'ペデスタル（上下移動）', 'Pedestal', 'カメラが上下に移動。トラックと組み合わせて L 字の見せ方に。', ['y を動かす'], ['klik'], t => ({ y: -30 + 50 * seg(t, .2, 2.8) }));
CAM('roll', 'ロール（傾き）', 'Roll', '画面を回す。衝撃のアクセントとして数度だけ、ごく短く使う。', ['±0.9°（デモは誇張）'], ['klik'], t => ({ r: Math.sin(t * TAU / 3) * .08 }));
CAM('zoomvsdolly', 'ズーム（平板）', 'Zoom (flat)', 'レンズのズームは全層が同じ倍率で大きくなり奥行きがつぶれる。資料映像・監視カメラ風に。ドリーとの違いを比べる。', ['scale 1 → 1.2', '奥行きがつぶれる'], ['klik'], t => ({ z: 1 + .3 * seg(t, .3, 2.6), flat: true }));
CAM('vertigo', 'ドリーズーム（めまい）', 'Dolly Zoom (Vertigo)', '寄りながらズームアウトして、主役の大きさは保ったまま背景だけが伸び縮みする。不安・衝撃。', ['z を動かし scale で相殺', 'perspective 1100'], ['klik', 'iart'], t => { const q = seg(t, .3, 2.6); return { z: 1 + .5 * q, dolly: -1.2 }; });
CAM('crane', 'クレーン（ジブ）', 'Crane / Jib', '下から上へ持ち上がりつつ少し見下ろす。シーンの締めくくりの定番。', ['y を上げ、傾きで補正'], ['klik', 'austerlitz'], t => ({ y: 30 - 70 * seg(t, .3, 2.7), z: 1 + .1 * seg(t, .3, 2.7) }));
D({ id: 'cam-whip', c: 'camera', ja: 'ウィップ（急な振り）', en: 'Whip', dur: 3, kw: ['whip', 'camera'], d: '最小の移動量で一瞬だけ速く振り、層ごとの速度スミアを入れてピタッと着地。10〜14 フレーム。', v: ['10〜14 フレーム', '着地コマはシャープに'], s: ['klik', 'iart'],
  f(g, t) { const q = E.whip(seg(t, .9, 1.35, E.linear)) - E.whip(seg(t, 2.3, 2.75, E.linear)), v = Math.sin(clamp((t % 1.5 - .9) / .45) * Math.PI); for (let i = 3; i >= 0; i--) alpha(g, i ? .25 * v : 1, () => world(g, { x: -100 + 200 * q - i * 12 * v })); } });
D({ id: 'cam-orbit', c: 'camera', ja: 'オービット（周回）', en: 'Orbit / Turntable', dur: 4, kw: ['orbit', 'camera'], d: '被写体の周りを回る。奥の物は小さく暗く、手前の物は大きく。前後関係（重ね順）も入れかえる。', v: ['角度を回す', '奥行きで並べ替え'], s: ['launch', 'austerlitz'],
  f(g, t) { rr(g, 0, 0, W, H, 0, K.paper); const a = t / 4 * TAU, items = []; for (let i = 0; i < 6; i++) { const b = a + i / 6 * TAU, z = Math.sin(b); items.push([z, 160 + Math.cos(b) * 110, 100 + z * 22, .6 + .4 * (z + 1) / 2, i]); } items.sort((p, q) => p[0] - q[0]).forEach(([z, x, y, s, i]) => alpha(g, .45 + .55 * (z + 1) / 2, () => xf(g, x, y, s, s, 0, () => rr(g, -22, -30, 44, 60, 6, i === 0 ? K.red : K.ink)))); } });
CAM('rack', 'ラックフォーカス', 'Rack Focus', 'ピントを手前から奥へ（またはその逆）移す。12〜20 フレームで、見てほしい対象を切りかえる。', ['12〜20 フレーム', '背景 blur 2.6px'], ['klik', 'launch'], t => { const q = seg(t, .6, 1.4) - seg(t, 2, 2.8); return { blurNear: 4 * (1 - q), blurFar: 4 * q }; });
CAM('handheld', '手持ち風のゆれ', 'Handheld Drift', 'いくつかの正弦波を足した、ゆっくりした不規則なゆれ。ドキュメンタリー感。場面を限って使う。', ['sin を 3 本足す', '振幅は小さく'], ['austerlitz', 'klik'], t => ({ x: Math.sin(t * 1.7) * 6 + Math.sin(t * 3.1) * 3, y: Math.sin(t * 2.3) * 4 + Math.sin(t * 4.7) * 2, r: Math.sin(t * 1.3) * .01, z: 1.05 }));
CAM('shake', '衝撃のシェイク', 'Screen Shake on Hit', '当たった瞬間に大きく、指数関数的に減衰する揺れ。exp(−9·経過) × 振幅。', ['k = exp(−9d) × amp', '0.45 秒'], ['hanif', 'pdoom'], t => { const d = (t % 1.5) - .5, k = d > 0 ? Math.exp(-9 * d) * 10 : 0; return { x: Math.sin(97 * d) * k, y: Math.cos(83 * d) * k, z: 1.04 }; }, 1.5);
CAM('punch', '拍でパンチイン', 'Punch-in on the Beat', 'ダウンビートごとに一瞬ズームが跳ねて戻る。ドロップの前は小さく（0.03）、後は大きく（0.07）。', ['+0.03 / +0.07', '減衰 τ 0.11 秒'], ['whaley', 'kimeur'], t => ({ z: 1 + .07 * Math.exp(-fract(t * 2) / .11) }), 2);
CAM('kenburns', 'ケン・バーンズ', 'Ken Burns', '静止画をゆっくり拡大しながら少し横にずらす。止め絵に命を入れる。', ['scale 1 → 1.1', 'translateX 0 → −20px'], ['haidr', 'student', 'kimeur'], t => ({ z: 1 + .12 * (t / 4), x: 20 * (t / 4), flat: true }), 4);
CAM('parallax', '視差（パララックス）3 層', 'Parallax Layers', '奥ほどゆっくり。前景 1.0、中景 0.5、背景 0.2 倍の移動量が目安。', ['前 1.0 / 中 0.5 / 奥 0.2'], ['iart', 'haidr', 'lottie'], t => ({ x: Math.sin(t / 4 * TAU) * 60 }), 4);
D({ id: 'cam-follow', c: 'camera', ja: 'フォロー（先読みで追う）', en: 'Follow with Lookahead', dur: 3, kw: ['follow', 'camera'], d: '動く被写体を、少し先を見越してバネで追う。被写体は画面の中央よりやや進行方向の後ろに置く。', v: ['先読み 約 14 フレーム', '慣性つき'], s: ['klik', 'iart'],
  f(g, t) { const S = u => 160 + Math.sin(u / 3 * TAU) * 220, sx = S(t), v = Math.cos(t / 3 * TAU) * 220 * TAU / 3, lead = 46 * Math.tanh(v / 120), cam = S(t - .08) + lead, ox = 160 - cam;
    rr(g, 0, 0, W, H, 0, K.paper); g.save(); g.translate(ox * .4, 0); for (let i = -8; i < 12; i++) poly(g, [[i * 70 - 20, 150], [i * 70 + 25, 80 + (i % 3) * 12], [i * 70 + 70, 150]], K.grid); g.restore(); g.save(); g.translate(ox, 0); for (let i = -14; i < 18; i++) rr(g, i * 50, 120, 24, 48, 4, K.mute); rr(g, -900, 168, 2000, 40, 0, K.ink); circ(g, sx, 140, 20, K.red); g.restore(); ln(g, 160, 20, 160, 160, K.blue, 1, [4, 4]); const px = ox + sx; ln(g, px, 104, px + Math.sign(v) * 34, 104, K.red, 2); poly(g, [[px + Math.sign(v) * 40, 104], [px + Math.sign(v) * 32, 99], [px + Math.sign(v) * 32, 109]], K.red); tx(g, '画面中央', 160, 14, { size: 9, f: 'm', c: K.blue }); } });

// =============== タイポグラフィ ===============
function charsAt(g, s, size, font = 'd', w = 400) { s = L(s); if (font === 'd') w = 800; g.font = `${w} ${size}px ${FONT[font]}`; const ws = [...s].map(c => g.measureText(c).width), tot = ws.reduce((a, b) => a + b, 0); let x = -tot / 2; return [...s].map((c, i) => { const cx = x + ws[i] / 2; x += ws[i]; return [c, cx, ws[i]]; }); }
function drawChar(g, c, x, y, size, col = K.ink, font = 'd', w = 400) { if (font === 'd') w = 800; g.font = `${w} ${size}px ${FONT[font]}`; g.textAlign = 'center'; g.textBaseline = 'alphabetic'; g.fillStyle = col; g.fillText(c, x, y); }
const TY = (id, ja, en, d, v, s, dur, f) => D({ id: 'ty-' + id, c: 'typography', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'type', 'text'], f });
TY('mask', 'マスクから立ち上がる（単語ごと）', 'Masked Slide-up', '見えない枠の下から単語が立ち上がる。移動は高さの 105〜118%、単語の間隔 55ms 前後、わずかに回転。', ['translateY 108% → 0', 'stagger 55ms', 'EASE_OUT'], ['klik', 'whaley', 'howseen', 'launch'], 2.6, (g, t) => { const words = ['MOVE', 'WITH', 'MEANING']; g.font = `400 34px ${FONT.d}`; const tot = words.reduce((a, w) => a + g.measureText(w).width, 0) + 24, sc = Math.min(1, 270 / tot), fs = 34 * sc; g.font = `400 ${fs}px ${FONT.d}`; let x = (W - tot * sc) / 2; words.forEach((wd, i) => { const ww = g.measureText(wd).width, p = seg(t, .3 + i * .1, .8 + i * .1, E.outExpo) * (1 - seg(t, 2.1, 2.4, E.inCubic)); clip(g, x - 4, 76, ww + 8, 44, () => xf(g, x + ww / 2, 112 + (1 - p) * 48, 1, 1, (1 - p) * .12, () => drawChar(g, wd, 0, 0, fs))); x += ww + 12 * sc; }); });
TY('cascade', '1 文字ずつ流れ込む', 'Letter Cascade', '文字ごとに 40px 下からフェードしながら上がる。1.5 フレームの時間差＋±1 フレームのゆらぎ。', ['rise 42px', 'stagger 1.5f'], ['klik', 'motion'], 2.6, (g, t) => { charsAt(g, 'モーション図鑑', 36).forEach(([c, x], i) => { const p = seg(t, .3 + i * .06 + (hash(i) - .5) * .03, .8 + i * .06, E.outExpo) * (1 - seg(t, 2.2, 2.5)); alpha(g, p, () => drawChar(g, c, 160 + x, 116 + (1 - p) * 42, 36)); }); });
TY('slam', '強調のスラム', 'Emphasis Slam', '一語だけ重いバネで叩きつけ、着地でつぶれ、2〜4 フレームだけ画面を揺らす。', ['heavy spring d16 k80 m1.6', 'shake 2〜4f'], ['klik', 'hf', 'student'], 2.4, (g, t) => { const v = spring(t - .3, 260, 16, 1), y = lerp(-80, 0, v), land = t > .45 && t < .6, sq = land ? .82 : 1, sh = land ? (hash(Math.floor(t * 60)) - .5) * 8 : 0; xf(g, 160 + sh, 120 + y, 1 / sq, sq, 0, () => drawChar(g, 'BOOM', 0, 0, 56, K.red)); });
TY('swap', '単語の入れかえ（ロール）', 'Word Swap / Roll', '同じ枠の中で、古い語が上へ抜け、新しい語が下から入る。重ならないよう出入りのタイミングをずらす。', ['translateY −100% / +100%'], ['klik', 'whaley'], 3, (g, t) => { const words = ['速く', '軽く', '強く'], i = Math.floor(t), p = seg(fract(t), .55, .85, E.inOut); tx(g, 'もっと', 120, 100, { size: 30, f: 'd', w: 400, c: K.mute }); clip(g, 166, 74, 110, 52, () => { drawChar(g, L(words[i % 3]), 220, 112 - p * 52, 30, K.red); drawChar(g, L(words[(i + 1) % 3]), 220, 164 - p * 52, 30, K.red); }); });
TY('typewriter', 'タイプライター（加速する）', 'Typewriter', '一定速度は機械的。最初は 1 文字 3.2 フレーム、だんだん 1.4 フレームへ加速し、±0.8 フレームゆらす。カーソルを点滅。', ['3.2f → 1.4f / 文字', '約 35ms / 文字'], ['klik', 'whaley', 'motion'], 3, (g, t) => { const s = L('seek(t) で描く。'), n = Math.floor(Math.pow(clamp((t - .3) / 1.6), .75) * s.length); g.font = `500 22px ${FONT.m}`; g.textAlign = 'left'; g.textBaseline = 'middle'; g.fillStyle = K.ink; const shown = s.slice(0, n), w = g.measureText(shown).width; g.fillText(shown, 60, 100); if (fract(t * 2) < .5 || n < s.length) rr(g, 62 + w, 88, 10, 24, 1, K.red); });
TY('scramble', 'スクランブル（解読）', 'Scramble / Decode', 'ランダムな記号が入れかわりながら、左から順に正しい文字に確定する。', ['scrambleText', 'chars: "01"'], ['gsap', 'motion', 'student'], 2.6, (g, t) => { const s = 'DECRYPTED', cs = '01#$%&*', p = clamp((t - .3) / 1.4) * (s.length + 3); charsAt(g, s, 30, 'm', 600).forEach(([c, x], i) => { const done = i < p - 3, ch = done ? c : i < p ? cs[Math.floor(hash(i * 13 + Math.floor(t * 24)) * cs.length)] : ''; drawChar(g, ch, 160 + x, 112, 30, done ? K.ink : K.red, 'm', 600); }); });
TY('blurin', 'ブラーイン', 'Blur-in', 'ぼけた状態からピントが合うように現れる。16px → 0、上質・シネマティック。', ['blur 16px → 0', 'opacity 0 → 1'], ['launch', 'hf', 'student'], 2.6, (g, t) => { const p = seg(t, .3, 1.1, E.outCubic) * (1 - seg(t, 2.2, 2.5)); g.filter = `blur(${(1 - p) * 10}px)`; alpha(g, p, () => drawChar(g, 'Focus', 160, 116, 48)); g.filter = 'none'; });
TY('tracking', 'トラッキングイン（字間が詰まる）', 'Tracking-in', '広い字間からゆっくり詰めて定位置に。ロゴ・タイトルの上品な出し方。', ['letter-spacing 0.5em → 0'], ['launch'], 3, (g, t) => { const p = seg(t, .2, 2.2, E.outCubic); charsAt(g, 'ATLAS', 40).forEach(([c, x], i, a) => { alpha(g, Math.min(1, p * 2), () => drawChar(g, c, 160 + x * (1 + (1 - p) * 1.4), 116, 40)); }); });
TY('trace', '輪郭を描いてから塗る', 'Trace (Outline → Fill)', '文字の輪郭線を描き終えてから塗りがふわっと広がる。', ['strokeDashoffset', '輪郭 約 16 フレーム → 塗り'], ['klik', 'gsap'], 3, (g, t) => { const p = seg(t, .2, 1.4, E.inOut), f = seg(t, 1.3, 1.8); g.font = `400 64px ${FONT.d}`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.setLineDash([400, 400]); g.lineDashOffset = 400 * (1 - p); g.strokeStyle = K.ink; g.lineWidth = 1.5; g.strokeText('LINE', 160, 100); g.setLineDash([]); alpha(g, f, () => { g.fillStyle = K.red; g.fillText('LINE', 160, 100); }); });
TY('flip', '文字のフリップ', 'Letter Flip', '文字ごとにカードのように縦回転して次の単語に切りかわる。2.5 フレームの時間差。', ['rotateX', 'stagger 2.5f'], ['klik'], 3, (g, t) => { const A = 'SPRING', B = 'TWEENS'; charsAt(g, A, 38).forEach(([c, x], i) => { const p = seg(t, .6 + i * .07, .9 + i * .07, E.inOut) * (1 - seg(t, 2.2 + i * .05, 2.5 + i * .05, E.inOut)), s = Math.cos(p * Math.PI); xf(g, 160 + x, 100, 1, Math.abs(s), 0, () => drawChar(g, s > 0 ? c : B[i], 0, 14, 38, s > 0 ? K.ink : K.red)); }); });
TY('arc', 'レールに乗って走る文字', 'Text on an Arc Path', '点線のレールが先に描かれ、文字が接線の向きに回転しながら乗って進む。', ['レール 約 14 フレーム', '接線方向に回転'], ['klik', 'gsap'], 3.2, (g, t) => { const rail = seg(t, .1, .6), P = u => [40 + u * 240, 150 - Math.sin(u * Math.PI) * 90]; g.beginPath(); for (let i = 0; i <= 60 * rail; i++) g.lineTo(...P(i / 60)); g.strokeStyle = K.grid; g.lineWidth = 2; g.setLineDash([4, 5]); g.stroke(); g.setLineDash([]); const s = 'ALONG THE PATH', p = seg(t, .6, 2.6, E.inOut); [...s].forEach((c, i) => { const u = clamp(p - i * .045); if (u <= 0) return; const [x, y] = P(u), [x2, y2] = P(Math.min(1, u + .01)); xf(g, x, y - 6, 1, 1, Math.atan2(y2 - y, x2 - x), () => drawChar(g, c, 0, 0, 16, K.red, 'm', 600)); }); });
TY('countup', '数字のカウントアップ', 'Number Count-up', '0 から目標値まで、最後にゆっくり落ち着くように数える。600〜1200ms、ease-out expo。桁幅は等幅に。', ['600〜1200ms', 'easeOutExpo', 'tabular-nums'], ['iart', 'student', 'whaley'], 2.6, (g, t) => { const v = Math.round(seg(t, .3, 1.5, E.outExpo) * 1754); tx(g, v.toLocaleString(), 160, 96, { size: 52, f: 'm', w: 600, c: K.red }); tx(g, '収録項目', 160, 140, { size: 12, w: 500, c: K.mute }); });
TY('odometer', '桁が回るロール', 'Odometer Roll', '各桁が縦に回って新しい数字に止まる。上の桁ほど少し遅れて。', ['桁ごとに縦スクロール'], ['whaley'], 3, (g, t) => { const target = 2048, digits = String(target).split('').map(Number); digits.forEach((d, i) => { const p = seg(t, .3 + i * .12, 1.4 + i * .12, E.outCubic), pos = p * (10 + d); const x = 100 + i * 40; rr(g, x - 17, 70, 34, 60, 6, K.card, K.grid, 1); clip(g, x - 17, 70, 34, 60, () => { for (let k = Math.floor(pos) - 1; k <= Math.floor(pos) + 1; k++) drawChar(g, String(((k % 10) + 10) % 10), x, 118 + (k - pos) * 46, 36, K.ink, 'm', 600); }); }); });
TY('karaoke', 'カラオケ字幕', 'Karaoke Caption', '話している語だけ 1.08 倍に膨らみアクセント色に。0.08〜0.12 秒のポップ。', ['active scale 1.08', 'pop 0.08〜0.12s'], ['student', 'hf', 'pdoom'], 3, (g, t) => { const ws = ['NEVER', 'STOP', 'MOVING']; g.font = `400 26px ${FONT.d}`; const wd = ws.map(w => g.measureText(w).width), tot = wd.reduce((a, b) => a + b, 0) + 24; let x = 160 - tot / 2; ws.forEach((w, i) => { const act = Math.floor(t / 1) === i, k = act ? 1 + .08 * spring(fract(t) - .02, 400, 18) : 1; xf(g, x + wd[i] / 2, 108, k, k, 0, () => drawChar(g, w, 0, 0, 26, act ? K.red : K.ink)); x += wd[i] + 12; }); });
