TY('underline', '下線を描く', 'Underline Draw', '語の下に線が伸びる。少し左右にはみ出させ、線は語の 3px 下に。', ['左 −6px・幅 +16px'], ['launch', 'remotion'], 2.6, (g, t) => { const p = seg(t, .5, 1.0, E.outCubic) * (1 - seg(t, 2.2, 2.5)); tx(g, 'Underline', 160, 94, { size: 36, f: 'd', w: 400 }); ln(g, 74, 122, 74 + 172 * p, 122, K.red, 4); });
TY('circle', '手描きの丸で囲む', 'Marker Circle', '少し傾いた手描きの楕円で囲む。back.out(1.7) で出して −3° 回転。', ['back.out(1.7)', 'rotation −3°'], ['student', 'remotion'], 2.8, (g, t) => { const p = seg(t, .5, 1.2, E.outCubic) * (1 - seg(t, 2.4, 2.7)); tx(g, '¥980', 160, 100, { size: 36, f: 'd', w: 400 }); g.save(); g.translate(160, 100); g.rotate(-.05); g.beginPath(); for (let i = 0; i <= 80 * p; i++) { const a = i / 80 * TAU * 1.08 - 2; g.lineTo(Math.cos(a) * (78 + noise1(i * .3) * 4), Math.sin(a) * (34 + noise1(i * .3, 2) * 3)); } g.strokeStyle = K.red; g.lineWidth = 3; g.stroke(); g.restore(); });
TY('scribble', '取り消し線（なぐり書き）', 'Scribble Strike', '波打つ線で語を消す。価格の訂正・ビフォー表示に。', ['strokeDashoffset → 0', '0.8s power1.inOut'], ['student'], 2.8, (g, t) => { const p = seg(t, .5, 1.3) * (1 - seg(t, 2.4, 2.7)); tx(g, '退屈な動き', 160, 100, { size: 30, f: 'd', w: 400, c: K.mute }); g.beginPath(); for (let i = 0; i <= 60 * p; i++) { const x = 64 + i / 60 * 192; g.lineTo(x, 100 + Math.sin(i * .9) * 5); } g.strokeStyle = K.red; g.lineWidth = 3; g.stroke(); });
TY('elastic', '伸び縮みする文字', 'Elastic Type', 'ベースラインは固定のまま、中央から外へ文字が伸びて細くなり、戻る。', ['scaleX / 字間をバネで'], ['charlie'], 2.4, (g, t) => { const v = Math.sin(clamp((t - .3) / 1.4) * Math.PI) * (1 + .3 * Math.sin(t * 9) * Math.exp(-t)); charsAt(g, 'STRETCH', 40).forEach(([c, x]) => xf(g, 160 + x * (1 + v * .5), 120, 1 - v * .35, 1 + v * .25, 0, () => drawChar(g, c, 0, 0, 40, K.ink))); });
TY('rsvp', '高速表示（スピードリード）', 'Speed-read (RSVP)', '情報の洪水を表すときだけ、1 語を約 0.16 秒で次々に同じ位置へ出す。', ['1 語 4 フレーム @25fps'], ['klik'], 2.4, (g, t) => { const ws = ['情報', 'が', '多すぎて', '追えない', '…'], i = Math.floor(t / .16) % ws.length; tx(g, ws[i], 160, 100, { size: 34, f: 'd', w: 400, c: i === 3 ? K.red : K.ink }); });
TY('ghost', '移動量が減っていく語の出現', 'Word Ghost Reveal', '1 語目は大きく 360px から、後ろの語ほど小さい距離（120→60→25→12px）で入る。軽いリズム。', ['360 → 120 → 60 → 25 → 12px', 'expo.out 0.33s'], ['student'], 3, (g, t) => { const ws = ['make', 'motion', 'feel', 'designed'], dist = [360, 120, 60, 25]; g.font = `400 26px ${FONT.d}`; const tot = ws.reduce((a, w) => a + g.measureText(w).width, 0) + 30, sc = Math.min(1, 280 / tot), fs = 26 * sc; g.font = `400 ${fs}px ${FONT.d}`; let x = (W - tot * sc) / 2; ws.forEach((w, i) => { const ww = g.measureText(w).width, p = seg(t, .3 + i * .15, .63 + i * .15, E.outExpo) * (1 - seg(t, 2.5, 2.8)); alpha(g, p, () => drawChar(g, w, x + ww / 2 + (1 - p) * dist[i], 110, fs, i === 0 ? K.red : K.ink)); x += ww + 10 * sc; }); });
TY('kinetic', '動詞で行が立ち上がる', 'Kinetic Lines on Verbs', '3〜5 行を、それぞれの動詞が読まれるタイミングで 28px 上げて出す（0.3 秒 power3.out）。', ['rise 28px', '0.3s power3.out', 'ナレーションの語に合わせる'], ['launch'], 3.4, (g, t) => { const ls = ['書いて', '確かめて', '直して', '出す。']; ls.forEach((s, i) => { const p = seg(t, .3 + i * .45, .6 + i * .45, E.outCubic) * (1 - seg(t, 3.0, 3.3)); alpha(g, p, () => tx(g, s, 70, 50 + i * 34 + (1 - p) * 28, { a: 'left', size: 24, f: 'd', w: 400, c: i === 3 ? K.red : K.ink })); }); });
TY('splitflap', 'パタパタ表示（スプリットフラップ）', 'Split-flap', '駅の発車標のように、文字盤が上半分ずつめくれて目的の文字に止まる。', ['1 枚ずつめくる', '桁ごとに時間差'], ['student'], 3, (g, t) => { const s = 'TOKYO', al = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'; [...s].forEach((c, i) => { const target = al.indexOf(c), p = clamp((t - .3 - i * .12) / 1.6), idx = Math.floor(p * target), x = 80 + i * 40; rr(g, x - 17, 74, 34, 52, 4, K.ink); drawChar(g, al[idx], x, 114, 32, K.paper, 'm', 600); ln(g, x - 17, 100, x + 17, 100, K.paper, 1); }); });
TY('inertia', '飛び込んで揺れて止まる文字', 'Inertia Letters', '文字が別々のレーンから飛び込み、着地後に減衰振動 θ = A·e^(−t/τ)·sin(ωt) で揺れて止まる。', ['θ = A e^(−t/τ) sin(ω t)', '周期 約 11 フレーム'], ['klik'], 3, (g, t) => { charsAt(g, 'INERTIA', 36).forEach(([c, x], i) => { const t0 = .3 + i * .08, p = seg(t, t0, t0 + .25, E.outCubic), dt = t - t0 - .25, th = dt > 0 ? .5 * Math.exp(-dt / .25) * Math.sin(dt * 30) : 0, from = i % 2 ? -120 : 120; xf(g, 160 + x, 120 + (1 - p) * from, 1, 1, th, () => drawChar(g, c, 0, 0, 36, i === 0 ? K.red : K.ink)); }); });
TY('gravity', '文字が落ちて積もる', 'Gravity Letters', '文字が重さを持って落ち、跳ねて止まる。シード固定の物理で、毎回同じ結果に。', ['シード固定の物理', 'bounce'], ['klik'], 3, (g, t) => { floor(g, 150); charsAt(g, 'GRAVITY', 38).forEach(([c, x], i) => { const p = clamp((t - .2 - hash(i) * .5) / 1.1), y = lerp(-40, 150, E.bounce(p)), r = (hash(i + 3) - .5) * .5 * p; xf(g, 160 + x, y, 1, 1, r, () => drawChar(g, c, 0, 0, 38, i === 3 ? K.red : K.ink)); }); });
TY('caption', 'ショート動画の字幕ポップ', 'Pop Captions', '1〜3 語の大きな語を、話す瞬間にポップさせる。勢いのある動画は 0.1〜0.2 秒の back.out(1.7)。', ['2〜3 語ずつ', 'back.out(1.7) 0.1〜0.2s'], ['student', 'kimeur', 'remotion'], 2.4, (g, t) => { const gs = [['これが', 'コツ'], ['音に', '合わせる']], gi = Math.floor(t / 1.2) % 2, lt = fract(t / 1.2) * 1.2; gs[gi].forEach((w, i) => { const s = seg(lt, .05 + i * .25, .2 + i * .25, E.outBack); xf(g, 160, 80 + i * 44, s, s, 0, () => { w = L(w); g.font = `800 34px ${FONT.d}`; g.lineWidth = 6; g.strokeStyle = K.paper; g.textAlign = 'center'; g.textBaseline = 'middle'; g.strokeText(w, 0, 0); g.fillStyle = i ? K.yel : K.ink; g.fillText(w, 0, 0); }); }); });

