U('checkbox', 'チェックボックス', 'Checkbox Check', '枠が少し縮んで塗りつぶされ、チェックの線が描かれる。150〜200ms・easeOutCubic。', ['150〜200ms', 'easeOutCubic'], ['iart', 'lottie'], 2, (g, t) => { const on = t % 2 < 1, lt = t % 1, p = on ? seg(lt, .3, .48, E.outCubic) : 1 - seg(lt, .3, .45), s = 1 - .12 * Math.sin(clamp((lt - .3) / .18) * Math.PI); xf(g, 160, 100, s, s, 0, () => { rr(g, -26, -26, 52, 52, 10, p > .05 ? K.red : null, K.ink, 2.5); g.beginPath(); g.moveTo(-12, 0); g.lineTo(-3, 10); g.lineTo(14, -10); g.strokeStyle = K.paper; g.lineWidth = 5; g.lineCap = 'round'; g.setLineDash([40, 40]); g.lineDashOffset = 40 * (1 - p); g.stroke(); g.setLineDash([]); g.lineCap = 'butt'; }); }, ['toggle', 'checkbox']);
U('morph', '1 つの形が変わり続ける（切らない）', 'One Shape, Never Cut', 'ボタン → ローディング → 完了 → カード。同じ要素の大きさ・角丸・色だけがバネで変わり、中身は短いブラーで入れかわる。', ['寸法はすべて track() のバネ', '中身はモーフ開始後に入り、次の前に消える'], ['twoclip', 'movez', 'verbove', 'barty', 'aiMotion'], 5, (g, t) => { const st = [[0, 120, 44, 22], [1, 44, 44, 22], [2, 56, 56, 28], [3, 200, 120, 14]], times = [0, 1, 2, 3, 4.4]; const pick = k => track(t, times.slice(0, 4).map((tt, i) => [tt + (i ? .2 : 0), st[i][k]]).concat([[4.4, st[0][k]]]), 300, 26), w = pick(1), h = pick(2), r = pick(3), ph = Math.floor(t) % 5, ct = fract(t), sw = clamp((ct - .25) / .15) * (1 - clamp((ct - .85) / .1));
  rr(g, 160 - w / 2, 100 - h / 2, w, h, r, ph === 2 ? K.green : ph === 3 ? K.card : K.red, ph === 3 ? K.ink : null); alpha(g, sw, () => { if (ph === 0 || ph === 4) tx(g, '送信', 160, 101, { size: 15, c: K.paper }); if (ph === 1) { g.beginPath(); g.arc(160, 100, 12, t * 9, t * 9 + 4); g.strokeStyle = K.paper; g.lineWidth = 3; g.stroke(); } if (ph === 2) { g.beginPath(); g.moveTo(149, 100); g.lineTo(157, 108); g.lineTo(172, 92); g.strokeStyle = K.paper; g.lineWidth = 4; g.stroke(); } if (ph === 3) { rr(g, 76, 56, 70, 10, 3, K.red); rr(g, 76, 76, 150, 8, 3, K.mute); rr(g, 76, 92, 120, 8, 3, K.mute); } }); }, ['morph', 'container']);
U('modal', 'モーダルを開く・閉じる', 'Modal Enter / Exit', '背景を暗くし、モーダルは 0.96 → 1 と 16px 上へ、バネ（280/28）で。閉じるときは 200〜250ms の ease-in で速く。', ['enter spring 280/28', 'exit 200〜250ms easeInQuart'], ['iart', 'lottie', 'motion'], 3, (g, t) => { const inn = spring(t - .3, 280, 28), out = seg(t, 2.2, 2.42, E.inExpo), k = inn * (1 - out); for (let i = 0; i < 4; i++) rr(g, 30 + i * 70, 40, 56, 120, 6, K.grid); alpha(g, k * .65, () => rr(g, 0, 0, W, H, 0, K.paper)); alpha(g, k, () => xf(g, 160, 100 + (1 - k) * 16, .96 + .04 * k, .96 + .04 * k, 0, () => { rr(g, -90, -56, 180, 112, 12, K.card, K.ink, 1.5); rr(g, -70, -36, 80, 10, 3, K.red); rr(g, -70, -14, 140, 8, 3, K.mute); rr(g, 10, 22, 60, 22, 11, K.red); })); }, ['modal', 'dialog']);
U('toast', 'トースト通知', 'Toast', '下からバネで出て、数秒後に下へ抜ける。複数なら上に積み上がる。', ['in spring', 'out 200ms ease-in'], ['twoclip', 'lottie'], 3.2, (g, t) => { const k = spring(t - .3, 260, 22) * (1 - seg(t, 2.6, 2.85, E.inCubic)); rr(g, 70, lerp(220, 136, k), 180, 40, 10, K.ink); circ(g, 92, lerp(220, 136, k) + 20, 8, K.green); tx(g, '保存しました', 170, lerp(220, 136, k) + 20, { size: 13, c: K.paper }); }, ['toast', 'notification']);
U('fan', 'カードを広げる（スタック）', 'Card Stack Fan', '重なったカードがバネで扇状に広がる。一番上だけ少し行きすぎて戻り、着地点にうっすら残像。', ['上のカードだけオーバーシュート'], ['charlie'], 3, (g, t) => { const o = seg(t, 2.3, 2.7, E.inOut); [2, 1, 0].forEach(i => { const v = spring(t - .3 - (2 - i) * .06, 220, i === 0 ? 12 : 22) * (1 - o), a = (i - 1) * .32 * v, x = (i - 1) * 70 * v; xf(g, 160 + x, 110, 1, 1, a, () => rr(g, -40, -55, 80, 110, 10, i === 0 ? K.red : i === 1 ? K.blue : K.ink, K.paper, 2)); }); }, ['stack', 'cards']);
U('accordion', 'アコーディオン', 'Accordion Expand', '枠の高さが先に広がり、中身は広がり始めてから少し遅れてフェードイン。閉じるときは中身が先に消える。', ['高さ → 中身の順', '閉じるのは逆順'], ['klik', 'motion'], 3, (g, t) => { const h = 36 + 80 * (spring(t - .3, 240, 26) - seg(t, 1.9, 2.3, E.inOut)), c = seg(t, .45, .8) * (1 - seg(t, 1.75, 1.9)); rr(g, 60, 40, 200, h, 10, K.card, K.ink, 1.5); tx(g, 'よくある質問', 80, 58, { a: 'left', size: 13 }); xf(g, 240, 58, 1, 1, clamp((h - 36) / 80) * Math.PI, () => { ln(g, -5, -2, 0, 3, K.ink, 2); ln(g, 0, 3, 5, -2, K.ink, 2); }); alpha(g, c, () => { rr(g, 80, 84, 150, 8, 3, K.mute); rr(g, 80, 100, 120, 8, 3, K.mute); rr(g, 80, 116, 140, 8, 3, K.mute); }); }, ['accordion', 'expand']);
U('hover', 'ホバーで浮く', 'Hover Lift', 'カーソルが乗るとカードが 4〜8px 浮き、影が広がって薄くなる。100〜150ms。', ['translateY −6px', '影を広げる', '100〜150ms'], ['iart', 'lottie'], 2.6, (g, t) => { const on = t > .7 && t < 1.9, k = on ? seg(t, .7, .85, E.outQuad) : 1 - seg(t, 1.9, 2.05, E.outQuad), kk = t < 1.9 ? k : 1 - seg(t, 1.9, 2.05); alpha(g, .9 - kk * .45, () => xf(g, 160, 146 + kk * 6, 1 + kk * .15, .14 + kk * .04, 0, () => circ(g, 0, 0, 62, K.paper))); rr(g, 100, 50 - kk * 8, 120, 90, 12, K.card, K.ink, 1.5); rr(g, 116, 66 - kk * 8, 50, 10, 3, K.red); cursor(g, lerp(270, 170, seg(t, .2, .7, E.outCubic)) + seg(t, 1.9, 2.4) * 100, lerp(170, 100, seg(t, .2, .7, E.outCubic))); }, ['hover']);
U('ripple', 'クリックの波紋', 'Click Ripple', 'クリックした点から円が広がって消える。押した位置を視覚的に返す。', ['原点はクリック位置', '300〜400ms'], ['twoclip'], 2, (g, t) => { rr(g, 80, 70, 160, 60, 12, K.blue); clip(g, 80, 70, 160, 60, () => { const p = seg(t, .6, 1.1, E.outCubic); alpha(g, (1 - p) * .5, () => circ(g, 200, 104, p * 140, K.ink)); }); tx(g, 'タップ', 160, 100, { size: 15, c: K.paper }); cursor(g, 200, 104, t > .55 && t < .7 ? 1 : 0); }, ['ripple', 'click']);
U('island', 'ダイナミックアイランド', 'Dynamic Island', '小さな丸い島が、角丸を保ったまま横長に広がって中身を見せ、また縮む。', ['幅・高さ・角丸をバネで'], ['twoclip'], 3, (g, t) => { const k = spring(t - .3, 260, 22) - spring(t - 2.1, 260, 26), w = lerp(80, 240, k), h = lerp(26, 60, k); rr(g, 160 - w / 2, 40, w, h, h / 2, K.paper, K.line, 1.5); alpha(g, seg(k, .6, 1), () => { circ(g, 160 - w / 2 + 30, 40 + h / 2, 14, K.red); rr(g, 160 - w / 2 + 54, 40 + h / 2 - 6, 90, 8, 3, K.ink); rr(g, 160 - w / 2 + 54, 40 + h / 2 + 6, 60, 6, 3, K.mute); }); }, ['island', 'pill']);
U('progress', 'プログレスバー', 'Progress Bar', '止まったり進んだりする実際の読み込みに合わせ、表示はなめらかに追いかける（バネで追従）。終わりに光が走る。', ['表示値は実値をバネで追う'], ['twoclip', 'student'], 3.4, (g, t) => { const real = t < .4 ? 0 : t < .9 ? .3 : t < 1.6 ? .55 : t < 2.0 ? .9 : 1, v = track(t, [[0, 0], [.4, .3], [.9, .55], [1.6, .9], [2.0, 1]], 120, 22); rr(g, 50, 92, 220, 16, 8, K.grid); rr(g, 50, 92, 220 * Math.min(1, v), 16, 8, K.red); if (t > 2.2) alpha(g, 1 - seg(t, 2.2, 2.8), () => rr(g, 50 + 220 * seg(t, 2.2, 2.8), 92, 30, 16, 8, K.paper)); tx(g, Math.round(Math.min(1, v) * 100) + '%', 160, 132, { size: 13, f: 'm', w: 500 }); }, ['progress']);
U('badge', '通知バッジのポップ', 'Badge Pop', '小さな赤い点は back.out(2.2)・0.26〜0.30 秒で弾ませる。オーバーシュートは状態の変化を知らせる場面に絞る。', ['back.out(2.2)', '0.26〜0.30s'], ['launch', 'hf'], 2, (g, t) => { rr(g, 130, 74, 52, 52, 12, K.ink); tx(g, '✉', 156, 101, { size: 22, c: K.paper }); const s = seg(t, .5, .78, E.backS(2.2)) * (1 - seg(t, 1.7, 1.85)); xf(g, 182, 74, s, s, 0, () => { circ(g, 0, 0, 11, K.red); tx(g, '3', 0, 1, { size: 12, f: 'm', c: K.paper }); }); }, ['badge']);
U('cmdk', 'コマンドパレット（⌘K）', 'Command Palette', '⌘K で中央にパレットが開き、入力に合わせて候補が絞られる。消える行は縮み、残る行は上に詰める。', ['開く spring', '行は FLIP で詰める'], ['twoclip', 'movez'], 4, (g, t) => { const k = spring(t - .2, 300, 26) * (1 - seg(t, 3.6, 3.8)), q = 'mo'.slice(0, Math.floor(clamp((t - 1) / .6) * 2)), items = ['motion', 'model', 'mask', 'mirror'], keep = items.map(s => s.startsWith(q)); let y = 0; alpha(g, k, () => xf(g, 160, 100, .96 + .04 * k, .96 + .04 * k, 0, () => { rr(g, -100, -70, 200, 140, 12, K.card, K.ink, 1.5); tx(g, '⌘K  ' + q + (fract(t * 2) < .5 ? '|' : ''), -84, -50, { a: 'left', size: 13, f: 'm' }); ln(g, -100, -36, 100, -36, K.grid, 1); items.forEach((s, i) => { const vis = keep[i] ? 1 : 1 - seg(t, 1.3, 1.6), ty = track(t, [[0, -18 + i * 24], [1.5, -18 + (keep.slice(0, i).filter(Boolean).length) * 24]], 300, 26); alpha(g, vis, () => tx(g, s, -84, ty, { a: 'left', size: 13, f: 'm', c: i === 0 ? K.red : K.ink })); }); })); }, ['palette', 'command']);
U('reorder', '並べ替え（FLIP）', 'List Reorder (FLIP)', '並び順が変わっても行が瞬間移動しない。前後の位置差を計算してバネで移動する（First-Last-Invert-Play）。', ['layout アニメーション', 'FLIP'], ['motion', 'mdev'], 3, (g, t) => { const orders = [[0, 1, 2, 3], [2, 0, 3, 1], [0, 1, 2, 3]], cols = [K.red, K.blue, K.ink, K.mute]; for (let i = 0; i < 4; i++) { const pos = o => orders[o].indexOf(i), y = track(t, [[0, pos(0)], [.6, pos(1)], [1.9, pos(2)]], 260, 24); rr(g, 90, 36 + y * 34, 140, 28, 8, cols[i]); } }, ['reorder', 'flip']);
U('drag', 'ドラッグして戻す・はまる', 'Drag & Snap', 'つかんでいる間は指の位置そのまま。離すと、その場所からバネで目標（元の位置か近い枠）へ。', ['ドラッグ中は直接操作', '離したらバネ'], ['twoclip', 'motion'], 3, (g, t) => { rr(g, 210, 60, 70, 70, 12, null, K.grid, 2); const hold = t > .4 && t < 1.3, cx = hold ? lerp(80, 205, seg(t, .5, 1.3, E.inOut)) : t <= .4 ? 80 : lerp(205, 245, spring(t - 1.3, 260, 18)), cy = hold ? lerp(95, 110, seg(t, .5, 1.3)) : t <= .4 ? 95 : lerp(110, 95, spring(t - 1.3, 260, 18)); const back = seg(t, 2.4, 2.9, E.inOut); rr(g, lerp(cx, 80, back) - 28, lerp(cy, 95, back) - 28, 56, 56, 12, K.red); if (t < 1.4) cursor(g, cx + 8, cy + 8, hold ? 1 : 0); }, ['drag', 'snap']);
U('swipe', 'スワイプで消す', 'Swipe to Dismiss', '指の速度が一定以上なら、そのまま回転しながら画面外へ。足りなければバネで戻る。', ['速度しきい値', '回転は移動量に比例'], ['motion'], 3, (g, t) => { const x = t < .4 ? 0 : t < .9 ? seg(t, .4, .9, E.inQuad) * 60 : 60 + (t - .9) * 420, r = x / 600; if (x < 260) xf(g, 160 + x, 100, 1, 1, r, () => { rr(g, -60, -40, 120, 80, 10, K.card, K.ink, 1.5); rr(g, -44, -24, 50, 10, 3, K.red); }); const nx = lerp(.9, 1, seg(t, .9, 1.4, E.outCubic)); alpha(g, .6, () => xf(g, 160, 108, nx, nx, 0, () => rr(g, -60, -40, 120, 80, 10, K.grid))); }, ['swipe']);
U('skeleton', 'スケルトンの光', 'Skeleton Shimmer', '読み込み中の灰色の枠に、光の帯が一定速度で流れる。linear で無限ループ。', ['linear 1.2s ループ'], ['iart'], 1.4, (g, t) => { const x = lerp(-80, 400, t / 1.4); [[40, 40, 60, 60], [116, 44, 160, 12], [116, 66, 120, 10], [40, 120, 236, 10], [40, 140, 200, 10]].forEach(([a, b, w, h]) => { rr(g, a, b, w, h, 5, K.grid); clip(g, a, b, w, h, () => { const gr = g.createLinearGradient(x - 60, 0, x + 60, 0); gr.addColorStop(0, 'rgba(255,255,255,0)'); gr.addColorStop(.5, 'rgba(255,255,255,.55)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = gr; g.fillRect(a, b, w, h); }); }); }, ['skeleton', 'shimmer']);
U('tooltip', 'ツールチップ', 'Tooltip', '指している点を原点に、150〜250ms で小さく拡大しながら出る。消すときは速く。', ['origin はアイコン側', '150〜250ms'], ['iart'], 2.4, (g, t) => { circ(g, 160, 130, 14, K.blue); tx(g, '?', 160, 131, { size: 14, c: K.paper }); const k = seg(t, .6, .8, E.outCubic) * (1 - seg(t, 1.8, 1.92)); alpha(g, k, () => xf(g, 160, 112, .9 + .1 * k, .9 + .1 * k, 0, () => { rr(g, -70, -44, 140, 34, 8, K.ink); poly(g, [[-6, -10], [6, -10], [0, -3]], K.ink); tx(g, '詳しい説明', 0, -27, { size: 12, c: K.paper }); })); }, ['tooltip']);
U('cursorarc', 'カーソルは弧を描いて動く', 'Human Cursor Path', '画面上のカーソルは直線でなく、わずかに弧を描き、ease-in-out で目標に近づいてクリックする。', ['sin の弧 0.06', 'eio easing'], ['barty', 'launch'], 3, (g, t) => { [[60, 60], [250, 80], [120, 150]].forEach(([x, y], i) => rr(g, x - 26, y - 14, 52, 28, 8, K.grid)); const pts = [[60, 60], [250, 80], [120, 150], [60, 60]], i = Math.floor(t) % 3, q = E.smooth(clamp(fract(t) / .7)), [x0, y0] = pts[i], [x1, y1] = pts[i + 1], nx = -(y1 - y0), ny = x1 - x0, arc = Math.sin(q * Math.PI) * .12; const x = lerp(x0, x1, q) + nx * arc, y = lerp(y0, y1, q) + ny * arc, press = fract(t) > .75 && fract(t) < .85; if (press) rr(g, x1 - 26, y1 - 14, 52, 28, 8, K.red); cursor(g, x, y, press ? 1 : 0); }, ['cursor']);
U('like', 'いいね（お祝い）', 'Like Burst', '50〜100ms 縮んでから、ハートが弾けて粒が飛ぶ。お祝いはオーバーシュート 15〜25% まで許す。', ['縮む → 弾ける → 落ち着く', 'overshoot 20%'], ['lottie', 'iart'], 2.4, (g, t) => { const s = t < .5 ? 1 : t < .58 ? lerp(1, .8, seg(t, .5, .58)) : lerp(.8, 1, spring(t - .58, 300, 10)), on = t > .58; xf(g, 160, 100, s, s, 0, () => poly(g, shapePts('heart', 0, 2, 26, 60), on ? K.red : null, K.ink, 2)); if (on) for (let i = 0; i < 10; i++) { const a = i / 10 * TAU, d = seg(t, .58, 1.1, E.outCubic) * 50; alpha(g, 1 - seg(t, .8, 1.2), () => circ(g, 160 + Math.cos(a) * d, 100 + Math.sin(a) * d, 3.5, i % 2 ? K.yel : K.red)); } }, ['like', 'celebration']);

// =============== ローダー ===============
const LD = (id, ja, en, d, v, s, dur, f) => D({ id: 'ld-' + id, c: 'loaders', ja, en, d, v, s, dur, kw: ['loader', 'loading'], f });
LD('spinner', 'スピナー（弧が伸び縮み）', 'Spinner', '回転は linear。弧の長さを伸び縮みさせると、ただの回転より生きて見える。', ['回転 linear', '弧の長さ ease-in-out'], ['iart'], 1.6, (g, t) => { const r = t / 1.6 * TAU * 1.5, len = .5 + 3.5 * E.sine(ping(t, 1.6)); g.beginPath(); g.arc(160, 100, 30, r, r + len); g.strokeStyle = K.red; g.lineWidth = 6; g.lineCap = 'round'; g.stroke(); g.lineCap = 'butt'; });
LD('dots', '3 つの点が弾む', 'Bouncing Dots', '同じ動きを 0.06〜0.12 秒ずつずらして 3 つ並べる。最小の時間差アニメーション。', ['stagger 約 0.06〜0.12s'], ['whaley'], 1.2, (g, t) => { for (let i = 0; i < 3; i++) { const p = fract(t / 1.2 - i * .12), y = -Math.max(0, Math.sin(p * TAU)) * 22; circ(g, 130 + i * 30, 110 + y, 9, i === 1 ? K.red : K.ink); } });
LD('bar', '不定のバー', 'Indeterminate Bar', '終わりが分からない読み込み。短い帯が加速・減速しながら左から右へ流れる。', ['ease-in-out で往復'], ['iart'], 1.8, (g, t) => { rr(g, 50, 96, 220, 8, 4, K.grid); const p = fract(t / 1.8), a = E.inOutCubic(clamp(p * 1.4)), b = E.inOutCubic(clamp(p * 1.4 - .4)); clip(g, 50, 96, 220, 8, () => rr(g, 50 + b * 220, 96, (a - b) * 220 + 6, 8, 4, K.red)); });
LD('ring', 'リング進捗', 'Progress Ring', '円周を進捗に合わせて描き、数値は等幅で数える。完了時に一度だけ弾む。', ['arc 0 → 360°', '完了で back.out'], ['iart'], 3, (g, t) => { const p = seg(t, .2, 2, E.inOut), done = seg(t, 2, 2.3, E.outBack); circ(g, 160, 96, 34, null, K.grid, 8); g.beginPath(); g.arc(160, 96, 34, -Math.PI / 2, -Math.PI / 2 + TAU * p); g.strokeStyle = K.red; g.lineWidth = 8; g.lineCap = 'round'; g.stroke(); g.lineCap = 'butt'; xf(g, 160, 96, 1 + .1 * Math.sin(done * Math.PI), 1 + .1 * Math.sin(done * Math.PI), 0, () => tx(g, Math.round(p * 100) + '%', 0, 1, { size: 15, f: 'm' })); });
LD('pulse', '脈打つ輪', 'Pulse Ring', '中心から輪が広がって消えるのをくり返す。待機・録音中・ライブ中の合図。', ['scale 1 → 2.2 と fade を同時に'], ['lottie'], 1.6, (g, t) => { for (let i = 0; i < 2; i++) { const p = fract(t / 1.6 + i * .5); alpha(g, 1 - p, () => circ(g, 160, 100, 18 + p * 40, null, K.red, 3)); } circ(g, 160, 100, 16, K.red); });
LD('squares', '四角が入れかわる', 'Morphing Squares', '4 つの四角が順番に位置を交換する。幾何学的で落ち着いた待ち時間に。', ['順番に swap'], ['hf'], 2.4, (g, t) => { const step = Math.floor(t / .6) % 4, p = E.inOutCubic(clamp(fract(t / .6) / .7)), pos = [[0, 0], [1, 0], [1, 1], [0, 1]]; for (let i = 0; i < 3; i++) { const a = pos[(i + step) % 4], b = pos[(i + step + 1) % 4]; rr(g, 136 + lerp(a[0], b[0], p) * 28, 76 + lerp(a[1], b[1], p) * 28, 22, 22, 4, i ? K.ink : K.red); } });

// =============== 図形・SVG ===============
const SH = (id, ja, en, d, v, s, dur, f) => D({ id: 'sh-' + id, c: 'shapes', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'svg', 'shape'], f });
SH('draw', '線を描く（ラインドロー）', 'Line Draw (DrawSVG)', 'パスの長さだけ破線にして、ずらす量（dashoffset）を減らすと線が描かれていく。', ['stroke-dashoffset: L → 0', 'DrawSVG'], ['gsap', 'motion', 'launch'], 2.8, (g, t) => { const p = seg(t, .2, 1.6, E.inOut) - seg(t, 2.2, 2.7, E.inOut) * 0; g.beginPath(); g.moveTo(40, 150); g.bezierCurveTo(90, 20, 150, 180, 200, 70); g.bezierCurveTo(230, 20, 270, 60, 285, 130); g.strokeStyle = K.red; g.lineWidth = 5; g.lineCap = 'round'; g.setLineDash([520, 520]); g.lineDashOffset = 520 * (1 - p) + 520 * seg(t, 2.2, 2.7, E.inOut) * -1; g.stroke(); g.setLineDash([]); g.lineCap = 'butt'; });
SH('morph', 'シェイプモーフ', 'Shape Morph', '形の輪郭を同じ点数にそろえてから点ごとに補間する。円 → 星 → 四角 → 三角。', ['点数をそろえて補間', 'MorphSVG'], ['gsap', 'klik', 'animate'], 4, (g, t) => { const ks = ['circle', 'star', 'square', 'tri', 'circle'], i = Math.floor(t) % 4, q = E.inOut(clamp((fract(t) - .3) / .6)); poly(g, lerpPts(shapePts(ks[i], 160, 100, 56), shapePts(ks[i + 1], 160, 100, 56), q), i % 2 ? K.blue : K.red); });
SH('follow', 'パスに沿って動く（向きも追う）', 'Path Follow / MotionPath', 'パスの上を進みながら、接線の方向へ向きを自動で合わせる。', ['autoRotate: true', 'MotionPath'], ['gsap', 'motion'], 3, (g, t) => { const P = u => [40 + u * 240, 100 + Math.sin(u * TAU * 1.5) * 50]; g.beginPath(); for (let i = 0; i <= 60; i++) g.lineTo(...P(i / 60)); g.strokeStyle = K.grid; g.lineWidth = 2; g.setLineDash([4, 5]); g.stroke(); g.setLineDash([]); const u = E.inOut(ping(t, 3)), [x, y] = P(u), [x2, y2] = P(Math.min(1, u + .01)); xf(g, x, y, 1, 1, Math.atan2(y2 - y, x2 - x), () => poly(g, [[14, 0], [-10, -9], [-5, 0], [-10, 9]], K.red)); });
SH('trim', 'トリムパス（始点と終点）', 'Trim Paths', 'After Effects のトリムパス。終点を先に、始点を少し遅れて動かすと、線が走り抜ける。', ['end 先行・start 追従'], ['lottieweb', 'lottie'], 2, (g, t) => { const e = seg(t, .2, .9, E.inOut), s = seg(t, .45, 1.2, E.inOut); g.beginPath(); g.arc(160, 100, 50, -Math.PI / 2 + TAU * s, -Math.PI / 2 + TAU * Math.max(s, e)); g.strokeStyle = K.red; g.lineWidth = 8; g.lineCap = 'round'; g.stroke(); g.lineCap = 'butt'; });
SH('repeater', 'リピーター（放射状の複製）', 'Radial Repeater', '1 つの形を回転させながら複製し、時間差で動かすと万華鏡のような模様に。', ['回転コピー × 時間差'], ['lottieweb'], 3, (g, t) => { for (let i = 0; i < 12; i++) { const a = i / 12 * TAU + t * .4, p = E.sine(ping(t + i * .08, 1.5)); xf(g, 160, 100, 1, 1, a, () => rr(g, 18 + p * 20, -5, 34, 10, 5, i % 3 ? K.ink : K.red)); } });
SH('blob', 'ゆらぐブロブ', 'Noise Blob', '円周の各点の半径をノイズで揺らす。有機的・液体的な背景や待機に。', ['半径 = r + noise'], ['hf'], 4, (g, t) => { const pts = []; for (let i = 0; i < 80; i++) { const a = i / 80 * TAU, r = 52 + (noise2(Math.cos(a) * 1.3 + t * .5, Math.sin(a) * 1.3, 4) - .5) * 40; pts.push([160 + Math.cos(a) * r, 100 + Math.sin(a) * r]); } poly(g, pts, K.red); });
SH('burst', '集中線・放射の線', 'Radiating Burst Lines', '12 本の線を 30° ずつ並べ、中心から外へ時間差で伸ばす。強調・驚き。', ['12 本・30° 間隔', 'stagger 0.03s'], ['student', 'pdoom'], 2, (g, t) => { for (let i = 0; i < 12; i++) { const a = i / 12 * TAU, p = seg(t, .3 + i * .02, .6 + i * .02, E.outCubic), q = seg(t, .6 + i * .02, .9 + i * .02, E.inCubic); ln(g, 160 + Math.cos(a) * (30 + q * 50), 100 + Math.sin(a) * (30 + q * 50), 160 + Math.cos(a) * (30 + p * 50), 100 + Math.sin(a) * (30 + p * 50), K.red, 4); } tx(g, '!', 160, 100, { size: 34, f: 'd', w: 400 }); });
SH('march', '破線が流れる（マーチングアント）', 'Marching Dashes', '破線のずらし量を一定速度で動かす。選択範囲・接続中・データの流れ。', ['lineDashOffset を linear に'], ['gsap'], 1, (g, t) => { g.setLineDash([10, 8]); g.lineDashOffset = -t * 36; rr(g, 70, 50, 180, 100, 12, null, K.red, 3); ln(g, 30, 175, 290, 175, K.blue, 3); g.setLineDash([]); });

// =============== パーティクル ===============
const PT = (id, ja, en, d, v, s, dur, f) => D({ id: 'pt-' + id, c: 'particles', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'particle'], f });
PT('burst', '放射状に弾ける', 'Radial Burst', '中心から全方向へ、減速しながら飛び散り、小さくなって消える。シード固定でいつも同じ配置。', ['速度ばらつき', '減速＋縮小'], ['hanif', 'kimeur'], 2, (g, t) => { const r = rng(5); for (let i = 0; i < 40; i++) { const a = r() * TAU, sp = 40 + r() * 90, p = E.outCubic(clamp((t - .2) / 1.2)); alpha(g, 1 - p, () => circ(g, 160 + Math.cos(a) * sp * p, 100 + Math.sin(a) * sp * p, 4 * (1 - p) + 1, i % 3 ? K.red : K.yel)); } });
PT('confetti', '紙吹雪', 'Confetti', '上へ打ち上げて重力で落ちる。1 枚ずつ回転と横揺れを入れ、表裏で色が変わるように見せる。', ['重力＋回転＋ゆらぎ'], ['gsap', 'hanif'], 3, (g, t) => { const r = rng(9); for (let i = 0; i < 40; i++) { const vx = (r() - .5) * 160, vy = -140 - r() * 120, s = clamp(t - .2, 0, 3), x = 160 + vx * s + Math.sin(s * 6 + i) * 8, y = 180 + vy * s + 160 * s * s, rot = s * (4 + r() * 6), c = [K.red, K.blue, K.yel, K.green][i % 4]; if (y < 210) xf(g, x, y, Math.cos(rot), 1, rot * .3, () => rr(g, -4, -2.5, 8, 5, 1, c)); } });
PT('twinkle', 'きらめき', 'Twinkle Sparkles', '4 方向の光が、位置・開始・大きさをずらして点滅する。同時に光らせない。', ['開始をずらす', '十字の光'], ['hanif', 'whaley'], 3, (g, t) => { for (let i = 0; i < 12; i++) { const p = fract(t / 1.5 + hash(i) * 3), k = Math.sin(clamp(p / .35) * Math.PI); if (k > 0) star(g, 30 + hash(i + 1) * 260, 20 + hash(i + 2) * 160, 4 + k * 10 * hash(i + 4), 1.5, 4, i % 3 ? K.yel : K.red, t * .5); } });
PT('embers', '立ち昇る火の粉', 'Rising Embers', '下から上へ、横に揺れながら昇り、上に行くほど小さく暗くなる。', ['上昇＋横ゆれ', '寿命で縮む'], ['hanif'], 3, (g, t) => { for (let i = 0; i < 36; i++) { const p = fract(t / 3 + hash(i)), x = 60 + hash(i + 7) * 200 + Math.sin(p * 9 + i) * 10, y = 190 - p * 200; alpha(g, 1 - p, () => circ(g, x, y, 4 * (1 - p) + .5, p < .4 ? K.yel : K.red)); } });
PT('snow', '雪', 'Snow', '奥（小さく遅い）と手前（大きく速い）の 2〜3 層で、ゆらゆら落ちる。', ['層ごとに大きさと速さ'], ['hanif'], 4, (g, t) => { for (let i = 0; i < 50; i++) { const d = .4 + hash(i + 3) * .6, y = fract(hash(i) + t / 4 * d) * 220 - 10, x = (hash(i + 1) * 340 + Math.sin(t * 1.5 + i) * 10 * d) % 330; circ(g, x, y, 1 + d * 3, d > .8 ? K.blue : K.mute); } });
PT('fireworks', '花火（尾を引く）', 'Fireworks with Trails', '打ち上げて頂点で弾け、粒が重力で垂れながら尾を引いて消える。', ['破裂＋重力＋尾'], ['hanif'], 3, (g, t) => { const up = seg(t, .1, .7, E.outQuad), cx = 160, cy = lerp(190, 70, up); if (t < .7) circ(g, cx, cy, 3, K.yel); else for (let i = 0; i < 24; i++) { const a = i / 24 * TAU, s = t - .7; for (let k = 0; k < 5; k++) { const ss = Math.max(0, s - k * .04), x = cx + Math.cos(a) * 70 * (1 - Math.exp(-ss * 2.5)), y = cy + Math.sin(a) * 70 * (1 - Math.exp(-ss * 2.5)) + 20 * ss * ss; alpha(g, (1 - seg(s, 1, 2)) * (1 - k / 5), () => circ(g, x, y, 2.4 - k * .3, i % 2 ? K.red : K.yel)); } } });
PT('swarm', '群れ（漂う光）', 'Swarm', '各粒子がノイズで決まる軌道を回り、全体としてゆるくまとまって動く。', ['noise で軌道', '群れの中心も漂う'], ['hanif'], 6, (g, t) => { const cx = 160 + Math.sin(t / 6 * TAU) * 50, cy = 100 + Math.cos(t / 3 * TAU) * 20; for (let i = 0; i < 40; i++) { const a = t * (.6 + hash(i) * .8) + i, r = 20 + noise1(t * .6 + i, 2) * 50; circ(g, cx + Math.cos(a) * r, cy + Math.sin(a * 1.3) * r * .6, 2.5, i % 5 ? K.ink : K.red); } });
PT('flow', 'フローフィールド', 'Flow Field', '場所ごとの向き（ノイズで決める）に沿って線が流れる。風・水・データの流れ。', ['angle = noise(x, y)'], ['hf'], 4, (g, t) => { for (let i = 0; i < 70; i++) { let x = hash(i) * W, y = hash(i + 50) * H; g.beginPath(); g.moveTo(x, y); for (let k = 0; k < 14; k++) { const a = noise2(x * .012, y * .012 + t * .15, 6) * TAU * 1.5; x += Math.cos(a) * 4; y += Math.sin(a) * 4; g.lineTo(x, y); } g.strokeStyle = i % 7 ? K.mute : K.red; g.lineWidth = 1.4; g.stroke(); } });
PT('coalesce', '粒が集まって形になる', 'Particles Coalesce', '散らばった粒が、それぞれの目的地（形の輪郭上の点）へ集まって形を作る。', ['散乱 → 目的地へバネ'], ['student', 'hf'], 3.4, (g, t) => { const pts = shapePts('heart', 160, 104, 70, 60), p = spring(t - .4, 60, 10) * (1 - seg(t, 2.7, 3.2, E.inCubic)); pts.forEach(([x, y], i) => circ(g, lerp(hash(i) * W, x, p), lerp(hash(i + 9) * H, y, p), 3, i % 4 ? K.red : K.ink)); });

// =============== ループ・アンビエント ===============
const LP = (id, ja, en, d, v, s, dur, f) => D({ id: 'lp-' + id, c: 'loops', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'loop'], f });
LP('seamless', '継ぎ目のないループ', 'Seamless Loop', '最後のコマと最初のコマを完全に一致させる。くり返す動きの周期はループ長を割り切れる値に。', ['frame 0 == frame N', '周期はループ長の約数'], ['n01', 'movez', 'kimeur', 'twoclip'], 2, (g, t) => { const u = t / 2; for (let i = 0; i < 8; i++) { const a = u * TAU + i / 8 * TAU; circ(g, 160 + Math.cos(a) * 60, 96 + Math.sin(a) * 60, 6 + 4 * Math.sin(u * TAU * 2 + i), i ? K.ink : K.red); } rr(g, 40, 176, 240, 4, 2, K.grid); rr(g, 40 + 236 * u, 172, 4, 12, 1, K.red); });
LP('breath', '呼吸', 'Breathing', '1〜2% の拡大縮小を sine でゆっくりくり返す。止まっている物に命を入れる最小の動き。', ['scale ±1〜2%', 'sine.inOut'], ['student', 'klik'], 3, (g, t) => { const s = 1 + .04 * Math.sin(t / 3 * TAU); xf(g, 160, 100, s, s, 0, () => rr(g, -50, -50, 100, 100, 20, K.red)); });
LP('float', '浮遊', 'Float', '上下にゆっくり漂い、影が連動して伸び縮みする。', ['y ±6px', '影も連動'], ['lottie'], 3, (g, t) => { const y = Math.sin(t / 3 * TAU) * 10; alpha(g, .85, () => xf(g, 160, 160, 1 - y * .015, 1, 0, () => circ(g, 0, 0, 30, K.paper))); circ(g, 160, 96 + y, 28, K.blue); });
LP('orbit', '周回', 'Orbit', '中心の周りを一定速度で回る。楕円にして奥行き、手前で大きく。', ['linear 回転'], ['whaley'], 3, (g, t) => { const a = t / 3 * TAU, z = Math.sin(a); if (z < 0) circ(g, 160 + Math.cos(a) * 90, 100 + z * 20, 8 + z * 3, K.red); circ(g, 160, 100, 26, K.ink); if (z >= 0) circ(g, 160 + Math.cos(a) * 90, 100 + z * 20, 8 + z * 3, K.red); });
LP('marquee', 'マーキー（流れる帯）', 'Marquee', '同じ内容を 2 つ並べて流し、1 つ分進んだら位置を戻すと切れ目なく流れ続ける。', ['2 つ並べて wrap'], ['student', 'gsap'], 3, (g, t) => { const w = 330, x = -fract(t / 3) * w; [0, w].forEach(o => { for (let i = 0; i < 4; i++) tx(g, i % 2 ? '★' : 'MOTION', x + o + i * 82 + 40, 100, { size: 22, f: 'd', w: 400, c: i % 2 ? K.red : K.ink }); }); });
LP('conic', '回る光の輪', 'Rotating Gradient Ring', '円錐グラデーションを回転させる。ボタンの縁・待機中の光。', ['conic-gradient を回転'], ['student'], 2, (g, t) => { if (!g.createConicGradient) return; const gr = g.createConicGradient(t / 2 * TAU, 160, 100); gr.addColorStop(0, K.red); gr.addColorStop(.3, K.yel); gr.addColorStop(.6, 'rgba(0,0,0,0)'); gr.addColorStop(1, K.red); circ(g, 160, 100, 50, gr); circ(g, 160, 100, 42, K.paper); });
LP('wobble', 'ゆらゆら（ノイズ）', 'Noise Wobble', '位置と回転にゆっくりしたノイズを足す。手描き感・不安定さ。', ['noise で微小なずれ'], ['klik', 'cab'], 4, (g, t) => { for (let i = 0; i < 3; i++) xf(g, 80 + i * 80 + (noise1(t * 1.2, i) - .5) * 10, 100 + (noise1(t * 1.4, i + 5) - .5) * 10, 1, 1, (noise1(t, i + 9) - .5) * .4, () => rr(g, -24, -24, 48, 48, 8, i === 1 ? K.red : K.ink)); });
LP('boil', 'ラインボイル（線の震え）', 'Line Boil', '同じ絵を 2 コマごと（12fps）に少しずつ描き直し、線がふつふつ震える手描きの味を出す。', ['12fps で描き直し', '±1〜2px'], ['pdoom', 'cab', 'animate'], 2, (g, t) => { const f = Math.floor(t * 12); g.beginPath(); for (let i = 0; i <= 40; i++) { const a = i / 40 * TAU; g.lineTo(160 + Math.cos(a) * (50 + (hash(i * 3 + f * 17) - .5) * 4), 100 + Math.sin(a) * (50 + (hash(i * 5 + f * 13) - .5) * 4)); } g.strokeStyle = K.ink; g.lineWidth = 3; g.stroke(); circ(g, 145 + (hash(f) - .5) * 2, 92, 4, K.ink); circ(g, 175 + (hash(f + 1) - .5) * 2, 92, 4, K.ink); g.beginPath(); g.arc(160, 106, 16, .2, Math.PI - .2); g.stroke(); });
LP('pendulum', '振り子', 'Pendulum', '端でゆっくり、中央で速い。sin で角度を決めるだけで自然な往復になる。', ['angle = A sin(ωt)'], ['cab'], 2, (g, t) => { const a = Math.sin(t / 2 * TAU) * .7, x = 160 + Math.sin(a) * 110, y = 30 + Math.cos(a) * 110; ln(g, 160, 30, x, y, K.ink, 2); circ(g, 160, 30, 4, K.ink); circ(g, x, y, 14, K.red); });
LP('holdcycle', 'ホールドとサイクル', 'Hold & Cycle', '見せ場でポーズを止め（ホールド）、止まっている間も小さな周期運動を続ける。', ['ホールド中も周期運動'], ['kimeur'], 3, (g, t) => { const hold = t > .6 && t < 2.4, x = hold ? 160 : t <= .6 ? lerp(30, 160, E.outExpo(t / .6)) : lerp(160, 300, E.inExpo((t - 2.4) / .6)); xf(g, x, 100, 1, 1, hold ? Math.sin(t * 8) * .06 : 0, () => star(g, 0, 0, 34, 14, 5, K.red)); });

// =============== データ可視化 ===============
const DV = (id, ja, en, d, v, s, dur, f) => D({ id: 'dv-' + id, c: 'data-viz', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'chart', 'data'], f });
DV('bars', '棒グラフが伸びる', 'Bar Grow', '棒が下から順に伸び、少し遅れて数値が出る。値の大きい棒ほど目立たせる。', ['stagger 0.05〜0.08s', 'easeOutExpo'], ['iart', 'student'], 3, (g, t) => { const vals = [.4, .7, .55, .9, .65]; floor(g, 170); vals.forEach((v, i) => { const p = seg(t, .3 + i * .08, 1.1 + i * .08, E.outExpo) * (1 - seg(t, 2.6, 2.9)); rr(g, 50 + i * 48, 170 - v * 130 * p, 30, v * 130 * p, 4, i === 3 ? K.red : K.ink); alpha(g, seg(t, .9 + i * .08, 1.1 + i * .08), () => tx(g, Math.round(v * 100), 65 + i * 48, 158 - v * 130 * p, { size: 10, f: 'm', w: 500, c: K.paper })); }); });
DV('line', '折れ線を描く＋ツールチップ', 'Line Chart Draw', '線が左から描かれ、最後の点に印が付く。ホバーでツールチップが追う。', ['線を描く 1.2s', '点はポップ'], ['twoclip', 'student'], 3.4, (g, t) => { const ys = [140, 120, 128, 96, 104, 70, 58], p = seg(t, .3, 1.5, E.inOut); for (let i = 0; i < 4; i++) ln(g, 30, 50 + i * 30, 290, 50 + i * 30, K.grid, 1); g.beginPath(); ys.forEach((y, i) => { const x = 40 + i * 40; if (i / 6 <= p) g.lineTo(x, y); else if ((i - 1) / 6 < p) { const k = (p - (i - 1) / 6) * 6; g.lineTo(lerp(x - 40, x, k), lerp(ys[i - 1], y, k)); } }); g.strokeStyle = K.red; g.lineWidth = 3; g.stroke(); const s = seg(t, 1.5, 1.7, E.outBack); xf(g, 280, 58, s, s, 0, () => circ(g, 0, 0, 6, K.red)); const hx = lerp(40, 280, seg(t, 2, 3, E.inOut)), hi = Math.min(5, Math.floor((hx - 40) / 40)), hy = lerp(ys[hi], ys[hi + 1], ((hx - 40) % 40) / 40); if (t > 2) { ln(g, hx, 40, hx, 160, K.mute, 1, [3, 3]); rr(g, hx - 26, hy - 34, 52, 22, 6, K.ink); tx(g, Math.round(200 - hy), hx, hy - 23, { size: 11, f: 'm', c: K.paper }); } });
DV('donut', 'ドーナツグラフ', 'Donut Sweep', '円弧を順番に描き足し、最後に中央の合計がカウントアップする。', ['弧を順に', '中央の数値'], ['iart'], 3, (g, t) => { const parts = [.45, .3, .25], cols = [K.red, K.blue, K.ink]; let a0 = -Math.PI / 2; const p = seg(t, .3, 1.5, E.inOut); parts.forEach((v, i) => { const a1 = a0 + v * TAU * p; g.beginPath(); g.arc(160, 100, 50, a0, a1); g.strokeStyle = cols[i]; g.lineWidth = 18; g.stroke(); a0 = a1; }); tx(g, Math.round(p * 128), 160, 100, { size: 22, f: 'm', w: 600 }); });
DV('stat', '大きな数字のカード', 'Stat Card', '一つの数字が証拠になる場面。数字のカウントアップと、比較バーの伸びを同時に。', ['数字 600〜1200ms', 'バー同期'], ['launch', 'student'], 3, (g, t) => { const p = seg(t, .3, 1.4, E.outExpo); rr(g, 60, 40, 200, 120, 14, K.card, K.ink, 1.5); tx(g, '+' + Math.round(p * 40) + '%', 160, 86, { size: 40, f: 'm', w: 600, c: K.red }); rr(g, 84, 124, 152, 8, 4, K.grid); rr(g, 84, 124, 152 * p * .8, 8, 4, K.red); });
DV('pins', '地図にピンが落ちる', 'Map Pins Drop', '地図上の地点にピンが時間差で落ち、着地でわずかに弾む。点は数を見せたいときに。', ['bounce・時間差'], ['verbove', 'remotion'], 3, (g, t) => { rr(g, 30, 30, 260, 140, 12, K.grid); for (let i = 0; i < 9; i++) { const x = 50 + hash(i) * 220, y = 50 + hash(i + 7) * 100, p = seg(t, .3 + i * .1, .7 + i * .1, E.bounce); alpha(g, Math.min(1, p * 3), () => { const yy = lerp(y - 40, y, p); circ(g, x, yy - 10, 7, i % 3 ? K.ink : K.red); poly(g, [[x - 5, yy - 7], [x + 5, yy - 7], [x, yy]], i % 3 ? K.ink : K.red); }); } });
DV('scatter', '散布図が現れる', 'Scatter Reveal', '点が軸から生まれて位置へ移動し、最後に回帰線が引かれる。', ['点 → 線の順'], ['iart'], 3, (g, t) => { ln(g, 40, 170, 290, 170, K.ink, 1.5); ln(g, 40, 30, 40, 170, K.ink, 1.5); for (let i = 0; i < 24; i++) { const x = 50 + hash(i) * 230, y = 160 - (x - 50) * .45 - (hash(i + 4) - .5) * 50, p = seg(t, .3 + i * .03, .8 + i * .03, E.outCubic); circ(g, x, lerp(170, y, p), 4, K.blue); } const l = seg(t, 1.6, 2.2, E.inOut); ln(g, 50, 160, lerp(50, 285, l), lerp(160, 54, l), K.red, 2.5); });

// =============== キャラクター ===============
const CH = (id, ja, en, d, v, s, dur, f) => D({ id: 'ch-' + id, c: 'character', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'character'], f });
function blobby(g, x, y, sx = 1, sy = 1, eye = 1, mouth = 0) { xf(g, x, y, sx, sy, 0, () => { rr(g, -26, -52, 52, 52, 22, K.red); rr(g, -12, -36, 6, 10 * eye + .5, 3, K.paper); rr(g, 6, -36, 6, 10 * eye + .5, 3, K.paper); if (mouth) circ(g, 0, -16, 5 * mouth, K.paper); }); }
CH('walk', '歩き（ウォークサイクル）', 'Walk Cycle', '1 歩ごとに体が上下（接地で低く、通過で高く）し、手足は逆位相で振る。周期を一定にしてループ。', ['1 歩 0.5s', '上下動 2 回 / 周期', '手足は逆位相'], ['cab', 'hanif', 'austerlitz'], 2, (g, t) => { floor(g); const ph = t / 1 * TAU, x = 160, bob = Math.abs(Math.cos(ph)) * 5; [-1, 1].forEach(s => { const a = Math.sin(ph) * .5 * s; xf(g, x, 128 - bob, 1, 1, a, () => rr(g, -4, 0, 8, 40, 4, K.ink)); }); xf(g, x, 128 - bob, 1, 1, 0, () => rr(g, -20, -56, 40, 60, 16, K.red)); [-1, 1].forEach(s => { const a = -Math.sin(ph) * .6 * s; xf(g, x, 92 - bob, 1, 1, a, () => rr(g, -3, 0, 6, 32, 3, K.ink)); }); circ(g, x + 8, 84 - bob, 3, K.paper); });
CH('jump', 'ジャンプ（溜め→伸び→着地）', 'Jump', 'かがんで溜め（1.22 倍に広がる）、伸びて跳び（0.8）、着地で 1.35 倍につぶれて 0.18 秒で戻る。', ['溜め 1.22', '空中 0.8', '着地 1.35 → 1 / 0.18s'], ['hanif', 'cab'], 2.2, (g, t) => { floor(g); const crouch = seg(t, .2, .5) - seg(t, .5, .56), air = clamp((t - .56) / .7), h = 4 * air * (1 - air) * 80 * (t > .56 && t < 1.26 ? 1 : 0), land = t > 1.26 ? Math.max(0, 1 - (t - 1.26) / .18) : 0; let sy = 1 - crouch * .22 - land * .35 + (h > 0 ? .2 * (1 - air * 2) * (air < .5 ? 1 : 0) : 0); sy = Math.max(.6, sy); blobby(g, 160, 168 - h, 1 / sy, sy); });
CH('blink', 'まばたき', 'Blink', '一瞬（2〜3 フレーム）で閉じて、少しゆっくり開く。間隔は不規則に（同じ間隔だとロボット）。', ['閉 2f・開 3〜4f', '間隔はばらす'], ['cab'], 4, (g, t) => { floor(g); const bl = [.8, 2.1, 2.35, 3.4].map(b => t > b && t < b + .2 ? 1 - Math.sin((t - b) / .2 * Math.PI) : 1).reduce((a, b) => Math.min(a, b), 1); blobby(g, 160, 168, 1, 1, bl); });
CH('take', 'テイク（驚き）', 'Take', '驚く直前に一瞬縮んで溜め、大きく伸びて目を見開き、少し戻ってホールド。', ['縮む → 伸びる → 戻ってホールド'], ['cab'], 2.4, (g, t) => { floor(g); const s = t < .6 ? 1 : t < .7 ? lerp(1, .8, seg(t, .6, .7)) : lerp(.8, 1, spring(t - .7, 260, 9)) + .15 * Math.exp(-(t - .7) * 3) * 0; blobby(g, 160, 168, 2 - s, s, t > .7 ? 1.4 : 1, t > .7 ? 1 : 0); if (t > .7 && t < 1.4) for (let i = 0; i < 5; i++) { const a = -Math.PI / 2 + (i - 2) * .4; alpha(g, 1 - seg(t, 1, 1.4), () => ln(g, 160 + Math.cos(a) * 70, 110 + Math.sin(a) * 70, 160 + Math.cos(a) * 88, 110 + Math.sin(a) * 88, K.ink, 3)); } });
CH('turn', '振り向き', 'Head Turn', '目線が先に動き、顔が続き、体が最後についてくる（目→頭→体の順）。', ['目 → 頭 → 体'], ['cab', 'klik'], 3, (g, t) => { floor(g); const e = seg(t, .4, .55, E.outCubic) - seg(t, 1.9, 2.05, E.outCubic), h = seg(t, .5, .85, E.inOut) - seg(t, 2, 2.35, E.inOut), b = seg(t, .65, 1.1, E.inOut) - seg(t, 2.1, 2.55, E.inOut); rr(g, 160 - 22 + b * 6, 110, 44, 58, 16, K.ink); xf(g, 160 + h * 12, 92, 1, 1, 0, () => { circ(g, 0, 0, 26, K.red); circ(g, -9 + e * 14, -4, 4, K.paper); circ(g, 9 + e * 14, -4, 4, K.paper); }); });
CH('idle', '待機（呼吸）', 'Idle Breathing', '何もしていなくても、ゆっくり呼吸して時々重心を移す。完全な静止は「止まった絵」に見える。', ['呼吸 2〜4 秒周期', '重心移動'], ['cab', 'hanif'], 4, (g, t) => { floor(g); const b = Math.sin(t / 4 * TAU * 2) * .03, sway = Math.sin(t / 4 * TAU) * 3; blobby(g, 160 + sway, 168, 1 - b, 1 + b); });
CH('tail', 'しっぽ・髪のフォロースルー', 'Tail Follow-through', '体が止まっても、しっぽの先ほど遅れて揺れが残る。関節ごとに少しずつ遅らせたバネ。', ['関節ごとに遅延したバネ'], ['cab', 'klik'], 3, (g, t) => { floor(g); const x = 100 + 120 * (seg(t, .3, .8, E.inOut) - seg(t, 1.8, 2.3, E.inOut)); let px = x - 26, py = 140; for (let i = 0; i < 6; i++) { const d = (i + 1) * .05, xi = 100 + 120 * (seg(t - d, .3, .8, E.inOut) - seg(t - d, 1.8, 2.3, E.inOut)), nx = xi - 26 - (i + 1) * 12, ny = 140 - i * 4 + Math.sin(t * 6 - i) * i * .8; ln(g, px, py, nx, ny, K.ink, 8 - i); px = nx; py = ny; } blobby(g, x, 168); });

// =============== 質感・ルック ===============
const LK = (id, ja, en, d, v, s, dur, f) => D({ id: 'lk-' + id, c: 'painterly', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'look', 'texture'], f });
function sampleArt(g, t) { const x = 160 + Math.sin(t * 2) * 60; rr(g, 0, 0, W, H, 0, K.blue); circ(g, x, 90, 36, K.yel); rr(g, 40, 130, 240, 40, 8, K.ink); tx(g, 'LOOK', x, 92, { size: 18, f: 'd', w: 400, c: K.paper }); }
LK('grain', 'フィルムグレイン', 'Film Grain', '毎コマ違うノイズを薄く重ねる。デジタルの平らさを消す最後の一層。', ['毎コマ違うシード', '不透明度 5〜10%'], ['haidr', 'klik'], 2, (g, t) => { sampleArt(g, t); const f = Math.floor(t * 24); for (let i = 0; i < 900; i++) { alpha(g, .25, () => rr(g, hash(i + f * 1000) * W, hash(i * 3 + f * 777) * H, 1.4, 1.4, 0, hash(i + f) > .5 ? '#fff' : '#000')); } });
LK('chroma', '色収差', 'Chromatic Aberration', '赤と青を 1〜2px 左右にずらす。ピントの外れた面や強い光の縁に。トランジションでは大胆に。', ['≤ 2px（通常）', 'トランジションで強く'], ['klik', 'student'], 2, (g, t) => { const o = 2 + 6 * Math.max(0, Math.sin(t / 2 * TAU)); rr(g, 0, 0, W, H, 0, K.paper); g.globalCompositeOperation = 'screen'; xf(g, -o, 0, 1, 1, 0, () => tx(g, 'RGB', 160, 100, { size: 64, f: 'd', w: 400, c: '#00e0ff' })); xf(g, o, 0, 1, 1, 0, () => tx(g, 'RGB', 160, 100, { size: 64, f: 'd', w: 400, c: '#ff3060' })); g.globalCompositeOperation = 'source-over'; });
LK('mblur', 'モーションブラー（サブフレーム）', 'Subframe Motion Blur', '1 コマの中で時刻を少しずつずらした複数枚を平均する。上：なし、下：8 サブフレーム。速い動きほど枚数を増やす。', ['4〜8 サブフレーム', '270° シャッター', '移動 5px ごとに 1 枚・上限 64'], ['movez', 'howseen', 'kimeur', 'twoclip'], 1.6, (g, t) => { const X = u => 40 + E.inOut(ping(u, 1.6)) * 240; rr(g, X(t) - 14, 46, 28, 28, 6, K.ink); for (let i = 0; i < 8; i++) alpha(g, 1 / 8 * 1.6, () => rr(g, X(t - i * .012) - 14, 116, 28, 28, 6, K.red)); });
LK('glow', 'グロー（発光）', 'Glow / Bloom', '明るい部分だけを大きくぼかして足し合わせる。UI の飾りには使わず、光る物にだけ。', ['ぼかして加算', 'UI には使わない'], ['student', 'austerlitz'], 2.4, (g, t) => { rr(g, 0, 0, W, H, 0, K.paper); const k = .6 + .4 * Math.sin(t / 2.4 * TAU); g.globalCompositeOperation = 'lighter'; for (let i = 5; i >= 1; i--) alpha(g, .12 * k, () => circ(g, 160, 100, 20 + i * 12, K.yel)); g.globalCompositeOperation = 'source-over'; circ(g, 160, 100, 18, '#fff'); });
LK('riso', '版ずれ（リソグラフ）', 'Misregistration', '色版ごとに数 px ずらし、数コマかけて戻す。印刷物・リソグラフの味。', ['4 → 3 → 2px を 3 コマで', 'multiply'], ['kimeur'], 2, (g, t) => { rr(g, 0, 0, W, H, 0, K.ink); const f = Math.floor(t * 12) % 6, o = [4, 3, 2, 1, 2, 3][f]; g.globalCompositeOperation = 'multiply'; xf(g, -o, o * .5, 1, 1, 0, () => { circ(g, 130, 100, 44, '#2ec4e8'); tx(g, '刷', 220, 100, { size: 60, f: 'd', w: 400, c: '#2ec4e8' }); }); xf(g, o, -o * .5, 1, 1, 0, () => { circ(g, 130, 100, 44, '#ff4fa3'); tx(g, '刷', 220, 100, { size: 60, f: 'd', w: 400, c: '#ff4fa3' }); }); g.globalCompositeOperation = 'source-over'; });
LK('halftone', 'ハーフトーン', 'Halftone', '明るさを点の大きさに置きかえる。新聞・コミックの印刷感。点の大きさを動かすとアニメになる。', ['網点の半径 = 濃さ'], ['hanif'], 3, (g, t) => { rr(g, 0, 0, W, H, 0, K.paper); for (let y = 6; y < H; y += 10) for (let x = 6; x < W; x += 10) { const d = Math.hypot(x - 160 - Math.sin(t / 3 * TAU) * 60, y - 100), v = clamp(1 - d / 110); circ(g, x, y, v * 5, K.red); } });
LK('watercolor', '水彩のにじみ', 'Watercolor Wash', '半透明の不定形を少しずつ広げて重ねる。縁は濃く、中は薄く。', ['半透明を重ねる', '縁を濃く'], ['hanif', 'pdoom', 'mable'], 4, (g, t) => { rr(g, 0, 0, W, H, 0, K.paper); for (let k = 0; k < 5; k++) { const p = seg(t, .2 + k * .25, 2 + k * .25, E.outCubic), pts = []; for (let i = 0; i < 50; i++) { const a = i / 50 * TAU, r = (30 + k * 6) * p * (1 + (noise2(Math.cos(a) * 2, Math.sin(a) * 2, k) - .5) * .7); pts.push([160 + Math.cos(a) * r * 1.4, 100 + Math.sin(a) * r]); } alpha(g, .16, () => poly(g, pts, K.blue, K.blue, 2)); } });
LK('handwrite', '筆で書く（ライトオン）', 'Brush Write-on', '筆跡の順にストロークを描いていく。文字や線画を「書く過程」として見せる。', ['筆順にストローク'], ['klik', 'hanif'], 3, (g, t) => { rr(g, 0, 0, W, H, 0, K.paper); const strokes = [[[90, 60], [110, 140]], [[70, 90], [140, 86]], [[170, 60], [170, 150], [150, 140]], [[200, 70], [250, 70], [220, 110], [250, 150]]]; strokes.forEach((st, i) => { const p = seg(t, .2 + i * .5, .6 + i * .5, E.inOut); g.beginPath(); g.moveTo(...st[0]); let L = 0; for (let k = 1; k < st.length; k++) L += Math.hypot(st[k][0] - st[k - 1][0], st[k][1] - st[k - 1][1]); let rem = L * p; for (let k = 1; k < st.length && rem > 0; k++) { const d = Math.hypot(st[k][0] - st[k - 1][0], st[k][1] - st[k - 1][1]), u = Math.min(1, rem / d); g.lineTo(lerp(st[k - 1][0], st[k][0], u), lerp(st[k - 1][1], st[k][1], u)); rem -= d; } g.strokeStyle = K.ink; g.lineWidth = 9; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; }); });
LK('papercut', '切り絵・ストップモーション', 'Paper Cut / Stop-motion', '紙の層に影を付け、2 コマ打ちで少しカクつかせ、出現は back.out(2.2) でポン。', ['2 コマ打ち', 'back.out(2.2)', '層に影'], ['student', 'nftchen'], 3, (g, t) => { const tt = onTwos(t); rr(g, 0, 0, W, H, 0, K.paper); [[60, K.blue, .2], [100, K.green, .5], [140, K.red, .8]].forEach(([y, c, d], i) => { const s = seg(tt, d, d + .3, E.backS(2.2)), j = (hash(Math.floor(tt * 12) + i) - .5) * 2; alpha(g, .25, () => xf(g, 160 + 4 + j, y + 6 + (1 - s) * 40, 1, 1, 0, () => rr(g, -110, 0, 220, 40, 14, '#000'))); xf(g, 160 + j, y + (1 - s) * 40, 1, 1, 0, () => rr(g, -110, 0, 220, 40, 14, c)); }); });
LK('pixel', 'ピクセル化（粗くする）', 'Pixelate', '一度小さく描いてから拡大する（補間なし）。レトロゲーム・デジタル化の演出。粗さを動かせばトランジションにも。', ['低解像度に描いて拡大', 'imageSmoothing off'], ['hf', 'kimeur'], 3, (g, t) => { const n = 4 + Math.floor((1 - Math.abs(Math.sin(t / 3 * Math.PI))) * 28), oc = offscreen(c => { c.setTransform(n / W * 2, 0, 0, n / W * 2, 0, 0); sampleArt(c, t); }); g.imageSmoothingEnabled = false; g.drawImage(oc, 0, 0, n * 2, Math.round(n * 2 * H / W), 0, 0, W, H); g.imageSmoothingEnabled = true; });
LK('vignette', 'ビネット（呼吸する周辺減光）', 'Vignette Breathe', '画面の四隅をわずかに暗くし、ゆっくり呼吸させる。視線を中央へ集める。', ['周辺減光 10〜30%'], ['haidr', 'student'], 3, (g, t) => { sampleArt(g, t); const k = .35 + .1 * Math.sin(t / 3 * TAU), gr = g.createRadialGradient(160, 100, 60, 160, 100, 200); gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, `rgba(0,0,0,${k})`); g.fillStyle = gr; g.fillRect(0, 0, W, H); });
LK('crt', 'CRT（走査線）', 'CRT Scanlines', '横線を重ね、たまに帯がゆっくり流れる。ブラウン管・監視モニター風。', ['走査線 2px おき', '流れる帯'], ['whatships'], 3, (g, t) => { sampleArt(g, t); for (let y = 0; y < H; y += 3) alpha(g, .22, () => rr(g, 0, y, W, 1.2, 0, '#000')); const by = fract(t / 3) * 260 - 30; alpha(g, .12, () => rr(g, 0, by, W, 30, 0, '#fff')); });

// =============== 3D ===============
const TD = (id, ja, en, d, v, s, dur, f) => D({ id: '3d-' + id, c: '3d', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), '3d', 'perspective'], f });
const proj = (x, y, z, f = 360) => { const s = f / (f + z); return [160 + x * s, 100 + y * s, s]; };
TD('flipcard', 'カードを裏返す（Y 回転）', 'Card Flip (rotateY)', '親に perspective を付けて Y 軸で回す。90° で表と裏を入れかえる。scale だけの偽の奥行きにしない。', ['perspective 800〜1100px', 'backface を切りかえ'], ['hf', 'student'], 3, (g, t) => { const a = E.inOut(seg(t, .4, 1.2)) * Math.PI - E.inOut(seg(t, 1.9, 2.7)) * Math.PI, c = Math.cos(a), s = Math.sin(a), pts = [[-60, -40], [60, -40], [60, 40], [-60, 40]].map(([x, y]) => proj(x * c, y, x * s * 1.2)); poly(g, pts.map(p => [p[0], p[1]]), c > 0 ? K.red : K.ink); tx(g, c > 0 ? '表' : '裏', 160, 100, { size: 26, f: 'd', w: 400, c: K.paper }); });
TD('tilt', 'カーソルで傾く', 'Perspective Tilt', 'カーソルの位置に合わせてカードが X・Y に数度傾き、光沢が反対側へ動く。', ['±8°', '光沢は逆方向'], ['iart', 'motion'], 4, (g, t) => { const mx = Math.sin(t / 4 * TAU), my = Math.cos(t / 4 * TAU * 2) * .6, pts = [[-70, -50], [70, -50], [70, 50], [-70, 50]].map(([x, y]) => proj(x, y, x * mx * .25 + y * my * .25)); poly(g, pts.map(p => [p[0], p[1]]), K.card, K.ink); const gx = 160 - mx * 50, gr = g.createRadialGradient(gx, 100 - my * 30, 0, gx, 100 - my * 30, 90); gr.addColorStop(0, 'rgba(255,255,255,.6)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); g.save(); poly(g, pts.map(p => [p[0], p[1]])); g.clip(); g.fillStyle = gr; g.fillRect(0, 0, W, H); g.restore(); cursor(g, 160 + mx * 90, 100 + my * 60); });
TD('cube', '立方体の回転', 'Cube Rotation', '8 頂点を回転して透視投影し、手前の面だけ描く。プロダクトの見せ方・ロゴの演出に。', ['回転行列＋透視'], ['austerlitz', 'hf'], 4, (g, t) => { const a = t / 4 * TAU, b = .5, V = []; for (const x of [-1, 1]) for (const y of [-1, 1]) for (const z of [-1, 1]) { let X = x * 45, Y = y * 45, Z = z * 45; [X, Z] = [X * Math.cos(a) - Z * Math.sin(a), X * Math.sin(a) + Z * Math.cos(a)]; [Y, Z] = [Y * Math.cos(b) - Z * Math.sin(b), Y * Math.sin(b) + Z * Math.cos(b)]; V.push([X, Y, Z]); } const F = [[0, 1, 3, 2], [4, 5, 7, 6], [0, 1, 5, 4], [2, 3, 7, 6], [0, 2, 6, 4], [1, 3, 7, 5]]; F.map(f => [f, f.reduce((s, i) => s + V[i][2], 0)]).sort((p, q) => q[1] - p[1]).forEach(([f], i) => poly(g, f.map(k => { const p = proj(...V[k]); return [p[0], p[1]]; }), i > 2 ? K.red : K.grid, K.ink, 1.5)); });
TD('coverflow', 'カバーフロー', 'Cover Flow', '中央のカードは正面、左右は Y 回転して奥へ下がる。選択の移動はバネで。', ['左右は rotateY ±60°', '選択はバネ'], ['motion'], 4, (g, t) => { const sel = track(t, [[0, 0], [.8, 1], [1.8, 2], [2.8, 1], [3.6, 0]], 200, 22); for (let i = -1; i < 4; i++) { const d = i - sel, ang = clamp(d, -1, 1) * 1.05, x = d * 70 + Math.sign(d) * 20 * Math.min(1, Math.abs(d)), z = Math.abs(clamp(d, -1, 1)) * 80, c = Math.cos(ang), s = Math.sin(ang), pts = [[-34, -46], [34, -46], [34, 46], [-34, 46]].map(([px, py]) => proj(x + px * c, py, z + px * s)); alpha(g, 1 - Math.min(.6, Math.abs(d) * .3), () => poly(g, pts.map(p => [p[0], p[1]]), Math.round(sel) === i ? K.red : K.ink, K.paper, 1.5)); } });
TD('depth', '奥行きのある重なり', 'Depth Stack', 'Z 方向に並べたカードの間をカメラが前に進む。手前の物が大きく速く横切る。', ['translateZ で並べる', 'カメラを前進'], ['klik', 'student'], 4, (g, t) => { const cz = t / 4 * 400; for (let i = 7; i >= 0; i--) { const z = i * 60 - cz % 60 - (Math.floor(cz / 60) % 1) * 0; const zz = ((i * 60 - cz) % 480 + 480) % 480; const [x, y, s] = proj((i % 2 ? 1 : -1) * 60, (i % 3 - 1) * 30, zz); alpha(g, clamp(1 - zz / 480) * clamp(zz / 40), () => rr(g, x - 30 * s, y - 20 * s, 60 * s, 40 * s, 6 * s, i % 3 ? K.ink : K.red)); } });

// =============== スクロール・ジェスチャー ===============
const SC = (id, ja, en, d, v, s, dur, f, c = 'scroll') => D({ id: 'sc-' + id, c, ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'scroll'], f });
function phone(g, fn) { rr(g, 110, 8, 100, 184, 16, K.card, K.ink, 2); clip(g, 114, 12, 92, 176, fn); }
SC('progress', 'スクロール連動の進捗', 'Scroll-linked Progress', 'スクロール量をそのまま値にする。読み進めた割合のバー・章の目次。', ['scrollYProgress', 'scrub: true'], ['gsap', 'motion'], 4, (g, t) => { const sp = E.inOut(ping(t, 4)); phone(g, () => { for (let i = 0; i < 12; i++) rr(g, 122, 30 + i * 30 - sp * 200, 76, 18, 4, i % 4 ? K.grid : K.blue); rr(g, 114, 12, 92 * sp, 4, 0, K.red); }); });
SC('parallax', 'スクロール視差', 'Scroll Parallax', 'スクロールに対して背景を遅く、前景を速く動かす。速さの比で奥行きを作る。', ['背景 0.3 / 前景 1.2'], ['iart', 'gsap'], 4, (g, t) => { const sp = E.inOut(ping(t, 4)) * 200; phone(g, () => { for (let i = 0; i < 5; i++) circ(g, 130 + i * 18, 60 + i * 50 - sp * .3, 18, K.grid); for (let i = 0; i < 6; i++) rr(g, 120, 40 + i * 60 - sp * 1.2, 80, 34, 6, K.red); }); });
SC('wordreveal', '読み進めると文字が濃くなる', 'Scroll Word Reveal', 'スクロール量に合わせて単語ごとに不透明度 0.15 → 1。i 番目の語は [i/(n−1)×0.8, +0.2] の範囲で変化。', ['opacity 0.15 → 1', '語ごとに範囲をずらす'], ['motion'], 4, (g, t) => { const sp = E.inOut(ping(t, 4)), ws = ['読む', '速さで', '言葉が', '浮かぶ']; ws.forEach((w, i) => { const st = i / 3 * .8, o = lerp(.15, 1, clamp((sp - st) / .2)); alpha(g, o, () => tx(g, w, 160, 52 + i * 34, { size: 24, f: 'd', w: 400 })); }); });
SC('pin', 'ピン留めして中身だけ進む', 'Pin & Scrub', 'セクションを画面に固定（pin）している間、スクロールで中のアニメーションを進める。', ['pin: true', 'scrub'], ['gsap'], 4, (g, t) => { const sp = E.inOut(ping(t, 4)); phone(g, () => { const pinned = sp > .25 && sp < .75, y = sp < .25 ? 120 - sp * 4 * 100 : pinned ? 20 : 20 - (sp - .75) * 4 * 100; rr(g, 114, y, 92, 120, 0, K.ink); const k = clamp((sp - .25) / .5); circ(g, 160, y + 60, 6 + k * 30, K.red); }); });
SC('pinch', 'ピンチで拡大', 'Pinch Zoom', '2 本指の間隔の比で拡大率を決め、指の中点を原点に拡大する。離すと範囲内にバネで戻る。', ['scale = 間隔の比', '原点は中点'], ['motion'], 3, (g, t) => { const s = t < 1.6 ? lerp(1, 1.8, seg(t, .3, 1.4, E.inOut)) : lerp(1.8, 1.4, spring(t - 1.6, 200, 20)); clip(g, 40, 20, 240, 160, () => xf(g, 170, 100, s, s, 0, () => { rr(g, -60, -40, 120, 80, 8, K.blue); circ(g, 0, 0, 20, K.yel); })); if (t < 1.6) { const d = 20 * s; circ(g, 170 - d, 100 - d * .6, 9, null, K.ink, 2); circ(g, 170 + d, 100 + d * .6, 9, null, K.ink, 2); } }, 'gestures');
SC('ptr', '引っぱって更新', 'Pull to Refresh', '下に引くほど抵抗が増え（ラバーバンド）、離すとスピナーが回って戻る。', ['抵抗 = 1 − 1/(x×0.55/d + 1)', '離したらバネ'], ['motion'], 3, (g, t) => { const pull = t < 1 ? seg(t, .2, 1) * 140 : 0, rubber = t < 1 ? 70 * (1 - 1 / (pull * .55 / 70 + 1)) : t < 2 ? 40 : lerp(40, 0, spring(t - 2, 260, 26)); phone(g, () => { if (rubber > 4) { g.beginPath(); g.arc(160, 12 + rubber / 2, 8, t * 8, t * 8 + 4.5); g.strokeStyle = K.red; g.lineWidth = 3; g.stroke(); } for (let i = 0; i < 6; i++) rr(g, 122, 26 + i * 28 + rubber, 76, 18, 4, K.grid); }); }, 'gestures');

// =============== 音と同期 ===============
const SD = (id, ja, en, d, v, s, dur, f) => D({ id: 'sd-' + id, c: 'sound', ja, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'sound', 'beat'], f });
SD('cues', 'SFX を拍に置く', 'SFX Cues on the Grid', 'クリック・ポップ・ドン・シュッを、拍の位置や実際に測ったピークに置く。音は絵と同じタイムラインで合成。', ['click / pop / thump / whoosh', '拍 or 測ったピークへ'], ['movez', 'whaley', 'kimeur'], 4, (g, t) => { const cues = [[.5, 'click', K.ink], [1, 'pop', K.red], [2, 'thump', K.blue], [2.75, 'whoosh', K.mute], [3.5, 'pop', K.red]]; for (let b = 0; b <= 8; b++) ln(g, 30 + b * 32.5, 120, 30 + b * 32.5, b % 4 ? 128 : 134, K.mute, 1.2); cues.forEach(([ct, n, c]) => { const x = 30 + ct / 4 * 260, k = Math.exp(-Math.max(0, t - ct) * 8) * (t >= ct ? 1 : 0); rr(g, x - 3, 90, 6, 30, 2, c); tx(g, n, x, 80, { size: 9, f: 'm', w: 500, c: K.mute }); if (k > .02) circ(g, 160, 50, 8 + k * 20, null, c, 3); }); const ph = 30 + fract(t / 4) * 260; ln(g, ph, 70, ph, 150, K.red, 1.5); });
SD('bars', 'オーディオビジュアライザー', 'Audio Bars', '周波数帯ごとの強さを棒の高さに。低音で大きく、高音で細かく動かす。', ['低音＝大きく遅く', '高音＝小さく速く'], ['remotion', 'kimeur'], 2, (g, t) => { for (let i = 0; i < 24; i++) { const f = i / 24, beat = Math.exp(-fract(t * 2) * 5), v = (1 - f) * beat * .7 + noise1(t * (3 + f * 10), i) * .4 * (.3 + f); rr(g, 34 + i * 11, 160 - v * 120, 7, v * 120, 3, i < 6 ? K.red : K.ink); } });
SD('duck', 'サイドチェイン・ダック', 'Sidechain Duck', 'キックが鳴る瞬間に周りの動き（カメラ・背景）を一瞬引っ込め、すぐ戻す。音楽のサイドチェインと同じ考え方。', ['アタック約 3 フレーム', 'リリース 24〜36 フレーム'], ['klik'], 2, (g, t) => { const ph = fract(t * 2), duck = ph < .05 ? ph / .05 : Math.exp(-(ph - .05) * 6); const s = 1 - duck * .08; xf(g, 160, 100, s, s, 0, () => { for (let i = 0; i < 6; i++) rr(g, -140 + i * 50, -60, 36, 120, 6, K.grid); }); circ(g, 160, 100, 20 + duck * 10, K.red); });
SD('lyric', '歌詞・字幕を語に合わせる', 'Word-locked Sync', '各表示は、それが指す語が実際に話された（歌われた）時刻から始める。語ごとの時刻は文字起こしで測る。', ['語レベルのタイムスタンプ', '話す 0.2〜0.6 秒前から'], ['launch', 'student', 'barty'], 4, (g, t) => { const ws = [['いま', .3], ['ここで', 1.1], ['動き', 2], ['出す', 2.9]]; ws.forEach(([w, wt], i) => { const p = seg(t, wt, wt + .25, E.outBack); xf(g, 70 + i * 62, 90, p, p, 0, () => tx(g, w, 0, 0, { size: 20, f: 'd', w: 400, c: i === 2 ? K.red : K.ink })); }); g.beginPath(); for (let x = 0; x < 260; x++) { const u = x / 260 * 4, a = ws.some(([, wt]) => u > wt && u < wt + .5) ? 1 : .2; g.lineTo(30 + x, 150 + Math.sin(x * .9) * 10 * a * noise1(x * .2)); } g.strokeStyle = K.blue; g.lineWidth = 1.4; g.stroke(); const ph = 30 + fract(t / 4) * 260; ln(g, ph, 130, ph, 170, K.red, 1.5); });

// ---- ref-b01.js ----
// ===== モーションリファレンス：出現・退場／移動／スケール（b01）=====
// 共通：イージング補助・破線・数値表示・カード・ぼかし・区間ごとに別カーブのキー
const b01InQuart = x => x ** 4;
const b01Quint = x => x < .5 ? 16 * x ** 5 : 1 - (-2 * x + 2) ** 5 / 2;
const b01Q = (u, a, c, b) => (1 - u) ** 2 * a + 2 * (1 - u) * u * c + u * u * b;
function b01Dash(g, d, fn) { g.setLineDash(d); fn(); g.setLineDash([]); }
function b01Num(g, s, x, y, c, a) { tx(g, s, x, y, { size: 10, w: 500, f: 'm', c: c || K.ink, a: a || 'center' }); }
function b01Blur(g, px, extra) { const b = px > .05 ? `blur(${(px * Math.abs(g.getTransform().a)).toFixed(2)}px)` : ''; g.filter = ((extra || '') + ' ' + b).trim() || 'none'; }
// 中心基準のカード（見出しバー＋本文バー）
function b01Card(g, w, h) { const x = -w / 2, y = -h / 2; rr(g, x, y, w, h, 10, K.card, K.grid, 1); rr(g, x + 14, y + 14, w * .4, 10, 3, K.red); rr(g, x + 14, y + 34, w - 28, 7, 3.5, K.mute); rr(g, x + 14, y + 48, w * .55, 7, 3.5, K.mute); }
// [[t, v], [t, v, ease], ...]：各キーへ向かう区間を、そのキーのカーブで補間
function b01Keys(t, keys) {
  if (t <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) if (t < keys[i][0]) { const [t0, v0] = keys[i - 1], [t1, v1, e = E.inOut] = keys[i]; return lerp(v0, v1, e((t - t0) / (t1 - t0))); }
  return keys[keys.length - 1][1];
}
// 速度グラフ（横＝進行率 0..1、縦＝速さ）。dv(u) は 0..1 に正規化した速さ
function b01Speed(g, dv, p, x, y, w, h) {
  rr(g, x, y, w, h, 4, null, K.grid, 1);
  const Y = v => y + h - 5 - v * (h - 12);
  g.beginPath(); g.moveTo(x, Y(0)); for (let i = 0; i <= 60; i++) g.lineTo(x + i / 60 * w, Y(dv(i / 60))); g.lineTo(x + w, Y(0)); g.strokeStyle = K.blue; g.lineWidth = 1.5; g.stroke();
  const live = p > 0 && p < 1; circ(g, x + p * w, Y(live ? dv(p) : 0), 3.2, K.red);
  b01Num(g, 'speed', x + 4, y - 7, K.mute, 'left');
}

