R({ id: 'split-reveal', dur: 2.6, bez: [.65, 0, .35, 1], still: 1.5,
  v: ['左 −105% / 右 +105%', '720ms easeInOutCubic', '左右対称'], vEn: ['L −105% / R +105%', '720ms easeInOutCubic', 'symmetrical'],
  f(g, t) {
    const fx = 70, fy = 40, fw = 180, fh = 120, hw = fw / 2, c = seg(t, .3, 1.02, E.inOut) * (1 - seg(t, 2.0, 2.45, E.inOut)), d = hw * 1.05 * c;
    g.save(); rr(g, fx, fy, fw, fh, 10); g.clip();
    rr(g, fx, fy, fw, fh, 0, K.paper);
    xf(g, 160, 92, 1, 1, 0, () => { rr(g, -26, -26, 52, 52, 12, K.red); star(g, 0, 1, 14, 6, 5, K.paper); });
    rr(g, 130, 130, 60, 6, 3, K.mute);
    [-1, 1].forEach(s => { const x0 = s < 0 ? fx - d : 160 + d; rr(g, x0, fy, hw, fh, 0, K.card); const ex = s < 0 ? x0 + hw : x0; ln(g, ex, fy, ex, fy + fh, K.mute, 1); rr(g, ex - s * 10 - 1.5, 92 - 12, 3, 24, 1.5, K.grid); });
    g.restore();
    rr(g, fx, fy, fw, fh, 10, null, K.grid, 1);
    b01Num(g, `X ∓${Math.round(c * 105)}%`, 160, 178);
    label(g, '中央から左右へ開く');
  } });

R({ id: 'trail-exit', dur: 1.7, bez: [.5, 0, .75, 0], still: .78,
  v: ['本体 + 残像 3 枚', '32ms ずつ遅れる', '520ms easeInQuart'], vEn: ['main + 3 copies', '32ms delay each', '520ms easeInQuart'],
  f(g, t) {
    const x0 = 72, D = 210, fin = seg(t, 0, .25, E.outCubic), ops = [1, .42, .24, .12];
    ln(g, 40, 128, 292, 128, K.grid, 1);
    alpha(g, .6, () => b01Dash(g, [3, 3], () => rr(g, x0 - 20, 80, 40, 40, 8, null, K.mute, 1)));
    for (let i = 3; i >= 0; i--) { const p = b01InQuart(seg(t, .5 + i * .032, 1.02 + i * .032, E.linear)), a = ops[i] * (1 - p) * fin;
      if (a > .004) alpha(g, a, () => { rr(g, x0 - 20 + D * p, 80, 40, 40, 8, K.red); if (!i) rr(g, x0 - 6 + D * p, 96, 12, 8, 4, K.paper); }); }
    const p0 = b01InQuart(seg(t, .5, 1.02, E.linear));
    b01Num(g, `x ${Math.round(p0 * 175)}  opacity ${Math.round((1 - p0) * 100)}%`, 160, 160, K.mute);
    label(g, '本体が先・残像が遅れる');
  } });

R({ id: 'collapse-away', dur: 2.6, bez: [.36, 0, .66, -.56], still: .85,
  v: ['origin bottom', 'scaleY 100 → 5%', '560ms easeInBack'], vEn: ['origin bottom', 'scaleY 100 → 5%', '560ms easeInBack'],
  f(g, t) {
    let sy, a; if (t < 1.9) { const p = E.inBack(seg(t, .5, 1.06, E.linear)); sy = lerp(1, .05, p); a = 1 - clamp(p * 1.1); } else { const r = seg(t, 1.9, 2.35, E.outCubic); sy = lerp(.05, 1, r); a = r; }
    alpha(g, a, () => xf(g, 160, 134, 1, sy, 0, () => xf(g, 0, -40, 1, 1, 0, () => b01Card(g, 160, 80))));
    b01Dash(g, [4, 3], () => ln(g, 62, 134, 258, 134, K.blue, 1.5));
    poly(g, [[160, 134], [154, 142], [166, 142]], K.blue);
    b01Num(g, 'origin', 262, 134, K.mute, 'left');
    b01Num(g, `scaleY ${Math.round(sy * 100)}%`, 112, 170); b01Num(g, `opacity ${Math.round(a * 100)}%`, 208, 170, K.mute);
    label(g, '下端を基準に畳む');
  } });

