// ---- ref-b03.js ----
// ===== モーションリファレンス b03：注目・光・エフェクト（MOTION ATLAS 方式）=====
// K.* の #rrggbb を分解して、透明度つき・混色の文字列を作る（グラデーション用）
function b03Rgb(h) { h = String(h); if (h[0] !== '#') return (h.match(/[\d.]+/g) || [0, 0, 0]).slice(0, 3).map(Number); const n = parseInt(h.slice(1), 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }
const b03A = (h, a) => { const c = b03Rgb(h); return `rgba(${c[0]},${c[1]},${c[2]},${clamp(a)})`; };
const b03Mix = (h1, h2, k) => { const a = b03Rgb(h1), b = b03Rgb(h2); return `rgb(${a.map((v, i) => Math.round(lerp(v, b[i], clamp(k)))).join(',')})`; };
// 0 → 1 → 0 の山（sin）
const b03Bump = (t, a, b) => Math.sin(clamp((t - a) / (b - a)) * Math.PI);
// 発光（光そのものを扱う項目だけで使う。shadowBlur ≤ 18）
function b03Glow(g, blur, fn) { g.save(); g.shadowColor = K.red; g.shadowBlur = Math.min(18, Math.max(0, blur)); fn(); g.restore(); }
// 区分一定（ネオンの通電のような段差）
function b03Step(p, keys) { let v = keys[0][1]; for (const [k, val] of keys) if (p >= k) v = val; return v; }
// 小さな数値読み出し（下中央）
function b03Read(g, s, x = 160, y = 186, c) { tx(g, s, x, y, { size: 10, f: 'm', w: 500, c: c || K.mute }); }
// 横長のゲージ（名前・値・塗り）
function b03Meter(g, name, v, x, y, w, col) { tx(g, name, x - 8, y + 2, { a: 'right', size: 9, f: 'm', w: 500, c: K.mute }); rr(g, x, y - 1, w, 6, 3, K.grid); rr(g, x, y - 1, Math.max(6, w * clamp(v)), 6, 3, col || K.red); }
// 風景の絵（写真の代わり）。x, y, w, h の中に描く
function b03Picture(g, x, y, w, h, r = 10) {
  g.save(); rr(g, x, y, w, h, r); g.clip();
  rr(g, x, y, w, h, 0, K.card);
  circ(g, x + w * .72, y + h * .34, h * .14, K.yel);
  poly(g, [[x, y + h], [x, y + h * .72], [x + w * .3, y + h * .38], [x + w * .55, y + h * .7], [x + w * .7, y + h * .52], [x + w, y + h * .8], [x + w, y + h]], K.red);
  poly(g, [[x, y + h], [x, y + h * .86], [x + w * .45, y + h * .74], [x + w, y + h * .9], [x + w, y + h]], K.blue);
  g.restore();
}

