    g.lineJoin = 'miter';
    // タイムライン
    const tl = 70, tw = 180;
    ln(g, tl, 166, tl + tw, 166, K.grid, 1);
    [0, .09, .14, .22, .31].forEach(k => ln(g, tl + k * tw, 162, tl + k * tw, 170, K.mute, 1));
    if (t > .3 && t < 1.2) circ(g, tl + clamp(p) * tw, 166, 3, K.red);
