    const tau = seg(t, .2, 2.4, E.linear), env = Math.sin(Math.PI * tau) ** 2, n = 26, y0 = 70, hh = 52, sh = hh / n;
    ln(g, 62, 60, 62, 132, K.grid, 1, [2, 3]); ln(g, 258, 60, 258, 132, K.grid, 1, [2, 3]);
