    rr(g, 20, 46, 14, 100, 7, null, K.grid, 1.5); rr(g, 23, 49 + p * (94 - 30), 8, 30, 4, K.blue);
    b04Num(g, 'scrollY', 27, 160, K.mute, 'center', 9);
    b04Num(g, t > 1.9 && t < 3.6 ? '↑' : '↓', 27, 34, K.mute, 'center', 12);
    b04View(g, 50, 46, 248, 100, () => {
      for (let i = 0; i < 5; i++) {
        const x = 62 + i * 112 - p * SH;
        rr(g, x, 58, 100, 76, 10, K.card, K.grid, 1); rr(g, x + 8, 66, 84, 34, 6, K.red);
        b04Num(g, '0' + (i + 1), x + 8, 117, K.ink, 'left', 10); rr(g, x + 32, 114, 52, 5, 2.5, K.mute); rr(g, x + 8, 124, 60, 5, 2.5, K.mute);
      }
    });
    rr(g, 50, 156, 248, 4, 2, K.grid); rr(g, 50, 156, 248 * p, 4, 2, K.red);
    b04Num(g, `x −${Math.round(p * SH)}px`, 298, 174, K.ink, 'right');
    b04Num(g, `${Math.round(p * 100)}%`, 50, 174, K.mute, 'left');
