        b04ClipRR(g, -112, -67, 224, 134, 10, () => { b04Scene(g, -112, -67, 224, 134); rr(g, -96, -52, 76, 10, 3, K.ink); rr(g, -96, -36, 50, 6, 3, K.mute); });
