R({ id: 'cursor-follow', dur: 3, ease: 'outCubic', still: 1.0,
  v: ['lerp 0.32 / 0.22 / 0.14 / 0.09', '後ろほど遅く小さく', '標準カーソルは残す'], vEn: ['lerp 0.32 / 0.22 / 0.14 / 0.09', 'later dots lag and shrink', 'keep the real cursor'],
  f(g, t) {
    const D = 3, pts = [[70, 62], [252, 70], [216, 146], [90, 138]];
    const ptr = u => { u = ((u % D) + D) % D; const i = Math.min(3, Math.floor(u / .75)), q = E.inOut(clamp((u - i * .75) / .5)), a = pts[i], b = pts[(i + 1) % 4]; return [lerp(a[0], b[0], q), lerp(a[1], b[1], q)]; };
    const fs = [.32, .22, .14, .09], R0 = [10, 8, 6.4, 5], n = 150, f0 = Math.floor(t * 60), fr = t * 60 - f0;
    let ps = fs.map(() => ptr((f0 - n) / 60));
    for (let i = n - 1; i >= 0; i--) { const q = ptr((f0 - i) / 60); ps = ps.map((p, k) => [p[0] + (q[0] - p[0]) * fs[k], p[1] + (q[1] - p[1]) * fs[k]]); }
    const q1 = ptr((f0 + 1) / 60); ps = ps.map((p, k) => [p[0] + (q1[0] - p[0]) * fs[k] * fr, p[1] + (q1[1] - p[1]) * fs[k] * fr]);
    b04Dash(g, [3, 4], () => poly(g, pts, null, K.grid, 1));
    for (let k = 3; k >= 0; k--) alpha(g, [1, .78, .58, .42][k], () => circ(g, ps[k][0], ps[k][1], R0[k], K.red));
    const [px, py] = ptr(t); cursor(g, px, py);
    for (let k = 0; k < 4; k++) { const x = 92 + k * 46; alpha(g, [1, .78, .58, .42][k], () => circ(g, x, 182, R0[k] * .6, K.red)); b04Num(g, fs[k].toFixed(2), x + 8, 182, K.mute, 'left', 9); }
    label(g, '先頭は速く / 後ろほど遅く小さく');
  } });

R({ id: 'drag-inertia', dur: 3.3, ease: 'outQuart', still: .95,
  v: ['離した速度を引き継ぐ', 'v *= 0.88 / frame', '境界を越えない'], vEn: ['keep release velocity', 'v *= 0.88 / frame', 'stays within bounds'],
  f(g, t) {
    const X0 = 64, D = 60, G = 117, LAM = 7.67, Y = 96, X1 = X0 + D + G * (1 - Math.exp(-LAM * 1.2));
    const pos = u => { if (u < .45) return X0; if (u < .65) return X0 + D * E.inCubic(seg(u, .45, .65, E.linear)); if (u < 1.85) return X0 + D + G * (1 - Math.exp(-LAM * (u - .65))); if (u < 2.05) return X1 - D * E.inCubic(seg(u, 1.85, 2.05, E.linear)); return X1 - D - (X1 - D - X0) * (1 - Math.exp(-LAM * (u - 2.05))) / (1 - Math.exp(-LAM * 1.25)); };
    const x = pos(t), vel = (pos(t + .004) - pos(t - .004)) / .008, held = (t >= .35 && t < .65) || (t >= 1.75 && t < 2.05);
    rr(g, 28, Y - 26, 264, 52, 26, null, K.grid, 1.5);
    [38, 282].forEach(bx => { ln(g, bx, Y - 16, bx, Y + 16, K.mute, 2); });
    const r0 = t < 1.85 ? .65 : 2.05, fade = t < 1.85 ? 1 - seg(t, 1.5, 1.8) : 1 - seg(t, 3.0, 3.3);
    if (t > r0) alpha(g, fade, () => { for (let u = r0; u <= t; u += 1 / 15) ln(g, pos(u), Y + 32, pos(u), Y + 40, K.mute, 1.5); });
    const sx = 1 + Math.min(.14, Math.abs(vel) / 6000), hs = held ? 1.06 : 1;
    xf(g, x, Y, sx * hs, hs / sx, 0, () => rr(g, -18, -18, 36, 36, 8, K.red));
    let cx, cy = Y + 6;
    if (t < .35) { const q = seg(t, .02, .35, E.outCubic); cx = lerp(160, X0 + 4, q); cy = lerp(170, Y + 6, q); }
    else if (t < .65) cx = x + 4;
    else if (t < 1.75) cx = lerp(pos(.65) + 4 + 22 * E.outCubic(seg(t, .65, 1.0)), X1 + 4, seg(t, 1.25, 1.75, E.inOut));
    else if (t < 2.05) cx = x + 4;
    else { const q = seg(t, 2.6, 3.2, E.inOut); cx = lerp(pos(2.05) + 4 - 22 * E.outCubic(seg(t, 2.05, 2.4)), 160, q); cy = lerp(Y + 6, 170, q); }
    cursor(g, cx, cy, held ? 1 : 0);
    b04Num(g, `v ${Math.round(Math.abs(vel))} px/s`, 160, 150, held ? K.mute : K.ink);
    b04Num(g, 'v × 0.88 / frame', 160, 166, K.mute, 'center', 9);
    label(g, '離した速度で滑って止まる');
  } });

