    b05Cur(g, t, [[0, 176], [.06, 176], [.28, 104], [2.3, 104], [2.7, 176]], [[0, 120], [.06, 120], [.28, 154], [2.3, 154], [2.7, 120]], [[.3, .4], [1.7, 1.8]]);
