    circ(g, 40, 172, 4, null, K.ink, 1.2); circ(g, 280, 172, 4, null, K.ink, 1.2);
    tx(g, '0s', 40, 184, { size: 9, w: 500, f: 'm', c: K.mute }); tx(g, '2.8s', 280, 184, { size: 9, w: 500, f: 'm', c: K.mute }); tx(g, '=', 160, 184, { size: 10, f: 'm', c: K.mute });
