// ---- ref-b07.js ----
// ===== モーションリファレンス b07：UI コントロール・ローディング・フィードバック =====
const b07TabX = [88, 160, 232], b07Tabs = ['HOME', 'WORK', 'SAVE'];
const b07Moves = [[.3, 0, 1], [1.15, 1, 2], [2.0, 2, 0]];
// タブの選択インデックス（最後に始まった移動の行き先）
function b07Sel(t, moves) { let s = moves[0][1]; moves.forEach(([t0, a, b]) => { if (t >= t0) s = b; }); return s; }
// 先端と後端を時間差で動かす（進行方向の端が先行）
function b07Edges(t, moves, w, fastD = .26, lag = .09, slowD = .34) {
  let L = b07TabX[moves[0][1]] - w / 2, R = L + w;
  moves.forEach(([t0, a, b]) => { const d = b07TabX[b] - b07TabX[a], f = seg(t, t0, t0 + fastD, E.outCubic), s = seg(t, t0 + lag, t0 + lag + slowD, E.inOutCubic); if (d > 0) { R += d * f; L += d * s; } else { L += d * f; R += d * s; } });
  return [L, R];
}
// 液体のように 2 つの円をつなぐ（x 軸方向・y=0 基準）
function b07Goo(g, xa, ra, xb, rb, c, reach = 70, start = .4) {
  if (xa > xb) { [xa, xb] = [xb, xa]; [ra, rb] = [rb, ra]; }
  circ(g, xa, 0, ra, c); circ(g, xb, 0, rb, c);
  const d = xb - xa, n = Math.min(ra, rb) * .82 * (1 - clamp((d - (ra + rb) * start) / reach));
  if (n > .4 && d > 1) { const m = (xa + xb) / 2; g.beginPath(); g.moveTo(xa, -ra * .82); g.quadraticCurveTo(m, -n, xb, -rb * .82); g.lineTo(xb, rb * .82); g.quadraticCurveTo(m, n, xa, ra * .82); g.closePath(); g.fillStyle = c; g.fill(); }
}
// 折れ線を途中まで描く
function b07Path(g, pts, p, c, w) {
  if (p <= 0) return; let L = 0; const ls = []; for (let i = 1; i < pts.length; i++) { const l = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); ls.push(l); L += l; }
  let rem = L * clamp(p); g.beginPath(); g.moveTo(...pts[0]);
  for (let i = 1; i < pts.length && rem > 0; i++) { const k = Math.min(1, rem / ls[i - 1]); g.lineTo(lerp(pts[i - 1][0], pts[i][0], k), lerp(pts[i - 1][1], pts[i][1], k)); rem -= ls[i - 1]; }
  g.strokeStyle = c; g.lineWidth = w; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';
}
function b07Heart(g, x, y, r, fill, stroke, lw) { poly(g, shapePts('heart', x, y, r, 48), fill, stroke, lw); }
function b07TabLabels(g, k) { b07Tabs.forEach((s, i) => { tx(g, s, b07TabX[i], 96, { size: 12, f: 'm', w: 700, c: K.mute }); alpha(g, k(i), () => tx(g, s, b07TabX[i], 96, { size: 12, f: 'm', w: 700, c: K.ink })); }); }

