    if (h > .05) alpha(g, h * .8, () => { g.setLineDash([2, 4]); circ(g, 0, 0, 26 * Math.SQRT2 * .72, null, K.mute, 1); g.setLineDash([]); });
    const c = h > .5 ? K.red : K.ink, R = lerp(26, 13, h), Lg = 9 * (1 - h), D = 8 * h;
