    for (let i = 0; i < 5; i++) { const s = b08Pop(tt, 1.3 + i * .07, .25); if (s > 0) alpha(g, a, () => star(g, CX - 40 + i * 20, CY + 30, 7 * s, 3 * s, 5, K.red)); }
