    const bp = seg(tt, dt, dt + .45, E.outCubic); if (bp > 0 && bp < 1) alpha(g, 1 - bp, () => rr(g, CX - 32 - bp * 16, CY - 32 - bp * 16, 64 + bp * 32, 64 + bp * 32, 14 + bp * 8, null, K.blue, 2));
