    const fade = 1 - seg(t, .85, 1.25); if (t > .85 && fade > 0) alpha(g, fade, () => { const off = (1 - fade) * 30; ln(g, X(20) + off, 20, X(180) + off, 180, K.red, 2 * fade); });
    if (p > .3 && p < 1) for (let i = 0; i < 4; i++) { const y = 84 + i * 12, x = X(y); if (x > 80 && x < 240) circ(g, x + 4, y, 2, K.yel); }
    alpha(g, 1 - out, () => rr(g, 112, 132, 96 * seg(t, .9, 1.2, E.outCubic), 3, 1.5, K.red));
