    const swing = seg(t, .25, hit, E.inCubic), defl = seg(t, rel, rel + .45, E.outExpo), wob = t > rel ? .08 * Math.exp(-(t - rel) * 6) * Math.sin((t - rel) * 30) : 0;
    let aA = lerp(-.35, ac, swing), aB = -aA; if (t > rel) { aA = lerp(ac, -.62, defl) + wob; aB = -aA; } if (t > 3.6) { aA = lerp(-.62, -.35, back); aB = -aA; }
    const frz = t > hit && t < rel;
    if (frz) { const q = seg(t, hit, hit + .12, E.outCubic); alpha(g, .7, () => { ln(g, C[0] - 150 * q, C[1] - 6, C[0] + 150 * q, C[1] - 6, K.red, 1); ln(g, C[0] - 150 * q, C[1] + 6, C[0] + 150 * q, C[1] + 6, K.red, 1); }); tx(g, '0.30s', C[0] + 120, C[1] - 16, { size: 9, f: 'm', w: 600, c: K.red }); }
