    const mx = kf(t, [[0, 300], [.35, 300], [1.15, 214], [1.7, 202], [2.5, 210], [3.25, 304], [4.2, 304]], E.inOut),
      my = kf(t, [[0, 186], [.35, 186], [1.15, 128], [1.7, 116], [2.5, 124], [3.25, 190], [4.2, 190]], E.inOut);
    const p = track(t, [[0, 0], [.75, 1], [2.75, 0]], 140, 18);
    const dx = clamp((mx - 160) / 90, -1, 1), dy = clamp((my - 100) / 70, -1, 1);
    const ry = dx * .34 * p, rx = -dy * .28 * p, z = -40 * p;
    b10Dash(g, () => rr(g, 90, 55, 140, 90, 8, null, K.mute, 1));
