      alpha(g, a, () => xf(g, x, y, s, s, 0, () => { rr(g, -48, -18, 96, 36, 10, front ? K.red : K.card, front ? null : K.line, 1.5); tx(g, names[i], 0, 1, { size: 14, f: 'm', w: 700, c: front ? K.paper : K.ink }); }));
