// 5. 遠近ドック
R({ id: 'catalog-ui-spatial-perspective-dock', dur: 4.2, ease: 'outCubic',
  v: ['scale = 1 + .7·e^−(d/40)²', '中心 ×1.7 + 持ち上げ 10px', 'spring 220/24'], vEn: ['scale = 1 + .7·e^−(d/40)²', 'center ×1.7 + lift 10px', 'spring 220/24'], still: 2.2,
  f(g, t) {
    label(g, '距離 → 拡大率');
    const mx = kf(t, [[0, 26], [.35, 26], [1.4, 160], [2.7, 160], [3.6, 296], [4.2, 296]], E.inOut), on = track(t, [[0, 0], [.55, 1], [3.35, 0]], 220, 24);
    const gauss = x => Math.exp(-(((x - mx) / 40) ** 2));
    // ガイド：拡大率のカーブ
    g.beginPath(); for (let x = 40; x <= 280; x += 4) g.lineTo(x, 84 - 34 * on * gauss(x)); g.strokeStyle = K.grid; g.lineWidth = 1.5; g.stroke();
    ln(g, 40, 84, 280, 84, K.grid, 1, [2, 3]);
    const n = 7, base = 26, gap = 7, sz = [];
    for (let i = 0; i < n; i++) sz.push(base * (1 + .7 * on * gauss(160 + (i - 3) * (base + gap))));
    const tot = sz.reduce((a, b) => a + b, 0) + gap * (n - 1);
    rr(g, 160 - tot / 2 - 10, 146, tot + 20, 36, 12, K.card, K.grid, 1);
    let x = 160 - tot / 2;
    for (let i = 0; i < n; i++) {
      const s = sz[i], k = (s / base - 1) / .7, lift = 10 * k * k, cx = x + s / 2, by = 176 - lift;
      rr(g, x, by - s, s, s, s * .26, i === 3 ? K.red : K.ink);
      b10Icon(g, i, cx, by - s / 2, K.paper);
      if (i === 3) alpha(g, clamp(on * 2 - .5), () => b10Read(g, '×' + (s / base).toFixed(2), cx, by - s - 9, 'center', K.ink));
      x += s + gap;
    }
    alpha(g, seg(t, 0, .25) * (1 - seg(t, 3.85, 4.1)), () => cursor(g, mx, 168));
  } });

