// ---- ref-b11.js ----
// ===== モーションリファレンス b11：UI マテリアル（液体・ジェル・ガラス・紙・布・金属）=====

// 2 つの円を液体の首でつなぐ（横並び・x1 < x2）。wm = 首の中央の半幅
function b11Neck(g, x1, y, r1, x2, r2, wm, fill) {
  if (wm <= .25 || x2 - x1 < 1) return;
  const f = clamp(wm / Math.min(r1, r2)), ph = lerp(.55, 1.45, f), c1 = Math.cos(ph), s1 = Math.sin(ph);
  const ax = x1 + r1 * c1, ay = r1 * s1, bx = x2 - r2 * c1, by = r2 * s1, mx = (ax + bx) / 2, cy = 2 * wm - (ay + by) / 2;
  g.beginPath(); g.moveTo(ax, y - ay); g.quadraticCurveTo(mx, y - cy, bx, y - by); g.lineTo(bx, y + by); g.quadraticCurveTo(mx, y + cy, ax, y + ay); g.closePath();
  g.fillStyle = fill; g.fill();
}
// 数値微分（速度）— 純粋関数の位置から求める
const b11Vel = (fn, t, h = .004) => (fn(t + h) - fn(t - h)) / (2 * h);
// 折れ線（複数）を先頭から len だけ描く。先端の座標を返す
function b11Path(g, subs, len) {
  g.beginPath(); let rem = len, head = null;
  for (const pts of subs) {
    if (rem <= 0) break; g.moveTo(pts[0][0], pts[0][1]); head = pts[0];
    for (let k = 1; k < pts.length && rem > 0; k++) { const [ax, ay] = pts[k - 1], [bx, by] = pts[k], d = Math.hypot(bx - ax, by - ay), u = Math.min(1, rem / d); head = [lerp(ax, bx, u), lerp(ay, by, u)]; g.lineTo(head[0], head[1]); rem -= d; }
  }
  return head;
}
const b11Len = subs => subs.reduce((s, pts) => s + pts.reduce((a, p, i) => i ? a + Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1]) : 0, 0), 0);

// ---------- 液体タブブリッジ ----------
R({ id: 'catalog-ui-material-liquid-tab-bridge', dur: 4.2, ease: 'inOutCubic',
  v: ['橋 11px → 2px で切れる', '移動 900ms', '到着で弾む'], vEn: ['bridge 11px → 2px, then cut', 'travel 900ms', 'bounce on arrival'], still: .95,
  f(g, t) {
    const xs = [96, 160, 224], y = 100, R0 = 15;
    const mv = t < 2.5 ? { t0: .4, a: 96, b: 224 } : { t0: 2.5, a: 224, b: 96 };
    const X = u => lerp(mv.a, mv.b, seg(u, mv.t0, mv.t0 + .9, E.inOutCubic)), x = X(t), p = clamp((x - mv.a) / (mv.b - mv.a));
    let tb = mv.t0 + 2; for (let s = mv.t0; s < mv.t0 + 1; s += .005) if ((X(s) - mv.a) / (mv.b - mv.a) >= .88) { tb = s; break; }
    rr(g, 56, y - 26, 208, 52, 26, K.card, K.grid, 1);
    const v = b11Vel(X, t), sx = 1 + Math.min(.42, Math.abs(v) / 1500), dir = Math.sign(mv.b - mv.a);
    // 残る滴と橋
    if (t > mv.t0 && t < tb + .4) {
      const ro = t < tb ? lerp(R0, 6, clamp(p / .88)) : 6 * (1 - seg(t, tb, tb + .32, E.inCubic)), wm = lerp(5.5, 1, clamp(p / .88));
      circ(g, mv.a, y, ro, K.red);
      if (t < tb) { const l = Math.min(mv.a, x), r = Math.max(mv.a, x); b11Neck(g, l, y, dir > 0 ? ro : R0 / sx, r, dir > 0 ? R0 / sx : ro, wm, K.red); }
      else { const k = 1 - seg(t, tb, tb + .18, E.outCubic), tip = 22 * k; if (k > 0) { g.beginPath(); g.moveTo(x - dir * (R0 * .9), y - 4 * k); g.lineTo(x - dir * (R0 + tip), y); g.lineTo(x - dir * (R0 * .9), y + 4 * k); g.closePath(); g.fillStyle = K.red; g.fill(); } }
    }
    // 着地の小さな弾み
    const ta = mv.t0 + .9, land = t > ta ? .16 * Math.exp(-(t - ta) * 7) * Math.sin((t - ta) * 26) : 0;
    xf(g, x, y, sx - land, 1 / (sx - land), 0, () => circ(g, 0, 0, R0, K.red));
    // タブのアイコン
    xs.forEach((cx, i) => { const on = Math.abs(cx - x) < 15, c = on ? K.paper : K.mute;
      if (i === 0) circ(g, cx, y, 5.5, null, c, 1.8); else if (i === 1) rr(g, cx - 5.5, y - 5.5, 11, 11, 2, null, c, 1.8); else poly(g, [[cx, y - 6.5], [cx + 6.5, y + 5], [cx - 6.5, y + 5]], null, c, 1.8); });
    ['A', 'B', 'C'].forEach((s, i) => tx(g, s, xs[i], y + 40, { size: 10, f: 'm', w: 500, c: Math.abs(xs[i] - x) < 15 ? K.ink : K.mute }));
    label(g, mv.a < mv.b ? 'A → C' : 'C → A');
    const live = t > mv.t0 && t < tb, br = live ? (lerp(5.5, 1, clamp(p / .88)) * 2).toFixed(1) + 'px' : (t >= tb && t < tb + .9 ? L('切れる') : '—');
    tx(g, `bridge ${br}`, 160, 172, { size: 10, f: 'm', w: 500, c: live ? K.ink : K.mute });
  } });

// ---------- ジェルボタン分裂 ----------
function b11Pill(g, cx, y, sx, sy, fill) { const w = 60 * sx, h = 44 * sy; rr(g, cx - w / 2, y - h / 2, w, h, h / 2, fill); return { r: h / 2, off: w / 2 - h / 2 }; }
R({ id: 'catalog-ui-material-gel-button-split', dur: 4.2, ease: 'inQuad',
  v: ['両側と首を同時に伸ばす', '首 0px で分裂', '分裂後 spring 300 / 9'], vEn: ['stretch both sides + neck together', 'split when neck hits 0px', 'after split: spring 300 / 9'], still: 2.0,
  f(g, t) {
    const y = 100, tS = 1.3;
    let d = t < .3 ? 22 : t < .5 ? lerp(22, 18, seg(t, .3, .5, E.outCubic)) : t < tS ? lerp(18, 54, seg(t, .5, tS, E.inQuad)) : lerp(54, 74, spring(t - tS, 260, 12));
    if (t > 3.0) d = lerp(74, 22, spring(t - 3.0, 200, 22));
    let sx = t < .3 ? 1 : t < .5 ? lerp(1, .94, seg(t, .3, .5, E.outCubic)) : t < tS ? lerp(.94, 1.16, seg(t, .5, tS, E.inQuad)) : 1 + .16 * (1 - spring(t - tS, 300, 9));
    if (t > 3.0) sx = 1 + .05 * Math.sin(seg(t, 3.0, 3.5) * Math.PI);
    const sy = 1 / Math.sqrt(sx);
    const neckGone = t >= tS && t < 3.0 + .18, wm = neckGone ? 0 : 22 * sy * Math.pow(clamp(1 - (d - 22) / 32), 1.4);
    const L1 = b11Pill(g, 160 - d, y, sx, sy, K.red), R1 = b11Pill(g, 160 + d, y, sx, sy, K.red);
    b11Neck(g, 160 - d + L1.off, y, L1.r, 160 + d - R1.off, R1.r, wm, K.red);
    tx(g, 'A', 160 - d - 4 * (1 - clamp((d - 22) / 20)), y + 1, { size: 15, f: 'd', c: K.paper });
    tx(g, 'B', 160 + d + 4 * (1 - clamp((d - 22) / 20)), y + 1, { size: 15, f: 'd', c: K.paper });
    // 引っ張る方向のガイド
    const pull = seg(t, .5, .7) * (1 - seg(t, tS, tS + .3));
    alpha(g, pull, () => { [-1, 1].forEach(s => { const x0 = 160 + s * (d + 40 * sx), x1 = x0 + s * 22; ln(g, x0, y, x1, y, K.mute, 1.5); ln(g, x1, y, x1 - s * 6, y - 5, K.mute, 1.5); ln(g, x1, y, x1 - s * 6, y + 5, K.mute, 1.5); }); });
    label(g, '1 → 2');
    tx(g, wm > .3 ? `neck ${Math.round(wm * 2)}px` : L('分裂'), 160, 160, { size: 10, f: 'm', w: 500, c: wm > .3 ? K.ink : K.red });
  } });

