// ---------- インク吸着 ----------
R({ id: 'catalog-ui-material-ink-adhesion', dur: 4.2, ease: 'inQuad',
  v: ['落下 stretch 1.35', '接触 squash 1.8 × 0.55', '縁で垂れて合流'], vEn: ['fall stretch 1.35', 'contact squash 1.8 × 0.55', 'drips at the edge, joins pool'], still: 1.5,
  f(g, t) {
    const top = 80, cx = 120, edge = 196, ex = edge, fade = 1 - seg(t, 3.45, 3.95), tm = 2.45;
    // インク溜まり（トレイ）— 合流点から波紋
    const lvl = 158 - 5 * seg(t, tm, tm + .5, E.outCubic) * fade;
    const pts = [[60, 178]]; for (let x = 60; x <= 282; x += 3) { const dx = Math.abs(x - ex), tt = t - tm; let dy = 0; if (tt > 0 && dx < tt * 130) dy = 5 * fade * Math.exp(-tt * 2.4) * Math.exp(-dx / 60) * Math.sin(dx * .17 - tt * 15); pts.push([x, lvl + dy]); } pts.push([282, 178]);
    g.save(); rr(g, 62, 130, 216, 46, 10); g.clip(); poly(g, pts, K.red); g.restore();
    rr(g, 60, 128, 220, 50, 12, null, K.grid, 1.5);
    // 面（棚）
    rr(g, 44, top, edge - 44, 12, 3, K.card, K.mute, 1);
    // 落ちる滴（縦に伸びる）
    if (t < .75) { const p = seg(t, .3, .75, E.inQuad), s = 1 + .38 * p, yy = lerp(30, top - 11 * s, p); alpha(g, seg(t, .05, .3), () => xf(g, cx, yy, 1 / s, s, 0, () => circ(g, 0, 0, 11, K.red))); }
    else alpha(g, fade, () => {
      // 付着：横へつぶれてから広がる
      const k1 = seg(t, .75, .87, E.outCubic), s = seg(t, .9, 1.6, E.outCubic), tw = t - .87, wob = tw > 0 ? 2.5 * Math.exp(-tw * 6) * Math.sin(tw * 24) : 0;
      const lft = cx - lerp(lerp(10, 27, k1), 30, s), rgt = cx + lerp(lerp(10, 27, k1), edge - cx, s), hh = lerp(lerp(16, 7, k1), 5.5, s) + wob - 2 * seg(t, 2.0, 2.4);
      const pp = [[lft, top + .5]]; for (let i = 0; i <= 28; i++) { const u = i / 28, x = lerp(lft, rgt, u); pp.push([x, top - Math.max(1.5, hh) * Math.pow(Math.sin(u * Math.PI), .4)]); } pp.push([rgt, top + .5]); poly(g, pp, K.red);
      if (t < 1.0) { const k = seg(t, .75, 1.0); alpha(g, 1 - k, () => tx(g, 'squash', cx, top - 26, { size: 9, f: 'm', w: 500, c: K.mute })); }
      // 縁を回り込んで垂れる → 首が細くなって分離
      if (t > 1.4) {
        const gp = seg(t, 1.4, 2.0, E.inOut), wrap = clamp((t - 1.4) / .2) * (1 - seg(t, 2.25, 2.6));
        if (wrap > 0) rr(g, ex - 3, top - 1, 6, 14 * wrap, 3, K.red);
        if (t < 2.12) { const rb = 8 * gp, by = top + 12 + rb * 1.25 + 10 * seg(t, 1.85, 2.12, E.inQuad), st = 1 + .35 * gp;
          const nw = 2.6 * (1 - seg(t, 1.9, 2.12)); if (nw > .3) rr(g, ex - nw, top + 9, nw * 2, by - top - 9, nw, K.red);
          xf(g, ex, by, 1 / st, st, 0, () => circ(g, 0, 0, rb, K.red)); }
        else if (t < tm) { const p = seg(t, 2.12, tm, E.inQuad), yy = lerp(top + 34, lvl - 6, p); xf(g, ex, yy, .78, 1.4, 0, () => circ(g, 0, 0, 7, K.red)); }
      }
    });
    label(g, '落下 → 付着 → 合流');
  } });

// ---------- メタリック箔チルト ----------
R({ id: 'catalog-ui-material-metallic-foil', dur: 4.2, ease: 'inOut',
  v: ['rotateY ±24°', '反射帯 = 傾きに同期', '光は逆側へ'], vEn: ['rotateY ±24°', 'light band synced to tilt', 'band moves opposite'], still: 1.3,
  f(g, t) {
    const a = kf(t, [[0, 0], [.3, 0], [1.2, -.42], [1.6, -.42], [2.7, .42], [3.1, .42], [3.9, 0], [4.2, 0]], E.inOut);
    const P = (x, y) => { const z = x * Math.sin(a), s = 380 / (380 + z); return [160 + x * Math.cos(a) * s, 94 + y * s]; };
    const M = (u, v) => P(lerp(-72, 72, u), lerp(-46, 46, v));
    const quad = [M(0, 0), M(1, 0), M(1, 1), M(0, 1)];
    alpha(g, .3, () => xf(g, 160, 162, Math.cos(a) * .9, .12, 0, () => circ(g, 0, 0, 72, K.grid)));
    g.save(); poly(g, quad, K.card); g.clip();
    alpha(g, .78, () => poly(g, quad, K.red));
    // 反射帯（傾きと逆へ流れる）
    const u = .58 - a / .42 * .34, sk = .16;
    alpha(g, .28, () => poly(g, [M(u - .16, 0), M(u + .12, 0), M(u + .12 - sk, 1), M(u - .16 - sk, 1)], K.ink));
    alpha(g, .75, () => poly(g, [M(u - .03, 0), M(u + .015, 0), M(u + .015 - sk, 1), M(u - .03 - sk, 1)], K.ink));
    alpha(g, .55, () => poly(g, [M(u + .06, 0), M(u + .085, 0), M(u + .085 - sk, 1), M(u + .06 - sk, 1)], K.ink));
    alpha(g, Math.abs(a) * .7, () => poly(g, quad, K.paper));
    g.restore();
    poly(g, quad, null, K.ink, 1);
    // チップと文字（傾きに合わせて横を縮める）
    const c0 = M(.12, .22), c1 = M(.27, .22), c2 = M(.27, .46), c3 = M(.12, .46); poly(g, [c0, c1, c2, c3], null, K.paper, 1.5);
    const tp = M(.62, .74), tw = (M(.9, .74)[0] - M(.34, .74)[0]) / 80;
    xf(g, tp[0], tp[1], tw, 1, 0, () => tx(g, 'FOIL', 0, 0, { size: 20, f: 'd', c: K.paper }));
    cursor(g, 160 + a / .42 * 84, 132);
    label(g, '傾き ↔ 反射帯');
    tx(g, `rotateY ${Math.round(a * 57.3)}°`, 24, 182, { a: 'left', size: 10, f: 'm', w: 500, c: K.ink });
    tx(g, `band ${Math.round(clamp(u) * 100)}%`, 296, 182, { a: 'right', size: 10, f: 'm', w: 500, c: K.red });
  } });

// ---------- ソフトボディトグル ----------
R({ id: 'catalog-ui-material-soft-body-toggle', dur: 4.2, ease: 'inOutCubic',
  v: ['押す scale 1.12 × 0.85', '移動中 stretch 1.4', '到着 squash → spring'], vEn: ['press scale 1.12 × 0.85', 'travel stretch 1.4', 'arrive squash → spring'], still: .75,
  f(g, t) {
    const y = 104, r = 17, xa = 134, xb = 186;
    const on = t < 2.4, t0 = on ? .4 : 2.4, from = on ? xa : xb, to = on ? xb : xa, dir = Math.sign(to - from), tt = t - t0;
    const p = seg(tt, .15, .48, E.inOutCubic);
    let sx, x = lerp(from, to, p);
    if (tt < 0) sx = 1;
    else if (tt < .15) sx = lerp(1, 1.12, seg(tt, 0, .15, E.outCubic));
    else if (tt < .48) sx = lerp(1.12, 1, seg(tt, .15, .3)) + .4 * Math.sin(seg(tt, .15, .48) * Math.PI);
    else sx = 1 - .22 * (1 - spring(tt - .48, 420, 11));
    let sy = 1 / sx; if (tt >= 0 && tt < .15) sy = lerp(1, .85, seg(tt, 0, .15, E.outCubic));
    if (tt >= .48) x = to + dir * (r - r * sx) * 1;
    const onK = on ? seg(tt, .15, .48) : 1 - seg(tt, .15, .48);
    rr(g, 108, y - 24, 104, 48, 24, K.grid);
    alpha(g, onK, () => rr(g, 108, y - 24, 104, 48, 24, K.red));
    alpha(g, .25, () => xf(g, x, y + 3, sx, sy, 0, () => circ(g, 0, 0, r, K.paper)));
    xf(g, x, y, sx, sy, 0, () => circ(g, 0, 0, r, K.ink));
    const cx = kf(t, [[0, xa + 4], [1.5, xa + 4], [2.1, xb + 4], [3.4, xb + 4], [4.05, xa + 4], [4.2, xa + 4]], E.inOut);
    const press = (t > .4 && t < .58) || (t > 2.4 && t < 2.58) ? 1 : 0;
    cursor(g, cx, y + 8, press);
    label(g, '押す → 伸びる → 戻る');
    tx(g, `scaleX ${sx.toFixed(2)}`, 160, 160, { size: 10, f: 'm', w: 500, c: Math.abs(sx - 1) > .03 ? K.red : K.mute });
  } });

