    const H_ = u => track(u, keys, 220, 16), B_ = u => track(u, keys, 70, 16);
    const hx = X(Math.min(1.02, H_(t))), bx = X(Math.min(1, B_(t))), v = b11Vel(H_, t) * 220;
    const a = seg(t, 0, .25) * (1 - seg(t, 3.4, 3.8));
