    const px = PX(t), v = b11Vel(PX, t), o = clamp(Math.abs(v) / 230) * 6 * Math.sign(v), w = 112, h = 80, y = 100;
    for (let x = 24; x < 300; x += 22) rr(g, x, 46, 10, 108, 3, K.grid);
