// ---------- ペーパーフォールド ----------
R({ id: 'catalog-ui-material-paper-fold', dur: 4.2, ease: 'inOut',
  v: ['折り目 x 固定', 'rotateY 0 → 180°', '角度で暗く（最大 55%）'], vEn: ['crease x fixed', 'rotateY 0 → 180°', 'darken by angle (max 55%)'], still: 2.0,
  f(g, t) {
    const th = Math.PI * (seg(t, .4, 1.5, E.inOut) - seg(t, 2.6, 3.6, E.inOut)), c = Math.cos(th), s = Math.sin(th);
    const P = (xl, yl) => { const X = xl * c, Z = xl * s, k = 420 / (420 - Z); return [160 + X * k, 100 + yl * k]; };
    // 下の面（左は白紙、右は中面）
    rr(g, 80, 52, 80, 96, 0, K.card); rr(g, 160, 52, 80, 96, 0, K.card);
    rr(g, 80, 52, 160, 96, 8, null, K.grid, 1);
    tx(g, 'INSIDE', 200, 82, { size: 12, f: 'd', c: K.red });
    rr(g, 176, 100, 48, 6, 3, K.mute); rr(g, 176, 112, 36, 6, 3, K.mute); rr(g, 176, 124, 42, 6, 3, K.mute);
    // 落ちる影
    if (s > .01) alpha(g, .45 * s, () => poly(g, [[160, 52], [160 + 80 * Math.max(0, c) + 10 * s, 56], [160 + 80 * Math.max(0, c) + 10 * s, 148], [160, 148]], K.paper));
    const quad = [P(0, -48), P(80, -48), P(80, 48), P(0, 48)];
    if (c >= 0) {
      poly(g, quad, K.red);
      const m = P(40, 0), sc = (P(80, 0)[0] - 160) / 80;
      if (sc > .08) xf(g, m[0], m[1], sc, 1, 0, () => tx(g, 'OPEN', 0, 0, { size: 14, f: 'd', c: K.paper }));
    } else {
      poly(g, quad, K.line);
      [[14, -24, 46], [14, -12, 34], [14, 0, 40]].forEach(([x0, yy, ww]) => poly(g, [P(x0, yy), P(x0 + ww * .9, yy), P(x0 + ww * .9, yy + 5), P(x0, yy + 5)], K.mute));
    }
    alpha(g, .55 * s, () => poly(g, quad, K.paper));
    poly(g, quad, null, c >= 0 ? K.red : K.mute, 1);
    ln(g, 160, 40, 160, 160, K.mute, 1, [3, 3]);
    label(g, '折り目を軸に回転');
    tx(g, `${Math.round(th * 57.3)}°`, 160, 176, { size: 10, f: 'm', w: 500, c: K.ink });
  } });

// ---------- クロスウェーブパネル ----------
R({ id: 'catalog-ui-material-cloth-wave', dur: 4.2, ease: 'sine',
  v: ['18 本の帯', '隣どうし +45ms', '振幅 9px → 0'], vEn: ['18 strips', '+45ms per neighbour', 'amplitude 9px → 0'], still: 1.2,
  f(g, t) {
    const N = 18, sw = 11, x0 = 160 - N * sw / 2, yt = 56, yb = 144;
    const dy = i => { const tau = t - .3 - i * .045; if (tau <= 0) return 0; return 9 * seg(tau, 0, .35) * (1 - seg(tau, 1.4, 2.3, E.inOut)) * Math.sin(tau * TAU / .85); };
    rr(g, x0, yt, N * sw, yb - yt, 0, null, K.grid, 1);
    for (let i = 0; i < N; i++) {
      const a = dy(i), b = dy(i + 1), xa = x0 + i * sw, xb = xa + sw, q = [[xa, yt + a], [xb, yt + b], [xb, yb + b * 1.25], [xa, yb + a * 1.25]];
      poly(g, q, K.red);
      const sl = b - a; if (sl > 0) alpha(g, Math.min(.5, sl * .09), () => poly(g, q, K.paper)); else alpha(g, Math.min(.4, -sl * .07), () => poly(g, q, K.ink));
      if (i) ln(g, xa, yt + a, xa, yb + a * 1.25, K.paper, .6);
    }
    // 位相のずれを見せる点
    for (let i = 0; i <= N; i += 3) circ(g, x0 + i * sw, 168 + dy(i) * .4, 2, Math.abs(dy(i)) > 1 ? K.red : K.mute);
    ln(g, x0, 182, x0 + N * sw, 182, K.grid, 1); ln(g, x0 + N * sw, 182, x0 + N * sw - 5, 179, K.grid, 1); ln(g, x0 + N * sw, 182, x0 + N * sw - 5, 185, K.grid, 1);
    label(g, '帯ごとに 45ms 遅れ');
  } });

// ---------- バブル結合メニュー ----------
R({ id: 'catalog-ui-material-bubble-merge', dur: 4.2, spring: [220, 16, 1],
  v: ['接触までは円のまま', '首 0.15s → 大きい面', 'spring 220 / 16'], vEn: ['stay circles until contact', 'neck 0.15s → larger surface', 'spring 220 / 16'], still: 2.2,
  f(g, t) {
    const y = 100, r = 24;
    if (t < 1.25 || t >= 3.25) {
      let d, wm = 0;
      if (t < 1.1) d = kf(t, [[0, 88], [.3, 88], [1.1, 24]], E.inQuad);
      else if (t < 1.25) { d = lerp(24, 19, seg(t, 1.1, 1.25)); wm = r * seg(t, 1.1, 1.25, E.outCubic); }
      else if (t < 3.4) { d = lerp(19, 24, seg(t, 3.25, 3.4)); wm = r * (1 - seg(t, 3.25, 3.4, E.inCubic)); }
      else d = lerp(24, 88, seg(t, 3.4, 4.0, E.outCubic));
      const sq = t < 1.1 ? .08 * seg(t, .8, 1.1, E.inQuad) : 0;
      xf(g, 160 - d, y, 1 + sq, 1 - sq, 0, () => circ(g, 0, 0, r, K.red)); xf(g, 160 + d, y, 1 + sq, 1 - sq, 0, () => circ(g, 0, 0, r, K.red));
      b11Neck(g, 160 - d, y, r, 160 + d, r, wm, K.red);
      const la = t < 1.25 ? 1 - seg(t, 1.05, 1.2) : seg(t, 3.5, 3.8);
      alpha(g, la, () => { tx(g, 'A', 160 - d, y + 1, { size: 15, f: 'd', c: K.paper }); tx(g, 'B', 160 + d, y + 1, { size: 15, f: 'd', c: K.paper }); });
      const ga = t < 1.1 ? 1 : t >= 3.4 ? seg(t, 3.85, 4.15) : 0; if (ga > 0 && d > 26) alpha(g, ga, () => { const gap = Math.round(2 * d - 2 * r); ln(g, 160 - d + r, y + 38, 160 + d - r, y + 38, K.mute, 1); tx(g, `gap ${gap}px`, 160, y + 52, { size: 10, f: 'm', w: 500, c: K.mute }); });
    } else {
      const k = t < 3.0 ? spring(t - 1.25, 220, 16) : 1 - seg(t, 3.0, 3.25, E.inCubic);
      const w = lerp(86, 156, k), h = lerp(48, 58, k);
      rr(g, 160 - w / 2, y - h / 2, w, h, h / 2, K.red);
      alpha(g, seg(t, 1.45, 1.7) * (1 - seg(t, 2.92, 3.02)), () => tx(g, 'A + B', 160, y + 1, { size: 16, f: 'd', c: K.paper }));
      alpha(g, seg(t, 1.5, 1.8) * (1 - seg(t, 2.9, 3.0)), () => tx(g, L('結合'), 160, y + 52, { size: 10, f: 'm', w: 500, c: K.red }));
    }
    label(g, '接触 → 結合');
  } });

// ---------- フロスト融解アンロック ----------
function b11Lock(g, x, y, open, c) { rr(g, x - 13, y - 4, 26, 21, 4, c); g.beginPath(); g.arc(x, y - 4 - open * 7, 8, Math.PI, Math.PI * 2 - (open ? .0 : 0)); g.lineTo(x + 8, y - 4 + (open ? -7 : 0)); g.strokeStyle = c; g.lineWidth = 3; g.stroke(); }
R({ id: 'catalog-ui-material-frost-melt', dur: 4.2, ease: 'inOutQuad',
  v: ['覆いの面積 100% → 0%', '縁から中心へ縮む', '最後に錠が消える'], vEn: ['cover area 100% → 0%', 'shrinks from edges inward', 'lock goes last'], still: 1.6,
  f(g, t) {
    const x0 = 80, y0 = 50, w = 160, h = 100, cx = 160, cy = 100;
    const melting = t < 3.3, Rm = melting ? 112 * (1 - seg(t, .45, 2.1, E.inOutQuad)) : 112, ca = melting ? 1 : seg(t, 3.3, 3.8);
    // 中の情報面
    rr(g, x0, y0, w, h, 12, K.card, K.grid, 1);
    b11Lock(g, cx, cy - 8, 1, K.red);
    tx(g, 'UNLOCKED', cx, cy + 26, { size: 10, f: 'm', w: 600, c: K.red });
    rr(g, x0 + 14, y0 + 14, 40, 6, 3, K.mute); rr(g, x0 + w - 44, y0 + 14, 30, 6, 3, K.mute);
    // 霜の覆い（ノイズで縁が溶ける円マスク）
    if (Rm > .5) {
      const pts = []; for (let i = 0; i < 72; i++) { const a = i / 72 * TAU, rr2 = Rm * (1 + (noise2(Math.cos(a) * 1.6, Math.sin(a) * 1.6, 3 + t * .4) - .5) * .32); pts.push([cx + Math.cos(a) * rr2, cy + Math.sin(a) * rr2 * .78]); }
      alpha(g, ca, () => {
        g.save(); rr(g, x0, y0, w, h, 12); g.clip(); poly(g, pts); g.clip();
        rr(g, x0, y0, w, h, 0, K.line); alpha(g, .35, () => rr(g, x0, y0, w, h, 0, K.mute));
        const rn = rng(11); g.strokeStyle = K.ink; g.lineWidth = 1;
        for (let k = 0; k < 16; k++) { const sx = x0 + rn() * w, sy = y0 + rn() * h, a0 = rn() * TAU; alpha(g, .28, () => { for (let j = 0; j < 6; j++) { const a = a0 + j * Math.PI / 3, l = 6 + rn() * 8; ln(g, sx, sy, sx + Math.cos(a) * l, sy + Math.sin(a) * l, K.ink, 1); ln(g, sx + Math.cos(a) * l * .55, sy + Math.sin(a) * l * .55, sx + Math.cos(a + .6) * l * .85, sy + Math.sin(a + .6) * l * .85, K.ink, 1); } }); }
        b11Lock(g, cx, cy - 8, 0, K.ink);
        tx(g, 'LOCKED', cx, cy + 26, { size: 10, f: 'm', w: 600, c: K.ink });
        g.restore();
        if (melting && Rm < 111) { g.save(); rr(g, x0, y0, w, h, 12); g.clip(); alpha(g, .7, () => poly(g, pts, null, K.ink, 1.5)); g.restore(); }
      });
    }
    rr(g, x0, y0, w, h, 12, null, K.grid, 1);
    // 覆われた面積（格子で数える）
    let n = 0, m = 0; for (let i = 0; i < 20; i++) for (let j = 0; j < 12; j++) { const px = x0 + (i + .5) * w / 20, py = y0 + (j + .5) * h / 12; m++; if (Math.hypot(px - cx, (py - cy) / .78) < Rm) n++; }
    const pct = melting ? Math.round(n / m * 100) : Math.round(100 * ca);
    label(g, 'ロック → 解除');
    tx(g, `${L('覆い')} ${pct}%`, 160, 172, { size: 10, f: 'm', w: 500, c: pct ? K.ink : K.red });
  } });

// ---------- メンブレンプレス ----------
R({ id: 'catalog-ui-material-membrane-press', dur: 4.2, spring: [180, 5, 1],
  v: ['両端は固定', '中央 36px たわむ', '離す: spring 180 / 5'], vEn: ['both ends pinned', 'center dips 36px', 'release: spring 180 / 5'], still: 1.2,
  f(g, t) {
    const xa = 56, xb = 264, y = 96, cx = 160, D = 36;
    const depth = t < 1.4 ? D * seg(t, .5, 1.0, E.inOutCubic) : D * (1 - spring(t - 1.4, 180, 5));
    const Y = x => { const u = (x - cx) / (cx - xa); return y + depth * (1 - u * u) * (1 - .25 * u * u); };
    ln(g, xa, y, xb, y, K.mute, 1, [3, 3]);
    const pts = []; for (let x = xa; x <= xb; x += 4) pts.push([x, Y(x)]);
    alpha(g, .14, () => poly(g, [[xa, y], ...pts, [xb, y]], K.red));
    g.beginPath(); pts.forEach(([x, yy], i) => i ? g.lineTo(x, yy) : g.moveTo(x, yy)); g.strokeStyle = K.red; g.lineWidth = 4; g.lineCap = 'round'; g.stroke(); g.lineCap = 'butt';
    [xa, xb].forEach(x => { rr(g, x - 6, y - 14, 12, 28, 3, K.card, K.grid, 1); circ(g, x, y, 3.5, K.ink); });
    // 指先
    const fy = t < 1.4 ? lerp(34, y + depth - 13, seg(t, .15, .5, E.inOut)) : lerp(y + D - 13, 34, seg(t, 1.4, 1.75, E.outCubic));
    const fyy = t < 1.4 && t > .5 ? y + depth - 13 : fy;
    alpha(g, t < 1.4 ? seg(t, 0, .15) : 1 - seg(t, 1.6, 1.85), () => { circ(g, cx, fyy, 11, K.ink); circ(g, cx, fyy, 11, null, K.paper, 1.5); });
    label(g, '両端固定 / 中央だけ');
    tx(g, `depth ${Math.round(depth)}px`, 160, 176, { size: 10, f: 'm', w: 500, c: Math.abs(depth) > .5 ? K.ink : K.mute });
  } });

// ---------- 砂状ステート切替 ----------
R({ id: 'catalog-ui-material-sand-dissolve', dur: 4.2, ease: 'inQuad',
  v: ['18 × 9 粒', '列ごと +60ms ＋ ゆらぎ', '落下 g = 600px/s²'], vEn: ['18 × 9 grains', '+60ms per column + jitter', 'fall g = 600px/s²'], still: 1.4,
  f(g, t) {
    const C = 18, Rw = 9, cs = 7, x0 = 160 - C * cs / 2, y0 = 66;
    // 次の状態
    rr(g, x0, y0, C * cs, Rw * cs, 8, K.card, K.grid, 1);
    circ(g, x0 + 24, y0 + 31, 11, K.green); g.beginPath(); g.moveTo(x0 + 19, y0 + 31); g.lineTo(x0 + 23, y0 + 35); g.lineTo(x0 + 30, y0 + 27); g.strokeStyle = K.paper; g.lineWidth = 2.5; g.stroke();
    rr(g, x0 + 44, y0 + 22, 62, 7, 3, K.ink); rr(g, x0 + 44, y0 + 35, 44, 6, 3, K.mute);
    // 今の状態：粒
    for (let i = 0; i < C; i++) for (let j = 0; j < Rw; j++) {
      const id = i * 31 + j * 7, ts = .5 + i * .06 + hash(id) * .22, tau = t - ts;
      const text = (j === 3 && i > 2 && i < 13) || (j === 5 && i > 2 && i < 10);
      const reform = seg(t, 3.3 + i * .02, 3.55 + i * .02);
      let x = x0 + i * cs, y = y0 + j * cs, a = 1;
      if (t < 3.3) {
        if (tau > -.15 && tau < 0) x += Math.sin(t * 90 + id) * .6;
        if (tau > 0) { y += 300 * tau * tau; x += (hash(id + 3) - .5) * 36 * tau; a = 1 - seg(tau, .25, .6); }
      } else a = reform;
      if (a <= 0) continue;
      const fell = tau > 0 && t < 3.3, sz = fell ? cs - 1.5 : cs;
      alpha(g, a, () => rr(g, x, y, sz, sz, fell ? 1 : 0, text ? K.paper : K.red));
      if (!text && hash(id + 9) > .6) alpha(g, a * .2, () => rr(g, x, y, sz, sz, 0, K.ink));
    }
    label(g, 'A → B');
    tx(g, L('列ごと +60ms'), 160, 176, { size: 10, f: 'm', w: 500, c: K.mute });
  } });

// ---------- オイルスリック選択 ----------
R({ id: 'catalog-ui-material-oil-slick', dur: 4.2, spring: [160, 14, 1],
  v: ['細い色帯 5 色が流れる', '選択領域だけ変形', '1 周 4.2s'], vEn: ['5 thin colour bands flow', 'only the selection deforms', '4.2s per cycle'], still: 1.6,
  f(g, t) {
    const x0 = 88, y0 = 36, w = 144, h = 128, rows = [58, 100, 142], ph = t / 4.2 * TAU;
    const bands = (a) => { const cols = [K.red, K.yel, K.blue, K.green, K.ink], off = fract(t / 4.2) * 40;
      for (let k = -14; k < 14; k++) { g.beginPath(); for (let x = x0 - 10; x <= x0 + w + 10; x += 6) { const yy = 100 + k * 8 + off + (x - 160) * .45 + Math.sin(x * .05 + ph) * 5; x === x0 - 10 ? g.moveTo(x, yy) : g.lineTo(x, yy); }
        g.strokeStyle = cols[((k % 5) + 5) % 5]; g.lineWidth = 2; alpha(g, a, () => g.stroke()); } };
    rr(g, x0, y0, w, h, 12, K.card, K.grid, 1);
    g.save(); rr(g, x0, y0, w, h, 12); g.clip(); bands(.07); g.restore();
    const k = spring(t - .55, 160, 14) * (1 - seg(t, 3.55, 3.95, E.inCubic));
    if (k > .01) {
      const pts = [], cx = 160, cy = rows[1], hw = 62 * (.8 + .2 * k), hh = 16 * (.6 + .4 * k);
      for (let i = 0; i < 60; i++) { const a = i / 60 * TAU, c = Math.cos(a), s = Math.sin(a), sq = Math.pow(Math.abs(c) ** 4 + Math.abs(s) ** 4, -.25), n = noise2(Math.cos(a) * 1.4 + Math.cos(ph) * .8, Math.sin(a) * 1.4 + Math.sin(ph) * .8, 5) - .5;
        pts.push([cx + c * sq * (hw + n * 10), cy + s * sq * (hh + n * 7)]); }
      alpha(g, clamp(k * 1.5), () => { g.save(); poly(g, pts, K.red); g.clip(); bands(.5); g.restore(); poly(g, pts, null, K.red, 1.5); });
    }
    rows.forEach((ry, i) => { const sel = i === 1 && k > .3; circ(g, x0 + 22, ry, 6, sel ? K.paper : K.mute); rr(g, x0 + 36, ry - 4, [64, 52, 72][i], 8, 3, sel ? K.paper : K.mute); });
    const cpx = kf(t, [[0, 280], [.1, 280], [.45, 196], [3.3, 196], [4.0, 280], [4.2, 280]], E.inOut), cpy = kf(t, [[0, 176], [.1, 176], [.45, 106], [3.3, 106], [4.0, 176], [4.2, 176]], E.inOut);
    cursor(g, cpx, cpy, t > .45 && t < .6 ? 1 : 0);
    label(g, '選択領域だけ変形');
  } });

// ---------- 磁性流体バッジ ----------
R({ id: 'catalog-ui-material-magnetic-fluid', dur: 4.2, spring: [140, 9, 1],
  v: ['長さ ∝ cos³(角度差)', '磁石の接近で伸びる', 'spring 140 / 9'], vEn: ['length ∝ cos³(angle diff)', 'grows as magnet nears', 'spring 140 / 9'], still: 1.5,
  f(g, t) {
    const cx = 124, cy = 100, r = 24;
    const mx = kf(t, [[0, 300], [.3, 300], [1.1, 226], [2.7, 226], [3.4, 300], [4.2, 300]], E.inOut);
    const k = track(t, [[0, 0], [.55, 1], [2.85, 0]], 140, 9);
    // 磁力線
    alpha(g, clamp(k) * .5, () => { for (let i = -1; i <= 1; i++) { g.beginPath(); g.moveTo(mx - 20, cy + i * 18); g.quadraticCurveTo((mx + cx) / 2, cy + i * 30, cx + r + 6, cy + i * 8); g.strokeStyle = K.mute; g.lineWidth = 1; g.setLineDash([2, 4]); g.lineDashOffset = -t * 20; g.stroke(); g.setLineDash([]); } });
    // 磁石（U 字）
    rr(g, mx - 20, cy - 34, 42, 14, 4, K.blue); rr(g, mx - 20, cy + 20, 42, 14, 4, K.blue); rr(g, mx + 8, cy - 34, 14, 68, 4, K.blue);
    rr(g, mx - 24, cy - 34, 10, 14, 3, K.ink); rr(g, mx - 24, cy + 20, 10, 14, 3, K.ink);
    // 突起
    const N = 18;
    for (let i = 0; i < N; i++) {
      const a = i / N * TAU, f = Math.max(0, Math.cos(a)) ** 3, wob = 1 + .08 * Math.sin(t * 17 + i * 1.7) * clamp(k);
      const L0 = Math.max(0, (2 + 34 * f) * k * wob), bw = .17;
      if (L0 < .5) continue;
      poly(g, [[cx + Math.cos(a - bw) * (r - 2), cy + Math.sin(a - bw) * (r - 2)], [cx + Math.cos(a) * (r + L0), cy + Math.sin(a) * (r + L0)], [cx + Math.cos(a + bw) * (r - 2), cy + Math.sin(a + bw) * (r - 2)]], K.red);
    }
    xf(g, cx + 3 * clamp(k), cy, 1 + .06 * clamp(k), 1 - .04 * clamp(k), 0, () => circ(g, 0, 0, r, K.red));
    tx(g, '3', cx + 3 * clamp(k), cy + 1, { size: 20, f: 'd', c: K.paper });
    label(g, '磁石に近い側ほど長く');
    tx(g, `dist ${Math.round(mx - cx - 24)}px`, 160, 172, { size: 10, f: 'm', w: 500, c: k > .05 ? K.ink : K.mute });
  } });

// ---------- ガラス亀裂リカバー ----------
function b11Cracks() {
  const rn = rng(7), rays = [], br = [];
  for (let i = 0; i < 7; i++) {
    const a = i / 7 * TAU + (rn() - .5) * .5, lim = Math.min(84 / Math.max(.01, Math.abs(Math.cos(a))), 54 / Math.max(.01, Math.abs(Math.sin(a)))) * (.72 + rn() * .2);
    const pts = [[160, 100]]; let x = 160, y = 100, aa = a;
    for (let k = 0; k < 4; k++) { aa = a + (rn() - .5) * .55; x += Math.cos(aa) * lim / 4; y += Math.sin(aa) * lim / 4; pts.push([x, y]); }
    rays.push(pts);
    if (i % 2 === 0) { const [bx, by] = pts[2], ba = a + (rn() > .5 ? .7 : -.7), bl = 14 + rn() * 10; br.push({ i, pts: [[bx, by], [bx + Math.cos(ba) * bl * .5, by + Math.sin(ba) * bl * .5 + 2], [bx + Math.cos(ba) * bl, by + Math.sin(ba) * bl]] }); }
  }
  return { rays, br };
}
R({ id: 'catalog-ui-material-glass-crack-recover', dur: 4.2, ease: 'outCubic',
  v: ['破損：中心 → 外へ描く', '修復：外 → 中心へ戻す', '7 本 ＋ 枝'], vEn: ['damage: draw centre → out', 'repair: retract out → centre', '7 rays + branches'], still: 1.5,
  f(g, t) {
    const { rays, br } = b11Cracks(), ti = .55, shake = t > ti ? 3 * Math.exp(-(t - ti) * 10) * Math.sin((t - ti) * 70) : 0;
    xf(g, shake, 0, 1, 1, 0, () => {
      rr(g, 70, 40, 180, 120, 12, K.card, K.mute, 1.5);
      g.save(); rr(g, 70, 40, 180, 120, 12); g.clip(); alpha(g, .07, () => { poly(g, [[110, 40], [150, 40], [100, 160], [60, 160]], K.ink); poly(g, [[170, 40], [184, 40], [134, 160], [120, 160]], K.ink); }); g.restore();
      const prog = i => seg(t, ti + i * .03, ti + .4 + i * .03, E.outCubic) * (1 - seg(t, 2.1 + (6 - i) * .03, 2.7 + (6 - i) * .03, E.inOut));
      g.lineJoin = 'round';
      rays.forEach((pts, i) => { const L0 = b11Len([pts]); b11Path(g, [pts], L0 * prog(i)); g.strokeStyle = K.red; g.lineWidth = 1.6; g.stroke(); });
      br.forEach(({ i, pts }) => { const ray = rays[i], d2 = b11Len([ray.slice(0, 3)]), Lr = b11Len([ray]), have = Lr * prog(i) - d2; if (have > 0) { b11Path(g, [pts], have * .7); g.strokeStyle = K.red; g.lineWidth = 1.2; g.stroke(); } });
      g.lineJoin = 'miter';
      const imp = seg(t, ti - .05, ti + .35);
      if (imp > 0 && imp < 1) alpha(g, 1 - imp, () => circ(g, 160, 100, 4 + imp * 26, null, K.ink, 2));
      const dm = prog(3); if (dm > .02) circ(g, 160, 100, 3 * dm, K.red);
      // 修復後の光
      const sw = seg(t, 2.85, 3.35, E.inOut);
      if (sw > 0 && sw < 1) { g.save(); rr(g, 70, 40, 180, 120, 12); g.clip(); const x = lerp(30, 300, sw); alpha(g, .35, () => poly(g, [[x, 40], [x + 16, 40], [x - 24, 160], [x - 40, 160]], K.ink)); g.restore(); }
    });
    const dmg = Math.round(seg(t, ti, ti + .58, E.outCubic) * (1 - seg(t, 2.1, 2.88, E.inOut)) * 100);
    label(g, '外へ割れる → 内へ戻る');
    tx(g, `crack ${dmg}%`, 160, 178, { size: 10, f: 'm', w: 500, c: dmg ? K.ink : K.mute });
  } });

// ---------- ネオン管ドロー ----------
function b11Neon() {
  const s = 1.15, ox = 10.5, oy = 12, P = (x, y) => [ox + x * s, oy + y * s];
  const O = []; for (let i = 0; i <= 40; i++) { const a = -Math.PI / 2 - i / 40 * TAU; O.push(P(155 + Math.cos(a) * 17, 75 + Math.sin(a) * 25)); }
  return [[P(38, 100), P(38, 50), P(70, 100), P(70, 50)], [P(118, 50), P(90, 50), P(90, 100), P(120, 100)], [P(90, 75), P(114, 75)], O, [P(190, 100), P(190, 50), P(222, 100), P(222, 50)]];
}
R({ id: 'catalog-ui-material-neon-tube-draw', dur: 4.2, ease: 'linear',
  v: ['一定速度で始点 → 終点', '描いた区間は点灯のまま', '完了でちらつき 2 回'], vEn: ['constant speed, start → end', 'drawn segments stay lit', '2 flickers on completion'], still: 2.0,
  f(g, t) {
    const subs = b11Neon(), Lt = b11Len(subs), p = seg(t, .35, 2.35, E.linear), off = 1 - seg(t, 3.55, 3.8);
    const fl = t > 2.4 && t < 2.75 ? [1, .35, 1, .5, 1, 1, 1][Math.floor((t - 2.4) / .05)] : 1;
    g.lineCap = 'round'; g.lineJoin = 'round';
    b11Path(g, subs, Lt + 1); g.strokeStyle = K.grid; g.lineWidth = 6; g.stroke();
    b11Path(g, subs, Lt + 1); g.strokeStyle = K.line; g.lineWidth = 2; g.stroke();
    if (p > 0 && off > 0) alpha(g, off * fl, () => {
      g.shadowBlur = 14; g.shadowColor = K.red;
      const head = b11Path(g, subs, Lt * p); g.strokeStyle = K.red; g.lineWidth = 4.5; g.stroke();
      g.shadowBlur = 0; g.shadowColor = 'transparent';
      b11Path(g, subs, Lt * p); g.strokeStyle = K.ink; g.lineWidth = 1.2; alpha(g, .7, () => g.stroke());
      if (p < 1 && head) { g.shadowBlur = 10; g.shadowColor = K.red; circ(g, head[0], head[1], 3.5, K.ink); g.shadowBlur = 0; g.shadowColor = 'transparent'; }
    });
    g.lineCap = 'butt'; g.lineJoin = 'miter';
    label(g, 'start → end');
    tx(g, `${Math.round(p * 100 * (off > 0 ? 1 : 0))}%`, 160, 176, { size: 10, f: 'm', w: 500, c: p > 0 && p < 1 ? K.ink : K.mute });
  } });

