    g.restore();
    rr(g, x0, y0, w, h, 14, null, K.ink, 1);
    const cx = kf(t, [[0, 262], [.1, 262], [.5, px], [1.0, px], [1.6, 262], [3.6, 262]], E.inOut), cy = kf(t, [[0, 178], [.1, 178], [.5, py], [1.0, py], [1.6, 178], [3.6, 178]], E.inOut);
    cursor(g, cx, cy, t > t0 - .1 && t < t0 + .12 ? 1 : 0);
