// 4. ワード重力落下
function b12Fall(dt, D) {
  // 自由落下 → 跳ね高さ 26 → 8 → 2px。返り値 [床からの高さ, 着地の衝撃 0..1]
  const T0 = .46, a = 2 * D / (T0 * T0), hs = [26, 8, 2];
  if (dt <= 0) return [D, 0];
  if (dt < T0) return [D - a * dt * dt / 2, 0];
  let s = dt - T0, imp = 1;
  for (const h of hs) { const T = 2 * Math.sqrt(2 * h / a); if (s < T) { const v0 = Math.sqrt(2 * a * h), y = v0 * s - a * s * s / 2; return [y, Math.max(0, 1 - s / .07) * imp]; } s -= T; imp *= Math.sqrt(h / (h === 26 ? D : 26)) * 1.1; }
  return [0, Math.max(0, 1 - s / .07) * imp];
}
