      if (t > tc && t < tc + .25 && !back) { const q = seg(t, tc, tc + .25, E.outCubic); for (let k = -2; k <= 2; k++) { const a = k * .45, r0 = 8 + q * 12, r1 = r0 + 8 * (1 - q); ln(g, bx0 - hw / 2 + Math.cos(Math.PI + a) * -r0 + 2, 126 + Math.sin(a) * r0, bx0 - hw / 2 + Math.cos(Math.PI + a) * -r1 + 2, 126 + Math.sin(a) * r1, K.yel, 1.5); } }
