// 16. 文字ヒンジフリップ
function b12Hinge(g, c, hx, hy, size, th, col) {
  // 上端の蝶番（rotateX）。横帯に分けて遠近で幅を変える
  const S = 12, capH = size * .74, F = 260, sh = capH / S, cth = Math.cos(th), sth = Math.sin(th);
  for (let j = 0; j < S; j++) {
    const d0 = j * sh, d1 = (j + 1) * sh, dm = (d0 + d1) / 2, k = F / (F + dm * sth), y0 = d0 * cth * F / (F + d0 * sth), y1 = d1 * cth * F / (F + d1 * sth);
    if (Math.abs(y1 - y0) < .05) continue;
    g.save(); g.beginPath(); g.rect(hx - size, hy + Math.min(y0, y1) - .3, size * 2, Math.abs(y1 - y0) + .6); g.clip();
    g.translate(hx, hy + y0); g.scale(k, (y1 - y0) / sh); g.translate(0, -d0);
    drawChar(g, c, 0, capH, size, col); g.restore();
  }
}
