R({ id: 'catalog-kinetic-type-stroke-catchup', dur: 4.2, ease: 'linear', still: 3,
  v: ['stroke-dashoffset 1 → 0', '一定速度（linear）', '2.2s'],
  vEn: ['stroke-dashoffset 1 → 0', 'constant speed (linear)', '2.2s'],
  f(g, t) {
    const { pts, len, total } = b12Path, p = seg(t, .3, 2.5, E.linear), d = total * p, out = seg(t, 3.5, 3.9, E.inOut);
    g.lineCap = 'round'; g.lineJoin = 'round';
    g.beginPath(); pts.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y)); g.strokeStyle = K.grid; g.lineWidth = 1.5; g.setLineDash([2, 4]); g.stroke(); g.setLineDash([]);
    for (let k = 0; k <= 10; k++) { const [x, y] = b12At(total * k / 10); circ(g, x, y, 1.8, k / 10 <= p * (1 - out) + 1e-6 ? K.mute : K.grid); }
    alpha(g, 1 - out, () => {
      g.beginPath(); g.moveTo(...pts[0]); for (let i = 1; i < pts.length && len[i] <= d; i++) g.lineTo(...pts[i]); if (d > 0) g.lineTo(...b12At(d));
      g.strokeStyle = K.red; g.lineWidth = 4; g.stroke();
      if (p > 0 && p < 1) { const [x, y] = b12At(d); circ(g, x, y, 7, null, K.red, 1.2); circ(g, x, y, 3, K.ink); }
    });
    g.lineCap = 'butt'; g.lineJoin = 'miter';
    circ(g, pts[0][0], pts[0][1], 3, K.blue);
    tx(g, `${Math.round(d * (1 - out))} / ${Math.round(total)}px`, 160, 172, { size: 10, f: 'm', w: 500, c: K.mute });
    label(g, '始点から一定速度でなぞる');
  } });

