    const band = seg(t, .3, .9, E.outExpo) * (1 - seg(t, 3.55, 3.9, E.inExpo)), txt = seg(t, .65, 1.05, E.outCubic) * (1 - seg(t, 3.4, 3.6, E.inCubic)), tail = seg(t, 1.05, 1.5, E.outBack) * (1 - seg(t, 3.25, 3.5, E.inCubic));
    const bw = fw * band, L0 = cx - bw / 2, R0 = cx + bw / 2, tl = 44 * tail, top = cy - bh / 2;
    if (tail > 0) {
      [-1, 1].forEach(sd => {
        const e = sd < 0 ? L0 : R0, inner = e - sd * fold * Math.min(1, tail * 2), outer = e + sd * tl, y0 = top + drop, y1 = top + bh + drop;
        alpha(g, .6, () => poly(g, [[inner, y0], [outer, y0], [outer - sd * Math.min(12, tl * .3), (y0 + y1) / 2], [outer, y1], [inner, y1]], K.red));
        poly(g, [[e, top + bh], [inner, top + bh], [e, y1]].map(([x, y]) => [x, y]), K.paper);
        alpha(g, .35, () => poly(g, [[e, top + bh], [inner, top + bh], [e, y1]], K.red));
      });
    }
    if (bw > 1) rr(g, L0, top, bw, bh, 2, K.red);
    clip(g, L0, top, bw, bh, () => alpha(g, txt, () => tx(g, 'MAKE IT MOVE', cx, cy + 1 + (1 - txt) * 22, { size: 18, f: 'd', c: K.paper })));
    tx(g, ['①', '②', '③'][tail > .05 ? 2 : txt > .05 ? 1 : 0], cx, 156, { size: 10, f: 'm', w: 500, c: K.mute });
