    const hA = 40 * k * pA, hB = 64 * k * pB, d = seg(t, 1.4, 1.8, E.outCubic) * (1 - out), red = seg(t, 1.7, 2.0) * (1 - out);
    label(g, 'Δ = 64 − 40');
