    alpha(g, pB * 4, () => tx(g, String(Math.round(64 * pB)), 201, by - hB - 10, { size: 13, f: 'm', w: 600 }));
    tx(g, 'A', 111, by + 11, { size: 10, f: 'm', w: 600, c: K.mute }); tx(g, 'B', 201, by + 11, { size: 10, f: 'm', w: 600, c: K.mute });
    if (d > 0) ln(g, 134, by - 80, lerp(134, 236, d), by - 80, K.mute, 1, [3, 3]);
    const br = seg(t, 1.8, 2.15, E.outCubic) * (1 - out);
    if (br > 0) { ln(g, 238, by - 80, 238, lerp(by - 80, by - 128, br), K.red, 1.5); ln(g, 234, by - 80, 242, by - 80, K.red, 1.5); if (br >= 1) ln(g, 234, by - 128, 242, by - 128, K.red, 1.5); }
    const s = seg(t, 2.1, 2.45, E.outBack) * (1 - out);
