    tx(g, '−', 32, y, { size: 18, f: 'm', w: 700, c: K.yel }); tx(g, '+', 288, y, { size: 18, f: 'm', w: 700, c: K.red });
    const gh = seg(t, .45, .7) * (1 - seg(t, 3.2, 3.4)); alpha(g, gh, () => poly(g, [[X(-.3) - 6, y - 18], [X(-.3) + 6, y - 18], [X(-.3), y - 9]], null, K.mute, 1));
